// ==========================================
// ★ K 의 방 — B등급 직업 갈림길 · 보정
// ==========================================
//
//   보정 — 비 오는 밤, 쫓기는 일행을 하나로 세운다. 박을 맞추고, 판을 짜고, 덧입히고, 세고, 놓는다.
//     북잡이 drummer · 전술가 tactician · 부여술사 enchanter (마력) · 분대장 squad (무력) · 진법가 formation (내공)

// ── 북잡이 ────────────────────────────────
kJob('drummer', 'B', [

{ at:'B', t:'빗소리 — 묻힌 박',
  x:`비가 지붕을 두드린다. 사방이 박이다. 너무 많은 박이다.<br><br>
    일행 걸음이 흐트러졌다. 빗소리에 제 발소리가 안 들리니 다들 제멋대로 딛는다.<br>
    북잡이는 박이 너무 많으면 박이 없는 것과 같다는 걸 안다.<br><br>
    북은 칠 수 없다. 서두르지 않는 발소리 하나가 아까부터 뒤를 따라온다.`,
  o:[
    { l:'① 앞사람 어깨에 손끝으로 박을 찍는다.', k:'fix', dc:20, wake:1,
      ok:`앞사람 어깨에 검지를 얹었다. 톡. 쉬고. 톡.<br><br>앞사람이 그 박에 발을 맞춘다. 그 사람이 제 앞사람 어깨에 손을 얹는다. 박이 손에서 어깨로, 어깨에서 손으로 줄을 타고 맨 앞까지 갔다.<br>빗속에서 다섯이 한 발로 걸었다. 따라오던 발소리가 갈림목에서 엉뚱한 쪽으로 꺾였다. 흩어진 발을 쫓던 귀다. 하나로 걷는 발은 못 들었다.<br><br>소리 없는 박이 북보다 멀리 갔다. 박은 귀로만 치는 줄 알았다. 살로도 친다. 손끝이 그걸 먼저 알았다.`,
      ng:`어깨를 짚는 순간 앞사람이 소스라쳐 돌아본다.<br><br>빗속에서 등 뒤에 얹힌 손은 다른 것의 손이다. 그쪽 팔꿈치가 이쪽 턱을 쳤다.<br>둘이 엉켜 넘어지는 소리가 빗소리를 뚫었다. 따라오던 발소리가 멈췄다. 그리고 빨라졌다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 빗소리 속에서 박 하나를 골라 따른다.', k:'sense', dc:19,
      ok:`빗소리를 가려 들었다. 지붕을 치는 비, 홈통을 타는 비, 웅덩이에 떨어지는 비.<br><br>홈통 끝 낙숫물만 박이 고르다. 똑, 쉼, 똑. 그 박을 손짓으로 짚어 줬다. 다들 낙숫물에 발을 맞췄다.<br><br>남의 박을 빌렸다. 비가 그치면 끊기는 박이다. 오늘 밤은 안 그친다.`,
      ng:`고르던 박이 중간에 바뀐다. 똑, 똑똑, 쉼.<br><br>낙숫물이 아니었다. 누군가 홈통 밑에서 손가락으로 양철을 두드리고 있었다. 이쪽 박을 따라서.<br>다들 얼어붙었다. 그 박이 조금씩 가까워진다.`,
      win:{ exp:15, dream:1, mind:5 }, lose:{ mind:-14, spirit:-12 } }
  ] },

{ at:'B1', t:'3번 창고 — 대걸레 박',
  x:`창고 안쪽에서 대걸레가 바닥을 민다. 쓱. 쓱. 쓱. 쉼. 양동이에 걸레 짜는 소리. 다시 쓱.<br><br>
    회색 비옷이다. 서두르지 않는다.<br>
    북잡이 귀에는 그 소리가 박으로 들린다. 셋 밀고 한 번 쉰다. 쉴 때 고개를 든다.<br><br>
    쪽문까지 상자 더미 사이로 서른 걸음. 발소리를 숨길 데가 필요하다.`,
  o:[
    { l:'① 쓱 소리 안에 걸음을 넣는다.', k:'fix', dc:21,
      ok:`손바닥을 펴 일행에게 보였다. 쓱에 한 걸음. 쓱에 한 걸음. 쉼에 멈춤.<br><br>대걸레가 바닥을 밀 때마다 다섯이 같이 디뎠다. 걸레 소리가 발소리를 덮는다. 쉼마다 섰다. 그때마다 비옷이 고개를 든다. 아무것도 움직이지 않는다.<br><br>서른 걸음을 열 번의 쉼으로 왔다. 쪽문에서 돌아봤다. 비옷이 대걸레를 세우고 바닥을 내려다본다. 젖은 발자국이 박 간격으로 찍혀 있다. 고르게.`,
      ng:`일곱째 쓱에서 비옷이 박을 바꿨다. 쓱. 쉼 없이 또 쓱.<br><br>쉼을 기다리던 발 하나가 이미 바닥에서 떨어져 있었다. 고무장화가 돌아섰다.<br>상자 뒤로 몸을 던졌다. 팔꿈치가 못에 찢겼다. 대걸레 소리가 다시 시작됐다. 이번엔 이쪽으로 민다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 상자 뒤에 엎드려 지나가길 기다린다.', k:'hide', dc:20,
      ok:`건어물 상자 뒤에 엎드렸다. 짠 냄새가 코를 찌른다.<br><br>쓱, 쓱. 대걸레가 상자 앞을 지나간다. 장화 끝이 손가락 한 뼘 앞에서 섰다가 갔다.<br>북잡이는 쉼도 박이라는 걸 안다. 제일 긴 쉼을 쉬었다.<br><br>일어나니 상자 틈에 말린 고기 꾸러미가 끼어 있다. 비옷이 닦지 않고 지나간 자리다. 셀 것은 세고 남길 것은 남긴다. 무엇을 위해 남겼는지는 모른다.`,
      ng:`엎드린 자리에 물이 고여 있었다. 비옷이 아직 안 닦은 자리다.<br><br>대걸레가 그 물을 밀러 온다. 걸레 끝이 이쪽 소매를 쓸었다. 걸레가 멈췄다.<br>한참 뒤에 다시 움직였다. 숨을 참은 시간이 길었다. 소매 끝이 아직도 젖은 손에 잡혀 있는 것 같다.`,
      win:{ exp:14, dream:1, item:'말린 고기' }, lose:{ mind:-14, spirit:-14 } },
    { l:'③ 북을 한 번 울려 박을 끊는다.', k:'break', dc:21,
      doom:{ title:'박을 받아 친 청소부', what:'대걸레 쪽으로 끌려갑니다', dc:17, sec:55,
        text:`북채를 들어 한 번 쳤다. 둥.<br><br>대걸레가 멈췄다. 비옷이 고개를 든다. 그리고 대걸레 자루로 바닥을 한 번 친다. 둥과 같은 높이로.<br>이쪽 박을 받아 친 것이다. 다음 박은 저쪽이 정한다. 장화가 다가온다. 쓱, 쓱.<br><br>젖은 걸레가 발목을 감는다. 바닥이 미끄럽다. 상자 사이로 끌려간다.`,
        dieText:`새벽에 3번 창고 바닥은 깨끗했다.<br><br>안쪽 구석에 북 하나가 엎어져 있다. 가죽이 젖었다.<br>양동이 물은 한 번 갈았다. 칠판의 다섯 옆에 분필로 줄이 하나 그어졌다.` },
      ok:`북을 먼 상자 더미 위에 엎어 놓고 테를 한 번 쳤다. 딱.<br><br>소리가 상자 사이를 튀어 엉뚱한 구석에서 울렸다. 비옷이 그쪽으로 간다. 서두르지 않고.<br>그사이 다섯이 쪽문으로 빠졌다. 맨 끝에서 북을 걷어 왔다.<br><br>쪽문 밖에서 들었다. 그 구석에서 대걸레 자루가 바닥을 한 번 친다. 딱. 이쪽이 친 높이 그대로. 대답이다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'B2', t:'7층 — 계수기 박',
  x:`정각이다. 딸깍. 간호사가 걸음마다 계수기를 누른다.<br><br>
    북잡이는 그 딸깍이 걸음에 맞지 않는다는 걸 들었다. 걸음보다 반 박 늦다. 엄지가 눈보다 늦다. 본 다음에 누른다.<br>
    지난 정각에 일행 하나가 대답을 늦게 했다. 그때 딸깍이 두 번 났다.<br><br>
    이번에도 하나가 둘로 세어지면 다음 정각에 하나를 데리러 온다.`,
  o:[
    { l:'① 대답할 박을 정해 준다.', k:'fix', dc:21,
      ok:`침대 난간에 손가락을 얹고 일행이 보게 쳤다. 소리 없이. 이름이 불리면 셋째 박에 대답.<br><br>간호사가 이름을 부른다. 하나, 둘, 셋. "네." 딸깍. 한 번.<br>다섯이 다 셋째 박에 대답했다. 딸깍도 다섯 번이었다.<br><br>간호사가 화이트보드 앞에서 숫자를 고친다. 지우지 않고 그 위에 덧쓴다. 같은 숫자다. 맞았다.`,
      ng:`셋째 박을 기다리던 사람이 둘째 박에 대답했다. 겁은 박보다 빠르다.<br><br>딸깍. 간호사가 고개를 갸웃한다. 엄지가 한 번 더 내려간다. 딸깍.<br>다음 정각이 오기 전에 누군가 그 침대 명패를 바꿔 걸었다. 이쪽은 밤새 그 명패를 봤다.`,
      win:{ exp:18, dream:2, spirit:5 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 반 박 늦은 틈에 복도로 빠져나간다.', k:'evade', dc:21,
      ok:`딸깍이 반 박 늦다. 그 반 박이면 문 하나를 지난다.<br><br>간호사가 옆 침대를 볼 때 문틈으로 빠졌다. 눈이 지나간 다음, 엄지가 누르기 전. 딸깍은 비어 가는 이불을 셌다.<br><br>복도는 길다. 등 뒤로 계수기 소리가 따라오지 않는다. 반 박은 남들은 못 듣는 틈이다.`,
      ng:`반 박을 셌는데 간호사가 이번에는 엄지를 먼저 눌렀다.<br><br>딸깍. 문틈에 걸친 이쪽 어깨가 세어졌다. 방 밖에서.<br>간호사가 돌아본다. 눈꺼풀이 안 움직이는 눈이다. 침대로 돌아오는 내내 그 눈이 등에 붙어 있었다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B3', t:'9호차 — 이음매 박',
  x:`덜컹. 덜컹. 열차가 레일 이음매를 넘는다.<br><br>
    시계가 멈췄다. 손목시계도, 객차 끝 벽시계도. 01:12에서 움직이지 않는다.<br>
    북잡이는 이음매 소리가 박이라는 걸 안다. 레일 한 칸 길이는 같다. 박이 빨라지면 열차가 빨라진 것이다.<br><br>
    박이 아까보다 빠르다. 종착 04:44. 지금이 몇 시인지 아무도 모른다.`,
  o:[
    { l:'① 이음매를 세어 시계를 만든다.', k:'fix', dc:21, wake:1,
      ok:`무릎 위에 손가락을 얹고 이음매를 셌다. 덜컹 하나에 손가락 하나. 숨 한 번에 덜컹 둘.<br><br>세다 보니 박이 숫자가 됐다. 숨 육십 번이 분 하나다. 지나간 역 불빛 사이를 세면 역 사이가 나온다.<br><span style="color:#d4af37;">"두 시 십 분쯤이야. 종착까지 두 시간 반."</span><br><br>틀릴 수도 있다. 그런데 세는 손이 멈추지 않는다. 귀가 제 혼자 센다. 박을 따라가던 귀가 박으로 시간을 재기 시작했다. 이 열차에서 시계는 이제 필요 없다.`,
      ng:`세는데 이음매 박이 엇간다. 덜컹, 덜컹덜컹.<br><br>이음매가 아니다. 객차 지붕 위를 누가 걷는다. 레일과 같은 박으로 걸으려다 한 번 틀렸다.<br>셈은 다 무너졌다. 지붕 위 걸음이 이쪽 좌석 바로 위에서 멎었다. 천장이 한 번 울렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 덜컹에 맞춰 통로를 걷는다.', k:'evade', dc:20,
      ok:`덜컹 할 때 열차가 흔들린다. 흔들릴 때 디디면 발소리가 묻힌다.<br><br>덜컹에 한 걸음. 흔들림을 타고 통로를 지났다. 잠든 사람들 중 아무도 고개를 안 들었다.<br><br>앞 칸 문에 닿았다. 북잡이 걸음은 늘 무엇인가의 박 안에 있다. 오늘은 쇠바퀴의 박이다.`,
      ng:`덜컹에 디딘 발이 젖은 바닥에서 미끄러졌다.<br><br>옆 좌석 팔걸이를 짚었다. 잠든 사람 손등이었다. 차다.<br>그 손이 뒤집혀 이쪽 손목을 쥔다. 떼어 내는 사이 이음매 열둘을 지났다. 손목에 손톱자국이 남았다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B', t:'젖은 가죽 — 끈을 조인다',
  x:`비를 맞고 뛰었다. 북이 젖었다.<br><br>
    쳐 보니 퍽. 가죽이 늘어져 소리가 안 선다. 북잡이에게 늘어진 북은 쉰 목소리다.<br>
    말릴 불은 없다. 불을 피우면 들킨다.<br><br>
    북 옆구리의 가죽 끈은 아직 질기다.`,
  o:[
    { l:'① 끈을 한 칸씩 다시 조인다.', k:'fix', dc:20,
      ok:`끈 매듭을 풀고 한 칸씩 당겼다. 당기고 튕겨 보고 또 당기고.<br><br>젖은 가죽은 당기면 찢어진다. 손끝에 쨍 하는 떨림이 오기 직전에서 멈췄다. 일곱 칸.<br>쳐 보니 소리가 섰다. 낮고 짧다. 멀리 안 가고 일행 귀까지만 간다.<br><br>비 오는 밤에 맞는 소리다. 젖은 북은 젖은 대로 쓴다.`,
      ng:`여섯째 칸에서 가죽이 쩍 갈라졌다.<br><br>손톱만 한 틈이다. 쳐 보니 소리가 그 틈으로 샌다. 피식.<br>끈을 당기던 손가락이 끈에 베였다. 피가 빗물에 섞여 북 테를 타고 흘렀다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, mind:-12 } },
    { l:'② 품에 넣고 체온으로 말린다.', k:'steady', dc:19,
      ok:`윗옷 안에 북을 넣고 웅크렸다. 가죽이 배에 닿는다. 차다.<br><br>한 시진을 그렇게 앉아 있었다. 이가 덜덜 떨렸다. 북이 이쪽 열을 다 먹었다.<br>꺼내 보니 가죽이 팽팽하다. 이쪽 손은 떨린다.<br><br>북이 살면 손은 따라 산다. 북잡이는 늘 그 순서다.`,
      ng:`품에 넣은 북에서 물이 배어 나와 배를 적셨다.<br><br>가죽은 덜 말랐고 이쪽은 다 젖었다. 이가 부딪는 소리가 북보다 크다.<br>그 소리가 골목 끝까지 갔는지, 끝에서 누가 걸음을 멈췄다.`,
      win:{ exp:14, spirit:6 }, lose:{ hp:-22, spirit:-12 } }
  ] },

{ at:'B', t:'쫓기는 골목 — 다섯 발, 한 발',
  x:`뒤에서 뛰는 소리가 난다. 여럿이다. 일행도 뛴다.<br><br>
    뛰는 다섯의 발이 제각각이다. 북잡이 귀에는 그게 다 들린다. 쫓는 쪽 귀에도 다 들릴 것이다.<br>
    숨이 거칠다. 박 없이 뛰는 사람은 먼저 지친다.<br><br>
    골목은 길다. 비에 젖은 판자 바닥이다.`,
  o:[
    { l:'① 다섯 발을 한 발로 묶는다.', k:'fix', dc:21, wake:1,
      ok:`<span style="color:#d4af37;">"하나, 둘."</span> 낮게 박을 불렀다. 둘에 왼발.<br><br>다섯 발이 한꺼번에 판자를 찼다. 한 사람 발소리다. 뒤쫓던 소리가 갈림목에서 머뭇거렸다. 다섯을 쫓던 귀가 하나를 들으면 헷갈린다.<br>숨도 박에 넣었다. 들이쉬는 데 둘, 내쉬는 데 둘. 다섯이 같은 숨을 쉬었다.<br><br>골목 끝에서 보니 아무도 안 지쳤다. 이쪽도. 입으로 부른 박이 다리에 남아 있다. 북을 안 쳤는데 북을 친 것보다 오래 남는다.`,
      ng:`박을 부르는 순간 목소리가 골목 끝까지 울렸다.<br><br>뒤쫓는 발소리가 그 목소리로 방향을 고쳤다.<br>판자 하나가 부러지며 발목이 빠졌다. 다들 이쪽을 끌어내느라 멈췄다. 멈춘 사이 등 뒤가 가까워졌다.`,
      win:{ exp:22, dream:2, mind:5 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 제일 빠른 사람 발에 박을 맡긴다.', k:'bond', dc:20,
      ok:`제일 빠른 사람 등을 가리켰다. 저 발을 따라.<br><br>다들 그 사람 발에 맞췄다. 이쪽은 맨 뒤에서 처지는 발을 손바닥으로 밀었다.<br>박은 내가 안 쳐도 된다. 세워 주기만 하면 된다.<br><br>골목을 빠져나왔다. 앞선 사람이 돌아본다. 제 발이 박이었다는 걸 모른다.`,
      ng:`제일 빠른 사람이 제일 먼저 지쳤다.<br><br>앞이 멈추자 줄이 뒤에서 부딪쳤다. 셋이 같이 넘어졌다.<br>판자 모서리에 무릎이 찍혔다. 일어나는 동안 뒤쫓는 소리가 둘로 갈라져 양쪽 골목을 막았다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B1', t:'냉동 창고 — 갈고리 레일',
  x:`천장 레일이 끼익 운다. 매달린 고기가 한 칸씩 움직인다. 빈 갈고리가 머리 높이로 지나간다.<br><br>
    북잡이는 레일 소리를 셌다. 끼익, 쉼 둘, 끼익. 안쪽 어둠에서 누가 사슬을 당기는 박이다. 사람 손이다. 사람 손은 지친다.<br><br>
    입김이 하얗다. 손가락이 북채에 들러붙는다. 건너편 문까지 갈고리 줄 셋을 지나야 한다.`,
  o:[
    { l:'① 쉼 둘 사이로 한 줄씩 건넌다.', k:'fix', dc:21,
      ok:`끼익에 멈추고 쉼에 건넜다. 한 줄, 두 줄.<br><br>셋째 줄 앞에서 박이 늘어졌다. 쉼 둘이 쉼 셋이 됐다. 사슬 당기는 손이 지쳤다. 늘어진 박은 넓은 틈이다. 다섯이 다 건넜다.<br><br>등 뒤에서 갈고리 하나가 허공을 찍었다. 마지막 사람이 지나간 자리다. 손은 지쳐도 한 번은 빨라진다.`,
      ng:`셋째 줄에서 박이 당겨졌다. 끼익이 쉼 하나 만에 왔다.<br><br>갈고리가 어깨 천을 꿰었다. 몸이 들린다. 옷을 찢고 빠져나왔다.<br>살갗도 같이 찢겼다. 찬 공기에 피가 금방 엉긴다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-10 } },
    { l:'② 매달린 고기 사이에 섞여 레일을 탄다.', k:'hide', dc:21,
      ok:`고기 사이에 들어가 갈고리 사슬을 쥐었다. 발을 들었다. 고기와 같이 흔들렸다.<br><br>입김을 참았다. 고기는 숨을 안 쉰다. 옆 고기에서 하얀 입김이 한 줄 새어 나온다. 이쪽 것이 아니다.<br>레일이 다섯 칸을 옮겨 줬다. 문 앞에서 내려서며 고기 한 덩이를 끊어 왔다. 얼었다. 짐승 고기다. 냄새로 안다.<br><br>돌아보지 않았다. 옆 고기도 내려서는 소리가 났다.`,
      ng:`레일이 갑자기 멈췄다. 사슬을 쥔 채로 매달려 한 시진.<br><br>손가락이 하얗게 얼었다. 사슬 당기는 손이 쉬는 것이다. 쉬는 박이 이렇게 길 줄 몰랐다.<br>다시 움직일 때 손이 안 펴졌다. 떨어지며 바닥에 무릎을 찧었다.`,
      win:{ exp:15, dream:1, item:'짐승 고기' }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B2', t:'처치실 — 따라 뛰는 모니터',
  x:`빈 처치실에서 모니터가 운다. 삑. 삑. 침대는 비었다. 선은 아무 데도 안 이어졌다.<br><br>
    북잡이는 그 박을 안다. 제 심장 박이다. 문 앞에 서자 빨라졌다. 한 걸음 물러서니 느려졌다.<br><br>
    복도 끝에서 딸깍 소리가 다가온다. 모니터가 빨라지면 저쪽이 들을 것이다.`,
  o:[
    { l:'① 제 심장을 느린 박으로 누른다.', k:'steady', dc:21,
      ok:`북잡이는 남의 박을 늦출 줄 안다. 제 것도 늦춘다. 넷 들이쉬고 여섯 내쉬었다.<br><br>삑……. 삑……. 모니터가 따라 느려졌다. 자는 사람 박이다.<br>딸깍 소리가 문 앞을 지나간다. 들여다보지 않는다. 잠든 침대는 다시 셀 필요가 없다.<br><br>지나간 뒤에야 숨을 크게 쉬었다. 모니터가 한 번 크게 울었다.`,
      ng:`늦추려 할수록 빨라졌다. 늦추려는 생각이 겁을 부른다. 삑삑삑.<br><br>딸깍 소리가 멈췄다. 문이 열렸다. 마스크가 들여다본다.<br>간호사가 모니터 전원을 끄고 나간다. 끄는 순간 이쪽 가슴이 한 번 텅 비었다. 다시 뛰기까지 한참 걸렸다.`,
      win:{ exp:16, dream:2, spirit:5 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 모니터 전원을 뽑는다.', k:'break', dc:20,
      ok:`벽에서 플러그를 뽑았다. 화면이 꺼졌다. 박이 멎었다.<br><br>이쪽 심장은 그대로 뛴다. 손바닥을 가슴에 대고 확인했다.<br>딸깍이 문 앞을 지나간다. 셀 박이 없는 방은 그냥 지나간다.`,
      ng:`뽑는 순간 모니터가 길게 울었다. 삐———. 심장이 멎은 소리다.<br><br>복도 끝에서 발소리가 뛰어온다. 여기서 처음 듣는 서두르는 발소리다.<br>침대 밑으로 굴러 들어갔다. 바퀴에 손등이 깔렸다. 비명을 이로 물었다.`,
      win:{ exp:14, dream:1 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B3', t:'식당칸 — 빌린 걸음',
  x:`식당칸 통로를 다섯이 걸어간다. 다섯의 걸음이 다 다르다. 북잡이는 다 안다. 누가 끌고 누가 튀는지.<br><br>
    하나가 이상하다. 걸음이 박에 맞는다. 너무 맞는다.<br>
    왼발이 늘 반 박 늦던 사람이다. 지금은 안 늦는다.<br><br>
    등받이에 긁혀 있던 글씨가 생각난다. 옆에 선 얼굴을 믿지 마.`,
  o:[
    { l:'① 일행 걸음을 하나씩 짚어 본다.', k:'fix', dc:21, wake:1,
      ok:`걷다 말고 손가락으로 식탁을 쳤다. 늘 치던 박.<br><br>넷은 저마다 버릇대로 받았다. 하나는 끌고, 하나는 서두르고. 하나만 이쪽 박을 정확히 받았다. 흠 없는 발이다.<br>그 얼굴을 봤다. 일행 얼굴로 웃는다. 그것이 식당칸 문 쪽으로 물러났다. 진짜는 뒤 칸 화장실에 갇혀 문을 두드리고 있었다. 꺼내 오니 왼발이 반 박 늦다. 그게 그 사람이다.<br><br>박을 듣던 귀가 박의 흠을 듣기 시작했다. 흠이 그 사람이다. 귀가 그걸 외웠다.`,
      ng:`짚어 보는데 그 하나가 먼저 식탁을 쳤다. 이쪽 버릇 그대로. 셋째 박을 조금 끄는 것까지.<br><br>일행이 누가 진짜인지 몰라 둘을 번갈아 봤다. 한참 뒤에야 그것이 물러났다.<br>그 뒤로 일행 하나가 이쪽을 끝까지 믿지 않았다. 이쪽 박에 반 박씩 늦게 걸었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 엇박을 쳐서 따라 하게 만든다.', k:'gaze', dc:20,
      ok:`일부러 틀린 박을 쳤다. 아무도 못 따라올 엇박.<br><br>넷은 어리둥절했다. 하나가 따라 쳤다. 정확히.<br>남의 얼굴을 쓰는 것은 남을 다 따라 한다. 틀린 것까지.<br><br>그것이 들킨 걸 알고 통로 끝으로 물러났다. 다섯째 자리가 비었다. 진짜 다섯째는 뒤 칸에서 찾았다.`,
      ng:`엇박을 쳤는데 다섯 다 어리둥절했다. 아무도 따라 치지 않았다.<br><br>그것은 생각보다 영리하다. 틀린 것은 안 배운다.<br>그 뒤로 일행은 이쪽이 식탁을 칠 때마다 이쪽 얼굴을 한 번씩 봤다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-14, spirit:-14 } },
    { l:'③ 그 하나 옆에 붙어 숨을 듣는다.', k:'sense', dc:21,
      doom:{ title:'같은 박으로 쉬는 손님', what:'얼굴 바뀌는 손님에게 끌려갑니다', dc:17, sec:50,
        text:`옆에 붙어 숨을 들었다. 숨이 이쪽과 같다. 박까지. 이쪽 숨을 배우고 있다.<br><br>그 손이 이쪽 손목을 잡는다. 다정하게. 일행 눈에는 둘이 나란히 걷는다. 연결 통로 쪽으로.<br><br>통로 문이 열린다. 빗소리와 쇠바퀴 소리가 쏟아진다. 발밑 철판이 덜컹 비었다.`,
        dieText:`다음 칸에서 다섯이 모였다. 맞는 숫자다.<br><br>북잡이가 식탁을 쳤다. 박이 정확하다. 흠 하나 없이.<br>일행 하나가 고개를 갸웃했다. 그 북잡이는 원래 셋째 박을 조금 끌었다.` },
      ok:`숨을 들었다. 박이 이쪽과 똑같다. 배우고 있다.<br><br>그 순간 숨을 일부러 멈췄다. 그것도 멈췄다. 한 박 늦게. 배우는 쪽은 늘 늦다.<br>손목을 잡으려던 손이 허공을 쥐었다. 일행을 끌고 반대쪽 칸으로 나왔다.<br><br>문을 닫자 유리 너머에서 그것이 이쪽 얼굴로 웃었다. 숨을 쉬는 박까지 이쪽 것이었다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'B', t:'갈라진 일행 — 벽 너머 박',
  x:`문이 닫히면서 일행이 둘로 갈렸다. 셋은 이쪽, 둘은 벽 너머.<br><br>
    소리를 지를 수 없다. 북을 크게 칠 수도 없다. 벽은 얇은 합판이다. 손가락 소리는 넘어간다.<br><br>
    북잡이는 저쪽 둘도 이쪽 박을 안다고 믿기로 했다. 며칠 내내 이쪽 박에 걸었다.`,
  o:[
    { l:'① 손가락으로 신호 박을 정한다.', k:'fix', dc:20,
      ok:`합판을 손가락으로 쳤다. 톡, 톡. 쉼. 톡. 기다렸다.<br><br>저쪽에서 톡, 톡. 쉼. 톡. 받았다.<br>그다음엔 박으로 말했다. 셋은 기다려. 둘은 와. 저쪽이 둘을 받았다.<br><br>반 식경 뒤 복도 끝 모퉁이에서 둘이 나타났다. 받은 박 그대로 걸어서.`,
      ng:`쳤는데 대답이 두 군데서 왔다. 벽 너머에서 하나, 등 뒤 복도에서 하나.<br><br>박이 똑같다. 둘 중 하나는 일행이 아니다.<br>어느 쪽인지 몰라 아무 데로도 못 갔다. 한참 뒤 등 뒤 쪽 박이 먼저 끊겼다. 끊긴 자리에서 발소리가 시작됐다.`,
      win:{ exp:16, dream:2, spirit:5 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 벽에 귀를 대고 저쪽 걸음을 듣는다.', k:'sense', dc:19,
      ok:`귀를 댔다. 걸음 둘. 하나는 끄는 발이다. 다쳤다.<br><br>걸음이 왼쪽으로 간다. 이쪽도 벽을 따라 왼쪽으로 걸었다. 같은 박으로.<br>벽 끝 문에서 만났다. 다친 발목을 천으로 묶었다.`,
      ng:`귀를 댄 합판 너머에서 누가 똑같이 귀를 대고 있었다.<br><br>숨소리가 귓바퀴에 바로 닿는다. 일행 숨이 아니다.<br>귀를 떼고 한참 물러섰다. 그 숨이 귓속에서 계속 쉬었다.`,
      win:{ exp:14, dream:1 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B', t:'골목 길잡이 — 늦는 박 하나',
  x:`비 오는 골목에서 만난 길잡이가 앞장선다. 모자를 눌러 썼다. 이 동네 길은 다 안다고 했다.<br><br>
    북잡이는 그 사람 걸음을 들었다. 고르다. 그런데 모퉁이마다 한 박씩 늦다.<br>
    늦는 박에 손이 주머니로 간다. 주머니 안에서 딸깍. 라이터 뚜껑 소리.<br><br>
    셋째 모퉁이. 딸깍. 멀리서 휘파람이 한 번 대답했다.`,
  o:[
    { l:'① 박을 조금씩 당겨 길잡이를 떼어 놓는다.', k:'fix', dc:21, wake:1,
      ok:`걸음 박을 조금씩 당겼다. 손바닥으로 앞사람 등을 짚어 가며. 길잡이 모르게.<br><br>다섯 발이 반 박씩 빨라졌다. 길잡이는 제 박으로 걷는다. 모퉁이 하나마다 반 걸음씩 벌어졌다.<br>넷째 모퉁이에서 길잡이가 딸깍 할 때 일행은 이미 다른 골목에 있었다. 휘파람이 대답한 쪽으로 길잡이 혼자 꺾였다. 장화 여럿이 그 골목에서 나왔다가 혼자인 걸 보고 섰다.<br><br>박은 맞추는 데 쓰는 줄만 알았다. 벌리는 데도 쓴다. 누구를 박 밖으로 내보낼지, 손이 고르기 시작했다.`,
      ng:`당기는데 길잡이가 같이 당겼다. 박을 듣는 사람이었다.<br><br>돌아본 얼굴이 웃는다. 딸깍. 휘파람 셋이 한꺼번에 대답했다.<br>앞뒤 골목에서 장화 소리가 났다. 담을 넘다 손바닥이 철조망에 찢겼다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 늦는 박을 짚어 일행을 멈춰 세운다.', k:'gaze', dc:20,
      ok:`다음 모퉁이 앞에서 손을 들어 일행을 세웠다.<br><br>길잡이가 돌아본다. 왜 서느냐고. 대답하지 않고 그 사람 주머니를 봤다.<br>길잡이가 웃더니 모자를 살짝 들어 보이고 빗속으로 걸어갔다. 서두르지 않고.<br><br>그쪽으로는 안 갔다. 그 사람이 간 길이 제일 넓었다.`,
      ng:`세웠는데 일행이 길잡이 편을 들었다. 왜 의심하느냐고.<br><br>의심은 박으로 설명이 안 된다. 넷째 모퉁이까지 따라갔다. 휘파람이 울렸다.<br>뛰었다. 하나가 넘어져 무릎이 찢겼다. 길잡이는 뛰지 않았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B1', t:'경매장 — 놋쇠 종',
  x:`경매장 칠판 옆에 놋쇠 종이 걸렸다. 반대편 문으로 노란 비옷들이 줄지어 들어온다. 갈고리 장대를 들었다.<br><br>
    종이 울리면 경매가 시작된다. 칠판 맨 아래 17번이 이쪽이다.<br>
    북잡이는 종 옆에 선 사람 손을 봤다. 종 줄을 쥔 손가락이 박을 센다. 넷까지 세고 당길 것이다.<br><br>
    지금 둘.`,
  o:[
    { l:'① 넷이 오기 전에 박을 앞질러 움직인다.', k:'fix', dc:21,
      ok:`셋에서 움직였다. 손짓 하나로 다섯이 얼음 더미 쪽으로 미끄러졌다.<br><br>넷에 종이 울렸다. 노란 비옷들이 경매대 앞으로 몰렸다. 17번 자리가 비어 있다.<br>종소리는 길다. 긴 소리 안에서 쪽문까지 갔다.<br><br>종소리가 끝날 때 문을 닫았다. 남이 세는 박도 끝까지 들으면 내 박이 된다.`,
      ng:`셋에서 움직이려는데 종 줄 쥔 손이 셋에서 당겼다. 남의 박은 바뀐다.<br><br>종이 울렸다. 노란 비옷들이 일제히 이쪽을 봤다.<br>갈고리 장대 끝이 옆구리를 긁고 지나갔다. 비옷 하나가 칠판의 17번 옆에 동그라미를 쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 수조 뒤에 엎드려 종소리를 기다린다.', k:'hide', dc:20,
      ok:`흐린 수조 뒤로 엎드렸다. 물비린내가 진하다.<br><br>종이 울렸다. 비옷들이 경매대로 몰렸다. 눈이 다 칠판에 간다. 그 틈에 기어서 빠졌다.<br>수조 바닥 물받이에 민물고기 한 마리가 퍼덕였다. 손을 넣어 건졌다.<br><br>경매에 안 오른 물건이다. 오른 물건은 이쪽이다.`,
      ng:`수조에 기댄 어깨가 유리를 밀었다. 물이 출렁 넘쳤다.<br><br>바닥을 타고 경매대까지 흘러갔다. 노란 장화들이 물길을 거슬러 온다.<br>얼음 더미 사이로 기어 도망쳤다. 무릎이 얼음 모서리에 찢겼다.`,
      win:{ exp:15, dream:1, item:'민물고기' }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B2', t:'비상계단 — 열세 칸',
  x:`계단을 내려왔다. 벽에 4. 또 내려왔다. 4. 페인트 번진 모양까지 같다.<br><br>
    다들 세는 걸 그만뒀다. 세면 더 무섭다.<br>
    북잡이는 그만두지 않았다. 계단은 박이다. 한 층에 열두 칸. 계단참. 다시 열두 칸.<br><br>
    세 번째 층에서 한 칸이 더 있었다. 열세 칸.`,
  o:[
    { l:'① 칸 수를 박으로 짚어 내려간다.', k:'fix', dc:21, wake:1,
      ok:`열두 칸 층은 같은 층이다. 고리다. 열세 칸 층만 다르다.<br><br>한 층마다 손바닥으로 난간을 짚으며 셌다. 열둘, 쉼. 다음 층. 열둘, 쉼. 열셋. 거기서 계단참 문을 밀었다. 벽 숫자가 3이었다.<br>다들 이쪽을 봤다. 이쪽 손은 아직 세고 있었다.<br><br>박은 맞을 때보다 틀릴 때 더 많이 알려 준다. 틀린 박이 문이었다. 귀가 이제 틀린 박부터 찾는다.`,
      ng:`열세 칸째를 밟았는데 그 칸이 꺼졌다. 한 칸 아래로 발목이 꺾였다.<br><br>계단 박이 거기서 무너졌다. 다시 셌더니 열두 칸이다. 4. 4.<br>발목이 금방 퉁퉁 부었다. 다음 층부터는 업혀서 셌다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 난간을 쳐서 울림이 내려가는 깊이를 듣는다.', k:'sense', dc:20,
      ok:`쇠 난간을 북채로 톡 쳤다. 소리가 난간을 타고 내려간다.<br><br>한참 뒤 바닥을 치는 소리. 다섯 층쯤 아래다. 끝이 있다. 끝이 있는 계단은 고리가 아니다.<br>울림이 한 번 꺾이는 층에서 문을 밀었다. 3이었다.`,
      ng:`쳤는데 소리가 위에서 돌아왔다. 아래로 보낸 소리다.<br><br>난간을 잡은 손이 떨렸다. 위층 어딘가에서 누가 같은 데를 치고 있다. 똑같은 세기로.<br>그 소리가 한 층씩 내려온다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'③ 한 칸만 새것인 고무를 밟고 선다.', k:'luck', dc:20,
      ok:`새 고무가 붙은 칸에 섰다. 발밑이 단단하다. 누가 최근에 고친 칸이다.<br><br>고무 귀퉁이를 들추니 접힌 약 봉투가 있다. 안에 꿀 한 줌. 고친 사람이 남겼다.<br>그 칸부터 다시 내려가니 벽 숫자가 바뀌었다.<br><br>고친 사람은 내려간 사람이다. 그 사람 박을 빌렸다.`,
      ng:`새 고무를 밟았는데 미끄러졌다. 새것이라 길이 안 들었다.<br><br>굴렀다. 계단참까지. 벽에 4.<br>팔꿈치가 계단 모서리에 찍혀 한참 저렸다.`,
      win:{ exp:15, dream:1, item:'꿀 한 줌' }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B3', t:'특실 복도 — 한 박자 늦은 발소리',
  x:`특실 복도는 카펫이다. 발소리가 죽는다. 그런데 하나가 들린다.<br><br>
    일행 발소리 뒤에 한 박 늦게 따라오는 발소리. 다섯이 서면 멈추고 걸으면 걷는다.<br>
    북잡이는 메아리가 아니라는 걸 안다. 메아리는 작아져서 온다. 이건 같은 세기다.<br><br>
    돌아보면 아무도 없을 것이다. 돌아보지 않으면 계속 붙어 올 것이다.`,
  o:[
    { l:'① 박을 바꿔 늦은 발을 떨어뜨린다.', k:'fix', dc:21,
      ok:`셋 걷고 멈췄다. 뒤에서 한 박 늦게 멈춘다. 둘 걷고 멈췄다. 하나 걷고 멈췄다.<br><br>늦은 발이 헷갈렸다. 하나를 더 디뎠다. 다섯이 서 있는데 카펫 밟는 소리가 하나 났다. 그걸로 거리가 나왔다. 일곱 걸음 뒤.<br>엇박으로 걸어 일곱을 열넷으로 벌렸다. 특실 끝 문을 닫았다.<br><br>문 너머에서 한 박 늦게 손잡이가 돌았다. 잠겨 있다.`,
      ng:`박을 바꾸는데 늦은 발이 따라 바꿨다. 이번엔 반 박 늦게. 그다음엔 아주 조금 늦게.<br><br>이쪽 박을 배워서 따라붙는다. 마지막 걸음은 같이 디뎠다. 목덜미에 숨이 닿았다.<br>뛰었다. 문틀에 어깨를 찧었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-16 } },
    { l:'② 아무 박도 없이 그 자리에 오래 선다.', k:'gaze', dc:20,
      ok:`다섯을 다 세우고 오래 섰다. 늦은 발도 섰다.<br><br>한참. 쉼도 박이다. 긴 쉼은 견디는 쪽이 이긴다.<br>그쪽이 먼저 못 견뎠다. 카펫이 한 번 눌렸다. 눌린 자국이 보였다.<br><br>자국을 피해 벽에 붙어 지나갔다. 자국은 따라오지 않았다.`,
      ng:`오래 서 있는데 일행 하나가 숨이 차서 몸을 흔들었다.<br><br>늦은 발이 그 흔들림에 맞춰 한 걸음 다가왔다. 카펫 자국이 다섯 사이로 들어왔다.<br>다들 흩어져 뛰었다. 흩어진 발은 다시 모으는 데 오래 걸린다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B', t:'처마 밑 — 바늘 박',
  x:`비가 들이치지 않는 처마 밑이다. 일행 하나가 옆구리를 베였다. 철조망이다.<br><br>
    꿰매는 손이 떨린다. 네온 간판이 깜박일 때마다 상처가 보였다 안 보였다 한다.<br>
    북잡이는 깜박임을 셌다. 빨강 셋, 어둠 하나, 빨강 둘. 고르지 않다. 고르지 않은 빛 밑에서 바늘이 헛돈다.<br><br>
    처마 끝에서 낙숫물이 떨어진다. 그건 고르다.`,
  o:[
    { l:'① 낙숫물 박에 바늘을 맞춘다.', k:'fix', dc:20,
      ok:`떨어지는 낙숫물을 손가락으로 짚어 보였다. 똑에 찌르고 다음 똑에 뺀다.<br><br>꿰매는 손이 낙숫물을 따라갔다. 깜박이는 빛은 잊었다. 열네 땀.<br>마지막 땀에 네온이 아주 꺼졌다. 손은 박을 알아서 어둠 속에서도 매듭을 지었다.`,
      ng:`낙숫물을 짚는데 바람이 처마를 쳤다. 물줄기가 흩어졌다. 박이 없어졌다.<br><br>바늘이 상처 옆을 찔렀다. 다친 사람이 소리를 삼켰다.<br>꿰맨 자리가 비뚤다. 비뚠 자리로 피가 계속 배어 나온다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ mind:-14, spirit:-12 } },
    { l:'② 다친 쪽 숨에 박을 준다.', k:'heal', dc:20,
      ok:`다친 사람 가슴에 손바닥을 얹고 느리게 눌렀다. 누를 때 내쉬고 뗄 때 들이쉬게.<br><br>숨이 느려지자 피가 느려졌다. 꿰매는 손도 덜 떨었다.<br>숨 박도 약이다. 북잡이는 그 약을 늘 지니고 다닌다.`,
      ng:`누르는 손이 상처 쪽에 닿았다. 다친 사람이 몸을 비틀었다.<br><br>꿰매던 바늘이 이쪽 손등을 찔렀다. 둘 다 피를 흘렸다.<br>처마 밑 웅덩이가 붉어졌다.`,
      win:{ exp:14, dream:1, spirit:5 }, lose:{ hp:-20, mind:-12 } }
  ] },

{ at:'B2', t:'세탁실 — 박이 빠지는 드럼',
  x:`세탁실에 증기가 찼다. 큰 드럼 여섯이 돈다. 웅, 웅. 젖은 시트가 유리창 안에서 뒤집힌다.<br><br>
    북잡이는 여섯 박을 다 들었다. 다섯은 고르다. 넷째 드럼만 한 바퀴에 한 번 쿵 하고 박이 빠진다.<br>
    안에 무거운 것이 있다. 시트보다 무겁고 시트보다 작다.<br><br>
    세탁실 끝 문은 증기 너머다. 증기 속에 흰 반팔이 서 있다. 보호사다.`,
  o:[
    { l:'① 넷째 드럼을 세우고 문을 열어 본다.', k:'gaze', dc:21,
      doom:{ title:'넷째 드럼', what:'세탁 드럼 안으로 끌려 들어갑니다', dc:17, sec:55,
        text:`정지 단추를 눌렀다. 드럼이 멎었다. 유리문을 열었다.<br><br>젖은 시트 사이에 손이 있다. 손이 이쪽 손목을 잡는다. 따뜻하다. 이 층에서 유일하게 따뜻한 손이다.<br>드럼이 다시 돈다. 단추는 아무도 안 눌렀다.<br><br>손이 당긴다. 어깨까지 들어갔다. 시트가 얼굴을 감는다.`,
        dieText:`아침에 세탁물이 7층으로 올라갔다. 시트 한 장이 유난히 무거웠다.<br><br>간호사가 그 시트를 빈 침대에 깔았다. 화이트보드 숫자는 맞았다.<br>넷째 드럼은 그 뒤로 고르게 돈다.` },
      ok:`정지 단추를 눌렀다. 드럼이 멎었다. 유리문을 반만 열었다.<br><br>젖은 시트 사이에 사람이 웅크리고 있다. 환자복이다. 점검을 피해 숨어서 돌고 있었다.<br>꺼내 주자 그 사람이 떨리는 손가락으로 증기 쪽을 가리켰다. 보호사 왼쪽, 바닥 가까이 배수구 문.<br><br>그 문으로 나갔다. 나가기 전에 그 사람이 젖은 꾸러미 하나를 쥐여 줬다. 말린 고기다. 드럼 안에서도 안 놓던 것이다.`,
      win:{ exp:20, dream:3, item:'말린 고기' } },
    { l:'② 드럼 박이 겹치는 순간마다 증기 속을 지난다.', k:'fix', dc:21,
      ok:`드럼 다섯 박이 겹치는 순간 세탁실이 제일 시끄럽다. 그 순간마다 몇 걸음씩 나갔다.<br><br>증기가 얼굴을 덮는다. 흰 반팔이 증기 속에서 고개를 돌린다. 시끄러운 쪽으로.<br>이쪽은 늘 시끄러운 순간 안에 있었다. 그것이 고개를 돌리는 쪽은 늘 지나간 자리였다.<br><br>문에 닿았다. 넷째 드럼의 쿵이 등 뒤에서 한 번 더 울렸다.`,
      ng:`겹치는 순간을 기다리는데 넷째 드럼 쿵이 박을 깼다.<br><br>발이 쿵 뒤의 빈 순간에 떨어졌다. 조용한 순간이었다. 보호사가 돌아섰다. 증기를 가르며 온다.<br>뜨거운 배관에 팔을 데며 빠져나갔다. 살갗이 배관에 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B1', t:'방파제 — 우산의 엄지',
  x:`방파제 끝, 꺼진 등대 밑에 작은 배. 우산이 서 있다. 이 바람에도 안 뒤집힌다.<br><br>
    그가 손을 흔든다. <span style="color:#a9b7c6;">"늦었네. 장부는?"</span><br>
    북잡이는 그의 다른 손을 봤다. 손전등 스위치 위에서 엄지가 톡, 톡 두드린다. 말할 때만 빨라진다.<br><br>
    배 밑에서 물이 무겁게 철썩인다. 빈 배의 박이 아니다.`,
  o:[
    { l:'① 엄지 박에서 거짓을 듣는다.', k:'fix', dc:21, wake:1,
      ok:`그가 말한다. 배는 비었다고. 톡톡톡. 빠르다. 다섯 시면 뭍에 닿는다고. 톡톡톡톡. 더 빠르다.<br><br>장부만 주면 다 끝난다고. 엄지가 멈췄다. 그 말만 참이다. 장부를 주면 끝난다. 이쪽이.<br>일행을 손짓으로 뒤로 물렸다. 우산이 웃었다. 손전등이 켜졌다. 수로 쪽 어둠에서 장화 소리가 대답했다. 이쪽은 이미 방파제 밑 사다리에 매달려 있었다.<br><br>박은 맞춰 주려고 듣는 줄 알았다. 이제 박에서 속을 듣는다. 엄지 하나가 얼굴보다 많이 말했다. 귀가 그걸 놓치지 않았다.`,
      ng:`엄지 박을 듣는데 그가 엄지를 뗐다. 들킨 걸 안다.<br><br>손전등이 켜졌다. 빛이 이쪽 눈에 꽂혔다. 수로 쪽에서 장화 소리가 뛴다.<br>젖은 방파제 돌에 미끄러지며 무릎이 찢겼다. 우산은 끝까지 뒤집히지 않았다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 고동 소리에 맞춰 방파제 밑으로 내려간다.', k:'evade', dc:21,
      ok:`멀리서 해무호가 고동을 운다. 길게, 쉬고, 짧게. 고동이 울 때 바람 소리가 묻힌다.<br><br>고동마다 하나씩 방파제 아래 테트라포드로 내려갔다.<br>우산이 돌아봤을 때 방파제 위는 비어 있었다. 손전등이 물 위를 훑는다. 테트라포드 사이 그늘에는 안 닿는다.`,
      ng:`고동이 끊기는 순간 내려가던 발이 미끄러졌다.<br><br>테트라포드 틈으로 다리가 빠졌다. 파도가 들어왔다 나간다. 나갈 때 당긴다.<br>일행이 겨드랑이를 잡아 끌어냈다. 정강이가 다 갈렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, spirit:-12 } }
  ] },

{ at:'B3', t:'탄수차 — 화부의 삽질',
  x:`화부가 삽질을 한다. 퍽, 휙, 쾅. 석탄을 뜨고, 돌고, 화실에 던진다. 쉬지 않는다.<br><br>
    <span style="color:#9fb4c8;">"더 빨리 가야 돼. 종착에 늦으면 안 돼."</span><br>
    북잡이는 삽질 박과 이음매 박이 같다는 걸 들었다. 삽이 빨라지면 덜컹도 빨라진다. 이 열차는 삽 박으로 달린다.<br><br>
    화부 어깨가 박마다 조금씩 처진다. 사람 박이다. 사람 박은 옮는다.`,
  o:[
    { l:'① 옆에서 삽질 박을 늦춘다.', k:'fix', dc:22, wake:1,
      ok:`석탄 더미 옆에 앉아 손바닥으로 철판을 쳤다. 퍽, 휙, 쾅보다 한 박 느리게.<br><br>화부가 처음엔 무시했다. 열 번째 박에 삽이 이쪽 박에 들어왔다. 지친 사람은 옆에서 치는 박을 못 이긴다.<br>덜컹이 느려졌다. 창밖 불빛이 길게 늘어지다 끊긴다. 종착까지 남은 시간이 늘었다. 화부가 삽에 기대 숨을 몰아쉬었다. 처음으로 쉬었다.<br><br>손바닥 박이 사람을 지나 쇠바퀴까지 갔다. 박은 사람만 잡는 줄 알았다. 사람이 움직이는 것은 다 잡힌다.`,
      ng:`늦추는 박을 치는데 화부가 삽을 멈췄다. 돌아본다.<br><br>화부 얼굴이다. 그런데 눈이 한 박 늦게 깜박인다. 삽 끝이 이쪽으로 왔다.<br>피했다. 삽날이 철판을 긁으며 불똥을 튀겼다. 팔뚝에 불똥이 박혔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-14 } },
    { l:'② 삽을 빼앗는다.', k:'break', dc:21,
      ok:`화부 손목을 잡고 삽 자루를 비틀어 뺏었다. 화부는 순순히 놓았다. 손이 덜덜 떨린다.<br><br>불이 줄었다. 열차가 조금 느려졌다.<br>화부가 주저앉으며 중얼거렸다. 늦으면 안 되는데. 누가 그렇게 시켰는지는 묻지 않았다.`,
      ng:`비틀었는데 화부 손이 안 떨어진다. 삽 자루와 손이 하나다.<br><br>둘이 엉켜 석탄 더미에 넘어졌다. 화실 문 바로 앞이다.<br>열기에 눈썹이 탔다. 삽은 화부 손에 그대로 있다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'B', t:'내려오는 셔터 — 남은 덜컥 셋',
  x:`출구 셔터가 내려온다. 위잉. 한 뼘씩. 셔터 밑으로 빗물과 네온 빛이 들어온다.<br><br>
    무릎 높이까지 남았다. 다섯이 다 기어 나가기엔 빠듯하다. 한꺼번에 들이밀면 엉킨다.<br>
    북잡이는 셔터가 내려오는 박을 셌다. 위잉, 덜컥. 한 뼘. 덜컥마다 잠깐 선다.<br><br>
    남은 덜컥이 셋이다.`,
  o:[
    { l:'① 덜컥마다 하나씩 굴려 내보낸다.', k:'fix', dc:21,
      ok:`덜컥에 하나. 서는 동안 밀어 굴렸다. 덜컥에 둘. 셋째 덜컥에 둘을 한꺼번에.<br><br>셔터가 정강이 높이다. 이쪽 차례다. 셔터가 다시 위잉 할 때 몸을 납작하게 눕혀 미끄러졌다.<br>북이 등에서 셔터에 걸렸다. 끈을 끊고 빠졌다.<br><br>북은 안에 남았다. 셔터 너머에서 누가 그 북을 한 번 쳤다. 이쪽 박이 아니다.`,
      ng:`둘째 덜컥이 오지 않았다. 셔터가 쉬지 않고 내려왔다. 박이 바뀌었다.<br><br>둘째 사람 다리가 셔터에 눌렸다. 다 같이 셔터를 밀어 올렸다.<br>손가락이 밑단에 찢겼다. 셔터가 내려앉은 뒤에도 손끝이 박처럼 욱신거린다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-12 } },
    { l:'② 북을 셔터 밑에 끼워 버틴다.', k:'steady', dc:21,
      doom:{ title:'접힌 북', what:'내려온 셔터에 깔렸습니다', dc:17, sec:50,
        text:`북을 셔터 밑단에 세워 끼웠다. 셔터가 북 테에 얹혀 멈췄다. 테가 운다.<br><br>넷이 기어 나갔다. 이쪽 차례에 테가 우드득 접혔다.<br>셔터가 한 번에 내려왔다. 등 위로. 숨이 밀려 나간다.`,
        dieText:`셔터 밖에서 넷이 셔터를 두드렸다. 안에서 대답이 없다.<br><br>셔터 밑단 틈으로 북 가죽 한 귀퉁이가 삐져나와 있었다.<br>비가 그 가죽을 두드렸다. 박이 고르다.` },
      ok:`북을 셔터 밑단에 세워 끼웠다. 셔터가 테에 얹혀 멈췄다. 테가 운다.<br><br>넷이 기어 나갔다. 이쪽은 마지막에 북을 걷어차며 굴렀다. 셔터가 내려앉았다. 발끝 한 치 앞에.<br>북은 셔터 밑에서 납작해졌다. 테는 부러졌고 가죽은 남았다.<br><br>가죽을 찢어 품에 넣었다. 젖은 가죽이 가슴에 붙는다. 아직 박이 남아 있는 것 같다.`,
      win:{ exp:20, dream:3 } },
    { l:'③ 맨 뒤에서 하나씩 밀어 준다.', k:'bond', dc:20,
      ok:`맨 뒤에 서서 앞사람 발바닥을 밀었다. 밀 때마다 한 사람이 밖으로 미끄러졌다.<br><br>넷째를 밀고 손을 뻗었다. 밖에서 넷이 손목을 잡아 당겼다.<br>셔터가 뒤꿈치를 스쳤다. 신발 뒤축이 셔터 밑에 남았다.`,
      ng:`밀다가 셋째 사람 신발이 벗겨졌다. 신발이 셔터 밑에 끼었다.<br><br>셔터가 신발 위에서 멎었다가 납작하게 눌렀다. 그사이 이쪽 손등이 밑단에 깔렸다.<br>빼내는 데 살갗이 남았다.`,
      win:{ exp:15, dream:1, spirit:5 }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B', t:'북 없이 — 마지막 복도',
  x:`북이 없다. 망가졌거나, 두고 왔거나, 빼앗겼다. 어느 쪽이든 손이 비었다.<br><br>
    마지막 복도다. 끝에 문이 있고 문 앞에 무언가 서 있다. 등을 보인 채. 소리가 나면 돌아설 것이다.<br>
    일행이 이쪽을 본다. 박을 기다린다. 늘 그래 왔다.<br><br>
    북잡이에게서 북을 빼면 무엇이 남는지, 이제 알 때다.`,
  o:[
    { l:'① 아무것도 치지 않는다 — 쉼으로 이끈다.', k:'fix', dc:22, wake:1,
      ok:`손을 들었다. 치지 않았다. 내리지도 않았다. 쉼이다.<br><br>일행이 숨을 죽였다. 쉼은 박보다 크게 들린다. 다섯이 같은 쉼 안에 있다.<br>그대로 한 걸음. 한 걸음. 등을 보인 것이 귀를 기울인다. 들을 것이 없다. 문고리를 돌리는 동안에도 아무도 숨을 안 쉬었다. 문을 닫고서야 다섯이 한꺼번에 숨을 쉬었다.<br><br>박을 치는 사람이었다. 오늘은 박과 박 사이를 쥐었다. 빈손으로 판을 끌고 왔다. 손이 그 무게를 기억한다.`,
      ng:`손을 들었는데 일행 하나가 그걸 뛰라는 신호로 알았다. 뛰었다.<br><br>발소리가 복도를 울렸다. 등을 보인 것이 돌아섰다. 다들 뛰었다.<br>문 앞에서 엉켰다. 이쪽 어깨가 문틀과 그것 사이에 끼었다. 빠져나왔다. 어깨에 무언가 쥐었던 자국이 남았다.`,
      win:{ exp:25, dream:4, spirit:6 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 제 허벅지를 손바닥으로 친다.', k:'steady', dc:20,
      ok:`손바닥을 허벅지에 대고 아주 작게 쳤다. 탁. 쉬고. 탁. 일행 귀까지만 간다.<br><br>그 박으로 걸었다. 등 보인 것이 고개를 반쯤 돌렸다. 박을 늦췄다. 그것도 다시 고개를 돌렸다.<br>문을 지났다. 허벅지가 얼얼하다.<br><br>북이 없으면 몸이 북이다. 알던 거다. 오늘은 그것밖에 없었다.`,
      ng:`탁. 첫 박에 그것이 돌아섰다. 작은 소리가 이 복도에선 크다.<br><br>얼굴 자리에 빗물이 흐른다. 얼굴은 없다.<br>다들 뛰었다. 이쪽이 맨 뒤였다. 등을 손톱이 긁었다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] }

]);

// ── 전술가 ────────────────────────────────
kJob('tactician', 'B', [

{ at:'B', t:'빗속 — 시계 셋',
  x:`시계가 셋이다. 손목시계는 세 시 이 분. 벽시계는 두 시 오십. 길 건너 네온 시계는 깜박여서 못 읽는다.<br><br>
    전술가는 시간을 모르면 판을 못 짠다. 판이 없으면 다들 제 시계를 믿는다. 다섯이 다섯 시계로 움직인다.<br><br>
    나가야 하는 시각은 정해져 있다. 그 전에 할 일이 넷이다.`,
  o:[
    { l:'① 끝에서부터 거꾸로 셈한다.', k:'fix', dc:21, wake:1,
      ok:`지금이 몇 시인지 버렸다. 끝 시각만 쥐었다. 거기서 거꾸로 셌다.<br><br>나가기 전 문 여는 데 십 분. 그 전 물 건너는 데 이십 분. 그 전 짐 찾는 데 삼십 분. 할 일 넷을 끝에서부터 쌓으니 시작이 나왔다. 지금 출발해야 한다. 지금이 몇 시든.<br>다들 움직였다. 시계를 보는 사람이 없었다.<br><br>판은 앞에서부터 짜는 줄 알았다. 끝을 먼저 놓으면 지금이 저절로 정해진다. 머릿속 셈이 뒤집혔다. 뒤집힌 쪽이 더 빠르다.`,
      ng:`거꾸로 셈하다 한 칸을 빼먹었다. 계단 내려가는 데 드는 시간이다.<br><br>끝에 닿았을 때 문은 이미 닫혀 있었다.<br>돌아가는 길에 장화 소리와 마주쳤다. 빗물 웅덩이에 넘어져 손목을 삐었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 제일 늦은 시계를 믿는다.', k:'steady', dc:19,
      ok:`벽시계를 믿기로 했다. 제일 늦다.<br><br>늦은 시계를 믿으면 서두른다. 서두르면 남는다. 다 끝내고 보니 이십 분이 남았다.<br>남은 시간에 다들 숨을 골랐다. 손목시계가 맞았는지는 끝내 모른다.`,
      ng:`제일 늦은 시계를 믿고 서둘렀다. 서두르다 소리를 냈다.<br><br>소리를 듣고 무언가 왔다. 숨느라 서둘러 번 시간을 다 썼다.<br>숨어 있는 동안 세 시계가 다 한 칸씩 갔다.`,
      win:{ exp:14, dream:1, mind:5 }, lose:{ mind:-14, spirit:-12 } }
  ] },

{ at:'B1', t:'3번 창고 — 칠판의 순서',
  x:`창고 칠판에 분필 글씨. 『05:10 해무호 입항. 3번 창고 전량 적재. 그 전에 청소 끝낼 것.』 그 밑에 『다섯. 모자라면 채울 것.』<br><br>
    칠판 옆에 창고 평면도가 붙어 있다. 구역마다 숫자. 1, 2, 3, 4. 청소 순서다.<br>
    전술가는 남의 판을 보면 빈 데부터 찾는다. 남이 짠 판에는 그 사람 버릇이 다 드러난다.<br><br>
    3번 칸만 지웠다가 다시 썼다. 순서를 한 번 바꿨다.`,
  o:[
    { l:'① 청소 순서를 읽고 이미 닦은 구역으로 돈다.', k:'fix', dc:21,
      ok:`1에서 시작해 2, 3. 닦은 구역은 다시 안 본다. 깨끗하니까.<br><br>대걸레 뒤를 따라 닦은 구역만 골라 밟았다. 바닥이 젖어 반짝인다. 대걸레는 늘 앞을 민다. 뒤는 안 돌아본다.<br>쪽문까지 갔다.<br><br>판을 읽으면 판 주인의 등 뒤가 제일 안전하다. 등 뒤는 다 끝난 자리다.`,
      ng:`3번 칸을 왜 바꿨는지 못 읽었다. 닦은 구역이라 믿고 들어섰다.<br><br>아직 안 닦은 구역이었다. 순서를 바꾼 건 이쪽을 기다리려고였다.<br>대걸레가 발밑을 밀었다. 미끄러져 철제 선반 모서리에 이마를 찧었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 칠판의 다섯을 지우고 고쳐 쓴다.', k:'gaze', dc:21,
      doom:{ title:'모자란 숫자', what:'청소부가 모자란 숫자를 채우러 끌고 갑니다', dc:17, sec:55,
        text:`손가락으로 다섯을 지우고 넷이라 썼다.<br><br>분필 가루가 손끝에 묻었다. 등 뒤에서 대걸레 소리가 멎었다. 장화가 칠판 앞에 선다. 넷을 본다. 수첩을 꺼낸다.<br>모자라면 채울 것. 칠판이 그렇게 말한다.<br><br>고무장갑이 이쪽 뒷덜미를 쥔다. 숫자를 채우러.`,
        dieText:`칠판 숫자는 다섯으로 돌아왔다. 분필 글씨가 반듯하다.<br><br>창고 안쪽 냉동실 문에 이름 없는 꼬리표가 하나 더 걸렸다.<br>새벽 다섯 시 십 분, 해무호는 전량을 실었다.` },
      ok:`다섯을 지우고 넷으로 고친 뒤 그 밑에 한 줄을 더 썼다. 『하나는 먼저 실음.』 청소부 글씨를 흉내 냈다. 반듯하게.<br><br>대걸레 소리가 멎었다. 장화가 칠판 앞에 선다. 오래 본다. 수첩을 꺼내 줄 하나를 긋는다. 그러고는 다시 바닥을 민다.<br><br>남의 판에 한 줄을 끼워 넣었다. 판 주인은 제 글씨인 줄 안다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'B2', t:'간호사실 — 근무표',
  x:`간호사실 유리창 안쪽 벽에 근무표가 붙었다. 칸마다 이름 대신 숫자. 정각마다 바뀐다.<br><br>
    전술가는 근무표를 보면 사람이 아니라 빈칸을 센다. 판은 사람이 돌리고 사람은 쉰다. 쉬는 칸이 판의 구멍이다.<br><br>
    새벽 세 시 칸에 숫자가 하나 적다. 둘이 돌던 복도를 하나가 돈다.`,
  o:[
    { l:'① 세 시 빈칸에 맞춰 판을 짠다.', k:'fix', dc:21,
      ok:`세 시 정각 점검이 끝나자마자 움직였다. 하나가 도는 복도는 반만 보인다. 반대쪽 반을 타고 갔다.<br><br>계수기 소리가 복도 한쪽에서만 났다. 이쪽은 늘 다른 쪽에 있었다.<br>이중문 앞에서 시계를 봤다. 세 시 이십 분. 빈칸은 사십 분 남았다.<br><br>남은 사십 분에 다음 층 판을 짰다. 구멍은 쓰라고 있다.`,
      ng:`빈칸 시간에 움직였는데 빈칸을 메운 하나가 두 사람 몫을 돌았다. 걸음이 두 배로 빠르다.<br><br>딸깍 소리가 앞뒤에서 동시에 났다. 같은 사람이다.<br>벽장 안에 숨어 한 시간을 버렸다. 벽장 안에도 근무표가 붙어 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 근무표를 떼어 간다.', k:'hide', dc:20,
      ok:`유리 미닫이를 손톱으로 밀고 근무표를 떼었다. 접어서 품에 넣었다.<br><br>판 하나가 통째로 손에 들어왔다. 내려가는 층마다 같은 근무표가 붙어 있을 것이다.<br>남이 짠 판이다. 쓰는 건 이쪽이다.`,
      ng:`떼는 순간 근무표 뒤에 붙은 종이가 같이 떨어졌다. 『떼어 간 사람 — 다음 정각 점검 대상.』<br><br>유리창 안 의자가 저절로 돌았다. 아무도 안 앉았는데.<br>정각까지 쫓기듯 내려갔다. 계단에서 정강이를 찧었다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B3', t:'9호차 — 시간표 여섯 줄',
  x:`객차 끝 문 위에 시간표. 역 이름 여섯 줄. 맨 아래 종착 04:44. 종착 이름 칸은 비었다.<br><br>
    내리는 문은 맨 앞에만 있다고 했다. 맨 앞까지 객차 여덟. 역은 여섯. 종착 전에 닿아야 한다.<br>
    전술가는 칸과 역을 나란히 놓았다. 역 하나에 칸 하나 반.<br><br>
    칸마다 무엇이 있는지는 모른다. 모르는 칸에는 시간을 더 준다.`,
  o:[
    { l:'① 역마다 넘어갈 칸을 정해 판을 짠다.', k:'fix', dc:21,
      ok:`저녁재까지 9호차를 빠져나간다. 다음 역까지 침대칸 둘. 식당칸은 오래 걸릴 테니 역 하나를 통째로 준다.<br><br>손가락으로 시간표를 짚어 가며 외우게 했다. 역 이름 하나에 칸 이름 하나. 다들 따라 말했다.<br>방송이 저녁재를 부를 때 일행은 이미 9호차 앞문을 열고 있었다.<br><br>판보다 먼저다. 먼저 간 만큼은 나중에 쓸 수 있다.`,
      ng:`판을 짜는 사이 방송이 저녁재를 지났다고 알렸다. 셈하는 데 역 하나를 썼다.<br><br>판은 처음부터 한 칸 늦었다.<br>늦은 판을 따라잡으려 뛰다가 통로 문틀에 팔을 찍었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 승강장 표지판으로 열차 속도를 잰다.', k:'gaze', dc:21,
      ok:`창밖 승강장이 지나갈 때 끝 표지판 숫자를 읽었다. 다음 역까지 남은 거리다.<br><br>역 사이 거리와 시간표를 맞추니 열차 속도가 나왔다. 속도로 종착을 다시 셈했다.<br>04:44가 아니다. 04:39다. 시간표가 다섯 분을 숨겼다.<br><br>판에서 다섯 분을 뺐다. 빼고 나니 오히려 판이 맞았다.`,
      ng:`창에 붙어 승강장을 보다가 유리에 비친 얼굴을 봤다. 이쪽 얼굴 뒤에 하나가 더 있다.<br><br>돌아보지 않았다. 셈은 다 날아갔다.<br>그 얼굴은 역 불빛이 지나갈 때마다 조금씩 이쪽 얼굴을 닮아 갔다.`,
      win:{ exp:16, dream:2, mind:5 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B', t:'처마 밑 거래 — 여섯째 손가락',
  x:`비 오는 처마 밑에서 남자 하나가 거래를 건다. 길을 알려 주겠다고. 대가로 짐 하나.<br><br>
    남자가 손가락으로 몫을 센다. 길 하나, 문 열쇠 하나, 배 자리 다섯. 그리고 여섯째 손가락을 접는다. 아무 말도 없이.<br>
    전술가는 셈을 들으면 남는 것부터 본다.<br><br>
    일행은 다섯이다. 남자가 접은 여섯째 손가락이 무엇인지는 남자만 안다.`,
  o:[
    { l:'① 순서를 바꿔 거래를 뒤집는다.', k:'fix', dc:21,
      ok:`순서를 바꾸자고 했다. 열쇠 먼저, 짐은 문 앞에서.<br><br>남자가 웃었다. 웃는 동안 여섯째 손가락이 폈다 접혔다. 셈이 흔들린 것이다.<br>열쇠를 받았다. 문 앞에서 짐을 내려놓는 대신 옆 골목 철문에 열쇠를 꽂았다. 같은 자물쇠다. 이 동네 열쇠는 하나로 여러 문을 연다.<br><br>남자 셈에는 문이 하나였다. 이쪽 셈에는 둘이었다. 여섯째 손가락은 첫째 문 너머에서 기다리다 비만 맞았다.`,
      ng:`순서를 바꾸자고 하자 남자가 순순히 받았다. 너무 순순했다.<br><br>열쇠는 맞았다. 문도 열렸다. 문 너머에 비옷 넷이 서 있었다. 여섯째 손가락은 문 너머에 있었다.<br>뛰다가 옆구리를 걷어차였다. 갈비뼈가 결린다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 받아들이는 척하고 간격을 벌려 따라간다.', k:'hide', dc:21,
      ok:`받아들이는 척하고 남자를 따라갔다. 일행은 열 걸음씩 벌려 세웠다. 한꺼번에 잡히지 않는 간격이다.<br><br>남자가 모퉁이에서 휘파람을 불었다. 골목에서 그림자 둘이 나왔다. 하나밖에 없는 걸 보고 섰다. 나머지는 열 걸음 뒤, 스무 걸음 뒤에 있다.<br><br>남자가 돌아보며 혀를 찼다. 셈이 하나도 안 맞는다고.`,
      ng:`따라가는데 벌려 세운 간격이 빗속에서 끊겼다. 맨 끝이 안 보인다.<br><br>돌아가니 맨 끝은 처마 밑에 있다. 남자 패거리 하나가 그 옆에서 우산을 받쳐 주고 서 있다.<br>데려오느라 주머니에 있던 걸 다 내줬다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'③ 짐을 내주고 길만 받는다.', k:'luck', dc:20,
      ok:`짐을 내주고 길만 받았다. 남자는 고개를 끄덕이고 갔다.<br><br>길은 맞았다. 짐 안에 든 것은 젖은 신문지뿐이었다.<br>이쪽도 셈은 한다.`,
      ng:`짐을 받은 남자가 짐을 흔들어 봤다. 가볍다. 신문지다.<br><br>남자 얼굴이 굳었다. 길은 반만 알려 줬다.<br>나머지 반은 막다른 골목이었다. 담을 넘다 손바닥이 깨진 유리에 찢겼다.`,
      win:{ exp:14, dream:1 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B', t:'쫓기는 판 — 미끼 둘',
  x:`뒤를 쫓는 무리가 있다. 손전등 셋. 비옷 스치는 소리. 서두르지 않는다.<br><br>
    쫓는 쪽이 서두르지 않으면 길을 다 안다는 뜻이다.<br>
    전술가는 쫓기는 판에서 제일 먼저 미끼를 생각한다. 미끼 하나는 하나를 끌고 간다. 셋을 끌려면 셋이 필요하다.<br><br>
    가진 것은 깡통 몇 개, 노끈, 젖은 외투 한 벌.`,
  o:[
    { l:'① 미끼를 둘로 나눠 갈림목에 놓는다.', k:'fix', dc:21, wake:1,
      ok:`외투를 막대에 걸어 왼쪽 골목 끝에 세웠다. 깡통은 노끈에 매어 오른쪽 홈통 밑에 달았다. 비가 홈통을 넘칠 때마다 깡통이 운다.<br><br>손전등 셋이 갈림목에서 섰다. 왼쪽에는 사람 모양. 오른쪽에는 사람 소리. 하나는 왼쪽, 하나는 오른쪽으로 갔다. 남은 하나가 갈림목에 서서 망설인다.<br>하나는 다섯이 한꺼번에 지나칠 수 있다. 지나쳤다.<br><br>미끼는 하나를 끄는 것인 줄 알았다. 둘을 놓으면 쫓는 쪽이 셈을 시작한다. 셈하는 동안 판이 이쪽으로 넘어온다. 남에게 셈을 시키는 법을 손이 배웠다.`,
      ng:`외투를 세우는데 바람이 외투를 쓰러뜨렸다. 깡통만 울었다.<br><br>손전등 셋이 다 오른쪽으로 갔다. 오른쪽 홈통 밑에 일행이 숨어 있었다.<br>흩어져 뛰었다. 넘어진 이쪽 손등을 장화가 밟고 지나갔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 제가 미끼가 되어 반대로 뛴다.', k:'evade', dc:21,
      doom:{ title:'셈 밖의 담', what:'쫓는 무리에게 잡혀 끌려갑니다', dc:17, sec:55,
        text:`일부러 손전등 앞을 가로질러 반대쪽으로 뛰었다. 셋이 다 따라왔다. 셈대로다.<br><br>골목 끝이 막혔다. 지도에 없는 담이다. 셈에 넣지 못한 담이다.<br>손전등 셋이 한 줄로 다가온다. 젖은 장갑이 팔을 꺾는다.<br><br>끌려간다. 골목 안쪽, 셔터가 반쯤 열린 창고 쪽으로.`,
        dieText:`일행은 반대편 골목으로 빠져나갔다. 판대로다.<br><br>판에는 미끼가 돌아오는 길도 그려져 있었다. 그 길에 담이 있다는 것만 없었다.<br>새벽에 반쯤 열린 셔터가 다 내려왔다.` },
      ok:`일부러 손전등 앞을 가로질러 반대로 뛰었다. 셋이 다 따라왔다.<br><br>골목 끝에 담이 있다. 담 밑 배수구 쇠뚜껑이 반쯤 들려 있다. 아까 지나오며 봐 둔 것이다. 미끄러져 들어갔다.<br>손전등 셋이 담 앞에서 섰다. 빛이 담을 훑고 물러갔다.<br><br>미끼도 판 위의 돌이다. 돌아올 길까지 놓고 뛰었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'B1', t:'야적장 — 멈추는 탐조등',
  x:`크레인 꼭대기 탐조등이 야적장을 훑는다. 한 바퀴 마흔 걸음. 가끔 멈춘다.<br><br>
    노인이 말했다. 저 위에 사람이 있다고. 탐조등은 혼자 안 멈춘다고.<br>
    전술가는 멈추는 때를 셌다. 다섯 번. 매번 무언가 움직인 자리에서 멈췄다. 고양이, 펄럭이는 방수포, 떨어진 물방울.<br><br>
    위에 있는 사람은 움직이는 것을 본다. 서 있는 것은 안 본다.`,
  o:[
    { l:'① 멈추는 때를 셈에 넣어 판을 짠다.', k:'fix', dc:21,
      ok:`일행에게 말했다. 빛이 오면 움직이지 말 것. 빛이 지나간 뒤 열을 세고 움직일 것. 빛이 멈추면 그 반대편으로.<br><br>판을 일러 주는 동안 방수포 끈 하나를 풀었다. 방수포가 펄럭인다. 빛이 거기서 멈춘다. 그동안 다섯이 골목 셋을 지났다.<br><br>위에 있는 사람의 눈을 판에 넣었다. 눈은 쓰는 쪽 것이다.`,
      ng:`방수포 끈을 풀었는데 방수포가 이쪽으로 펄럭였다. 빛이 방수포에서 멈췄다. 방수포 밑에 이쪽 다리가 있다.<br><br>빛 속에서 비가 바늘처럼 보였다. 크레인 위에서 무전기 소리가 났다.<br>컨테이너 틈으로 뛰다 어깨가 철판 모서리에 찢겼다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 크레인 사다리를 올라 탐조등을 묶는다.', k:'break', dc:22,
      ok:`빛이 반대쪽을 볼 때 사다리를 탔다. 젖은 쇠다. 손가락이 얼었다.<br><br>꼭대기에 사람이 의자에 앉아 졸고 있다. 졸면서도 손이 탐조등 손잡이를 쥐었다.<br>그 손 밑으로 손잡이 고정 나사를 조였다. 빛이 한쪽만 비춘다. 나머지 야적장이 어둠에 잠겼다.`,
      ng:`반쯤 올랐을 때 빛이 사다리를 비췄다. 멈췄다. 이쪽 바로 위에서.<br><br>위에서 무언가 떨어졌다. 쇠 공구다. 어깨를 맞고 사다리를 놓칠 뻔했다.<br>내려와서 한참 팔을 못 들었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-12 } },
    { l:'③ 빈 컨테이너 안에서 빛이 지나기를 기다린다.', k:'hide', dc:20,
      ok:`열린 컨테이너에 들어가 문을 반만 닫았다. 빛이 문틈을 지나간다. 네 바퀴. 다섯 바퀴.<br><br>바닥에 소금 자루가 하나 있다. 터진 귀퉁이로 소금 덩이가 굴러 나왔다. 주머니에 넣었다.<br>여섯째 바퀴에 빛이 반대쪽에서 오래 멈췄다. 그때 나왔다.`,
      ng:`컨테이너 안에 이미 누가 있었다. 웅크린 사람이다. 숨을 안 쉰다.<br><br>그 옆에서 빛이 지나기를 기다렸다. 다섯 바퀴.<br>나올 때 다리가 안 움직였다. 그 사람 눈이 떠 있었다. 처음부터 이쪽을 보고 있었다.`,
      win:{ exp:15, dream:1, item:'소금 덩이' }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B2', t:'기록 보관실 — 빈 침대의 대역',
  x:`기록 보관실 장부에 정각마다 인원이 적힌다. 들어옴, 나감. 숫자는 하루 내내 같다.<br><br>
    전술가는 장부를 넘기며 판의 규칙을 읽었다. 이 건물은 숫자만 본다. 얼굴은 안 본다. 누가 있는지보다 몇이 있는지.<br><br>
    내려가려면 위층 침대가 빈다. 빈 침대는 정각에 찾으러 온다.`,
  o:[
    { l:'① 숫자를 맞출 대역을 세운다.', k:'fix', dc:21, wake:1,
      ok:`세탁 바구니에서 시트와 가운을 꺼냈다. 둘둘 말아 사람 길이로 묶었다. 베개를 머리 자리에. 이불을 덮었다.<br><br>침대 다섯에 다섯. 정각 점검 소리가 위층에서 들렸다. 딸깍 다섯 번. 숫자가 맞았다.<br>이쪽은 그 위층 아래 계단에 있었다.<br><br>판을 짜는 것은 사람을 옮기는 일인 줄 알았다. 오늘은 숫자를 옮겼다. 상대가 무엇을 세는지 알면, 사람 대신 그것을 놓으면 된다. 그 셈이 손에 붙었다.`,
      ng:`말아 놓은 시트가 자꾸 풀렸다. 베개가 이불 밖으로 굴렀다.<br><br>정각까지 셋만 만들었다. 딸깍 셋. 계단에서 들었다.<br>위층 문이 열리는 소리. 내려오는 발소리. 여기서 처음 듣는 서두르는 발소리다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-14 } },
    { l:'② 장부의 숫자 칸을 고친다.', k:'gaze', dc:21,
      ok:`장부를 넘겨 보니 숫자를 고친 자국이 많다. 다 같은 볼펜이다.<br><br>같은 볼펜으로 이쪽 칸도 고쳤다. 나감 다섯. 들어옴 다섯. 둘을 같이 고치면 장부가 맞는다.<br>장부가 맞으면 아무도 찾지 않는다.`,
      ng:`고치는데 볼펜이 종이를 찢었다. 한 장이 뜯어졌다.<br><br>뜯어진 자리 밑 장에 이쪽 일행 수가 적혀 있다. 이쪽이 아까 셌던 숫자다. 글씨도 이쪽 글씨다.<br>누군가 이쪽보다 먼저 이쪽을 셌다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B3', t:'식당칸 — 여섯 벌 차린 식탁',
  x:`식당칸 식탁 하나에 접시가 놓였다. 여섯 벌. 일행은 다섯이다.<br><br>
    웨이터가 의자를 빼 준다. 웃는다. 앉으라고.<br>
    전술가는 자리를 보면 판을 본다. 여섯 자리에 다섯이 앉으면 빈자리 하나. 빈자리는 누군가 앉으라고 비워 둔 자리다.<br><br>
    창가 자리 접시만 김이 오른다.`,
  o:[
    { l:'① 자리를 정해 빈자리를 둘러싼다.', k:'fix', dc:21,
      ok:`창가 자리는 비웠다. 그 양옆에 제일 단단한 둘을 앉혔다. 이쪽은 창가 맞은편에.<br><br>빈자리를 다섯이 둘러쌌다. 빈자리에 아무도 앉지 않았다. 앉을 틈이 없다.<br>웨이터가 김 오르는 접시를 거둬 갔다. 아쉬운 얼굴로.<br><br>그 얼굴이 아주 잠깐 웨이터 얼굴이 아니었다.`,
      ng:`자리를 정하는 동안 하나가 이미 창가에 앉았다. 지쳤다.<br><br>일으켜 세웠다. 그 사람 손이 벌써 포크를 쥐고 있었다. 포크를 빼앗는 데 손바닥이 찔렸다.<br>그 사람은 한동안 이쪽 이름을 기억하지 못했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, mind:-16 } },
    { l:'② 앉지 않고 그대로 지나간다.', k:'steady', dc:20,
      ok:`앉지 않았다. 웨이터에게 고개만 숙이고 통로로 지나갔다. 배가 고프다. 음식 냄새가 따라온다.<br><br>식당칸 끝 바 카운터 밑에 꿀 단지 하나가 굴러 있다. 아무도 차려 주지 않은 것이다.<br>그건 먹어도 된다.`,
      ng:`지나가는데 웨이터가 이쪽 소매를 잡는다. 웃는 얼굴로. 앉으시라고.<br><br>뿌리쳤다. 소매 단추가 떨어져 식탁 밑으로 굴렀다.<br>웨이터가 그 단추를 주워 창가 접시 옆에 놓았다. 자리에 이름표를 놓듯이.`,
      win:{ exp:14, dream:1, item:'꿀 한 줌' }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B', t:'계단 밑 — 젖은 셈',
  x:`비를 피해 계단 밑에 모였다. 가진 것을 꺼내 놓았다.<br><br>
    성냥 일곱 개비, 셋은 젖었다. 손전등 하나, 깜박인다. 말린 고기 두 줄. 붕대 한 롤.<br>
    전술가는 늘어놓은 것을 시간으로 바꾼다. 성냥은 분, 고기는 걸음, 붕대는 피.<br><br>
    남은 길은 셈보다 길다.`,
  o:[
    { l:'① 맡은 일에 따라 나눈다.', k:'fix', dc:20,
      ok:`손전등은 맨 앞에. 성냥은 맨 뒤에. 앞은 빛으로 길을 보고 뒤는 불로 등을 본다.<br><br>고기는 짐 진 사람에게 한 줄, 다친 사람에게 반 줄, 남은 반 줄을 셋이 나눈다. 이쪽 몫은 냄새만.<br>붕대는 다친 다리에 지금 다 감았다. 나중에 막을 피보다 지금 막는 피가 싸다.<br><br>셈이 끝나자 다들 일어섰다. 셈이 끝나야 다리가 움직인다.`,
      ng:`나누다가 젖은 성냥을 마른 쪽에 섞었다.<br><br>맨 뒤에서 불을 켜야 할 때 셋이 연달아 안 켜졌다. 그사이 등 뒤 어둠이 가까워졌다.<br>넷째 성냥이 켜졌을 때 무언가 성냥불 바로 앞까지 와 있었다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 젖은 것을 다 버리고 가볍게 간다.', k:'luck', dc:20,
      ok:`젖은 성냥, 깜박이는 손전등을 버렸다. 버리는 것도 셈이다.<br><br>가벼워진 걸음이 빨랐다.<br>다음 계단참에 누가 놓고 간 마른 성냥갑이 있다. 운이다. 셈에는 없었다.`,
      ng:`버린 손전등이 계단 아래로 굴러가며 켜졌다.<br><br>빛이 아래층 복도를 비췄다. 거기 서 있던 것들이 일제히 위를 올려다봤다.<br>숨을 죽이고 반대쪽 계단으로 돌았다. 돌다가 발목을 접질렸다.`,
      win:{ exp:14, dream:1 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B', t:'닫히는 철문 — 숨 열 번, 숨 다섯 번',
  x:`철문 하나를 지나야 한다. 문은 무겁고 스스로 닫힌다. 경첩에 스프링이 감겼다.<br><br>
    문 너머는 계단이다. 등 뒤에서 발소리가 다가온다. 다섯이 지나는 데 숨 열 번. 문이 닫히는 데 숨 다섯 번.<br>
    전술가는 셈이 모자라면 누가 남을지부터 떠올린다. 그게 싫어서 다른 셈을 찾는다.<br><br>
    발밑에 부러진 걸레 자루가 굴러 있다.`,
  o:[
    { l:'① 자루를 쐐기로 박고 다 같이 넘는다.', k:'fix', dc:21, wake:1,
      ok:`문을 밀어 열고 걸레 자루를 경첩 쪽 틈에 박았다. 문이 자루에 걸려 반쯤 열린 채 멈췄다. 자루가 휜다. 숨 열 번은 버틸 휨이다.<br><br>다섯이 다 넘었다. 마지막에 넘으며 자루를 걷어찼다. 문이 쾅 닫혔다. 반대편에서 발소리가 문에 부딪쳤다.<br><br>누가 남을지 셈하던 판이 아무도 안 남는 판이 됐다. 셈을 바꾼 게 아니라 셈할 것을 바꿨다. 사람보다 물건부터 센다. 머리가 그쪽으로 먼저 돈다.`,
      ng:`자루를 박았는데 자리가 틀렸다. 경첩이 아니라 손잡이 쪽이다.<br><br>문이 자루를 밀어 부러뜨렸다. 넷째가 넘을 때 문이 닫히며 팔을 물었다.<br>다 같이 문을 밀어 빼냈다. 발소리가 바로 뒤였다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 제가 남아 문을 받친다.', k:'steady', dc:21,
      doom:{ title:'셈대로 남은 자리', what:'닫힌 문 너머로 끌려갑니다', dc:17, sec:55,
        text:`등으로 문을 받쳤다. 넷이 지나갔다. 셈대로다.<br><br>마지막 숨에 몸을 빼려는데 문틈으로 손이 들어와 허리띠를 잡는다. 젖은 장갑이다.<br>문이 닫히는 힘과 장갑이 당기는 힘이 같은 쪽이다.<br><br>끌려간다. 문 안쪽 어둠으로.`,
        dieText:`문 너머에서 넷은 기다렸다. 판에 적힌 시간만큼.<br><br>그 판에는 남는 사람이 돌아오는 칸이 있었다. 비어 있었다.<br>넷은 판대로 다음 계단을 내려갔다. 판을 짠 사람이 그렇게 하라고 했으니까.` },
      ok:`등으로 문을 받쳤다. 넷이 지나갔다.<br><br>마지막 숨에 몸을 빼려는데 문틈으로 장갑이 들어온다. 허리띠를 풀어 장갑에 쥐여 주고 빠졌다.<br>문이 닫혔다. 허리띠가 문틈에 끼어 덜렁거린다.<br><br>판에 남는 사람은 없었다. 남는 허리띠만 있었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'B1', t:'선착장 — 회색 밴',
  x:`선착장 끝에 회색 밴이 서 있다. 시동은 꺼졌다. 운전석과 조수석에 둘. 담뱃불 둘.<br><br>
    밴 옆 바닥에 꽁초가 쌓였다. 빗물에 퉁퉁 불었다.<br>
    전술가는 꽁초를 보면 시간을 센다. 한 개비 칠 분. 둘이 번갈아 피웠다.<br><br>
    밴 뒷문이 반쯤 열렸다. 안에 빈 자루 다섯 개가 접혀 있다.`,
  o:[
    { l:'① 꽁초로 시간을 재고 판을 짠다.', k:'fix', dc:21,
      ok:`꽁초는 스물하나. 칠십 분을 기다렸다. 기다리는 사람은 정해진 때까지 기다린다.<br><br>해무호 고동까지 남은 시간과 맞춰 보니 둘은 고동이 울리면 움직인다.<br>고동이 울렸다. 둘이 담배를 던지고 내려 선착장 쪽으로 갔다. 다섯은 반대로, 둘이 막 비운 밴 그늘을 지났다.<br><br>남이 기다린 시간도 셈이 된다. 기다린 사람은 그 시간을 모른다.`,
      ng:`꽁초를 세다가 한 개비가 아직 타고 있는 걸 못 봤다. 방금 버린 것이다.<br><br>셋째 사람이 밴 뒤에 서 있었다. 담배 연기가 이쪽 얼굴에 닿았다.<br>쇠파이프가 어깨를 내리쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-12 } },
    { l:'② 밴 열쇠를 노린다.', k:'luck', dc:21,
      ok:`둘이 담배를 사러 초소 쪽으로 갔다. 열쇠가 꽂혀 있다.<br><br>뒷문으로 타지 않았다. 열쇠만 뽑아 바다에 던졌다.<br>둘이 돌아와 한참 뒤적였다. 그동안 다섯은 선착장 끝을 돌아 나갔다. 남의 판에서 말 하나를 뺐다.`,
      ng:`열쇠를 뽑는데 열쇠고리에 방울이 달려 있었다. 딸랑.<br><br>둘이 돌아봤다. 손전등이 켜졌다.<br>부두 기둥 사이로 뛰다가 정강이가 쇠 계류주에 찍혔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'B2', t:'원무과 — 39와 40',
  x:`대기실 의자마다 번호표가 놓였다. 전광판 숫자가 바뀐다. 띵동. 창구는 비었다.<br><br>
    입구 번호표 기계가 일행이 들어설 때마다 한 장씩 뱉는다. 41, 42, 43, 44, 45.<br>
    전술가는 전광판을 봤다. 지금 38. 의자에 놓인 번호표 중 39와 40이 없다. 누가 가지고 갔다.<br><br>
    불린 번호는 창구로 간다. 창구 뒤에 문이 하나 있다. 정문 쪽이다.`,
  o:[
    { l:'① 번호 순서를 판으로 쓴다.', k:'fix', dc:21,
      ok:`41번은 제일 단단한 사람에게 쥐였다. 45는 이쪽이 쥐었다.<br><br>39, 40이 불리고 아무도 안 나갔다. 전광판이 41을 부를 때 41이 창구로 갔다. 창구 뒤 문이 열렸다.<br>열리는 동안 41이 문을 붙잡았다. 42부터 45까지가 제 번호를 기다리지 않고 그 문으로 들어갔다.<br><br>차례는 하나가 열면 뒤가 다 지나간다. 판 짠 쪽은 하나씩 오리라 셈했다.`,
      ng:`41이 창구 앞에 서자 전광판이 41을 지웠다. 띵동. 45. 이쪽 번호다.<br><br>이쪽 차례를 앞당겼다. 혼자 창구 앞에 섰다. 유리 너머에서 손이 서류를 내민다. 이름 칸이 비었다.<br>쓰지 않았다. 문은 안 열렸다. 대기실로 돌아오는 동안 손이 계속 펜을 찾았다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-14 } },
    { l:'② 번호표를 받지 않고 지나간다.', k:'evade', dc:21,
      ok:`기계가 뱉은 번호표를 아무도 안 집었다. 번호표는 바닥에 쌓였다.<br><br>번호가 없으면 불리지 않는다. 불리지 않으면 세어지지도 않는다.<br>벽에 붙어 대기실을 지나 비상구로 나갔다. 바닥 번호표 다섯 장에 젖은 신발 자국이 남았다.`,
      ng:`안 집었는데 기계가 멈추지 않는다. 다섯 장, 여섯 장, 열 장. 바닥이 번호표로 덮였다.<br><br>전광판이 그 번호를 하나씩 부른다. 의자 밑에서 무언가 일어난다. 번호에 대답하러.<br>뛰었다. 의자에 걸려 넘어져 이마가 깨졌다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B3', t:'우편칸 — 이름 없는 칸',
  x:`우편칸에 칸칸이 나뉜 선반이 있다. 칸마다 역 이름. 저녁재, 가는골, 그 밑에 세 칸. 맨 아래 칸은 이름이 없다.<br><br>
    이름 없는 칸이 제일 크다. 우편이 가득하다. 봉투마다 받는 사람 이름 대신 좌석 번호.<br>
    전술가는 분류된 것을 보면 누가 분류했는지 생각한다. 이 열차의 판을 짠 손이다.<br><br>
    봉투 하나에 이쪽 좌석 번호가 적혀 있다.`,
  o:[
    { l:'① 칸마다 봉투를 세어 문이 열릴 역을 읽는다.', k:'gaze', dc:21,
      ok:`칸마다 봉투를 셌다. 저녁재 열하나. 가는골 서른여섯. 그다음 칸은 비었다.<br><br>빈 칸은 아무도 안 내리는 역이다. 아무도 안 내리는 역에서 판 짠 손은 문을 안 지킨다. 그 역 이름을 외웠다.<br>이쪽 좌석 번호 봉투는 이름 없는 칸에서 꺼내 빈 칸에 꽂았다.<br><br>남의 판에서 칸 하나를 바꿨다. 작은 칸이다. 작은 칸은 잘 안 본다.`,
      ng:`세다가 이름 없는 칸 봉투들이 바스락거렸다. 안에서 무언가 움직인다.<br><br>봉투 하나가 저절로 열렸다. 사진 한 장. 이쪽 일행이 9호차에 앉아 있는 사진이다. 위에서 찍었다.<br>선반 위를 올려다보지 않았다. 한참 손이 떨렸다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 우편 자루로 통로를 좁힌다.', k:'fix', dc:21,
      ok:`무거운 등기 자루를 통로에 쌓아 좁혔다. 사람 하나 겨우 지나는 틈. 틈 앞에 제일 단단한 사람을 세웠다.<br><br>얼굴 바꾸는 것도 좁은 데로는 하나씩 와야 한다. 하나씩 오면 얼굴을 하나씩 볼 수 있다.<br>틈으로 들어온 얼굴 셋을 다 봤다. 셋째에서 손을 들었다. 그것이 물러갔다.<br><br>판을 좁혔더니 판이 보였다.`,
      ng:`자루를 쌓는데 자루 하나가 무겁다. 우편이 아니다.<br><br>묶은 끈을 풀다 말았다. 안에서 손가락이 끈을 같이 풀고 있었다.<br>자루를 밀어 넘기고 물러섰다. 넘어진 자루에 정강이가 깔렸다.`,
      win:{ exp:16, dream:2, spirit:5 }, lose:{ hp:-26, spirit:-14 } }
  ] },

{ at:'B', t:'읽힌 판 — 세 번 막힌 길',
  x:`세 번 연달아 막혔다. 판대로 간 길마다 누가 먼저 와 있었다.<br><br>
    전술가는 우연이 셋이면 우연이 아니라는 걸 안다. 판을 읽혔다. 저쪽도 판을 짠다.<br>
    이쪽 버릇은 이렇다. 물 있는 곳을 먼저. 넓은 길보다 좁은 길. 끝에 제가 선다.<br><br>
    그 버릇이 젖은 길바닥에 다 찍혀 있다.`,
  o:[
    { l:'① 버릇을 버리고 판을 흩뜨린다.', k:'fix', dc:22, wake:1,
      ok:`이번엔 넓은 길로 갔다. 물 있는 곳은 건너뛰었다. 맨 앞에 섰다.<br><br>판이 엉망이다. 이쪽이 봐도 엉망이다. 그래서 읽히지 않았다. 넓은 길에는 아무도 없었다. 다들 좁은 길에서 기다리고 있었을 것이다.<br><br>판은 맞게 짜는 것인 줄 알았다. 읽히지 않게 짜는 판도 있다. 제 버릇을 남의 눈으로 보기 시작했다. 그 눈이 떠지자 판이 하나 더 보인다. 저쪽 판이다.`,
      ng:`버릇을 버렸는데 엉망인 판이 그냥 엉망이었다. 넓은 길 끝이 막혔다.<br><br>되돌아오는 길에 좁은 길에서 기다리던 것들이 나와 섰다.<br>판을 버리면 판에 진다. 뛰다가 담에 어깨를 찧었다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 버릇대로 가되 두 배 빠르게 간다.', k:'luck', dc:21,
      ok:`버릇대로 갔다. 다만 두 배 빠르게.<br><br>저쪽이 기다릴 자리에 저쪽보다 먼저 닿았다. 기다리러 오던 그림자 하나와 모퉁이에서 엇갈렸다. 그쪽이 놀랐다.<br>판이 읽혀도 먼저 놓으면 이긴다. 오늘은 그랬다.`,
      ng:`빠르게 갔는데 저쪽은 이미 와 있었다. 이쪽 버릇은 빠르기까지 읽혔다.<br><br>모퉁이에서 우산 끝이 이쪽 목을 겨눴다.<br>물러서다 계단에서 굴렀다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B2', t:'중앙 계단 — 엄지 서른둘',
  x:`중앙 계단 양옆에 직원들이 줄지어 섰다. 다 같은 얼굴. 모두 계수기를 들고 엄지만 얹었다.<br><br>
    발이 계단에 닿는 순간 엄지들이 내려갈 것이다.<br>
    전술가는 세는 쪽이 무엇을 세는지부터 짚었다. 사람이 아니라 발이다. 엄지들은 발소리에 얹혀 있다.<br><br>
    계단은 서른둘. 다섯이 서른두 칸을 디디면 엄지는 몇 번 내려가는가.`,
  o:[
    { l:'① 다섯이 한 칸에 나란히, 한 발로 디딘다.', k:'fix', dc:22,
      ok:`한 줄로 세우지 않았다. 한 칸에 다섯이 나란히 서게 했다. 계단이 넓다. 하나, 하면 다섯이 같이 디딘다.<br><br>딸깍. 엄지가 한 번 내려간다. 발소리가 하나다. 서른두 칸에 딸깍 서른둘.<br>계수기 숫자는 서른둘이다. 다섯이 아니다. 사람 수가 아니다.<br><br>세는 손들이 서로를 봤다. 셀 것을 잘못 센 얼굴이다. 그 틈에 로비로 내려섰다.`,
      ng:`셋째 칸에서 하나가 반 박 늦게 디뎠다. 딸깍 딸깍.<br><br>엄지 하나가 다른 엄지들보다 한 번 더 내려갔다. 숫자가 어긋났다. 어긋난 숫자는 맞을 때까지 센다.<br>양옆 손들이 계단 안쪽으로 한 걸음 들어섰다. 밀리다 난간에 갈비뼈를 찧었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 난간을 타고 미끄러져 발을 안 닿게 한다.', k:'evade', dc:21,
      doom:{ title:'세지 않은 발', what:'세는 손들에게 붙들려 끌려갑니다', dc:18, sec:50,
        text:`난간에 걸터앉아 미끄러졌다. 발이 계단에 안 닿는다. 엄지들이 안 내려간다.<br><br>세어지지 않은 것이 지나간다. 세어지지 않은 것은 찾아야 한다.<br>양옆에서 손들이 한꺼번에 뻗는다. 발목을, 팔을, 옷깃을.<br><br>미끄러지던 몸이 멈췄다. 들린다. 계단 위쪽으로 넘겨진다. 손에서 손으로.`,
        dieText:`일행은 로비에 내려섰다. 엄지들이 정확히 그 수만큼 내려갔다.<br><br>계단 위쪽 어딘가에서 엄지 하나가 오래 눌린 채였다.<br>7층 화이트보드에 숫자가 하나 늘었다. 고친 자국 없이.` },
      ok:`난간에 걸터앉아 미끄러졌다. 발이 안 닿는다. 엄지들이 안 내려간다.<br><br>손들이 뻗어 오기 전에 난간 끝에서 뛰어내렸다. 로비 바닥에 발이 닿았다. 딸깍. 계단이 아니라 로비에서 한 번.<br><br>세는 손들 쪽에서 보면 이쪽은 처음부터 로비에 있던 사람이다. 세는 판의 칸 밖으로 한 번 나갔다 들어왔다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'B1', t:'정문 — 사슬 기계실',
  x:`정문 철문은 사슬로 감겼다. 사슬은 기계실 도르래로 이어진다. 기계실에 레버가 셋.<br><br>
    레버마다 종이가 붙었다. 감기, 풀기, 정지. 지웠다가 다시 쓴 글씨다. 셋 다 같은 손 글씨다.<br>
    전술가는 레버 셋을 보면 순서를 생각한다. 무엇을 먼저 당기면 무엇이 되는지.<br><br>
    기계실 창밖으로 회색 비옷이 정문 쪽으로 걸어간다. 다섯 시 십 분까지 칠 분.`,
  o:[
    { l:'① 순서를 짜서 레버를 셋에게 나눠 맡긴다.', k:'fix', dc:22, wake:1,
      ok:`레버에 붙은 종이를 다 뗐다. 글씨를 믿지 않았다. 도르래를 봤다. 사슬이 감긴 쪽, 톱니가 물린 쪽.<br><br>레버마다 하나씩 세웠다. 셋, 둘, 하나. 정지를 먼저 풀고, 풀기를 당기고, 감기는 끝까지 안 건드린다.<br>사슬이 풀리며 철문이 덜컹 열렸다. 다섯이 다 나간 다음 맨 끝 손이 감기를 당겼다. 등 뒤에서 사슬이 다시 감겼다. 문 안쪽에 비옷이 섰다.<br><br>판은 혼자 쥐는 줄 알았다. 오늘은 손 셋에 나눠 쥐어 줬다. 저마다 제 칸을 알았다. 나눠 쥔 판이 한 손 판보다 빨랐다.`,
      ng:`종이를 뗐는데 종이 뒤에 다른 글씨가 있었다. 그걸 읽느라 일 분을 썼다.<br><br>셋이 레버를 한꺼번에 당겼다. 셋이 서로를 막았다. 도르래가 비명을 질렀다.<br>사슬이 튀어 기계실 창을 깼다. 유리 조각이 팔에 박혔다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 가운데 레버를 힘껏 꺾는다.', k:'break', dc:21,
      ok:`가운데가 정지라면 정지가 풀려야 뭐든 된다. 힘껏 당겼다.<br><br>녹슨 레버가 꺾였다. 도르래가 헛돌며 사슬이 제 무게로 풀려 내렸다.<br>문이 반쯤 열렸다. 다섯이 그 틈으로 빠졌다.`,
      ng:`당겼는데 가운데가 감기였다. 사슬이 한 바퀴 더 감겼다. 철문이 조이며 운다.<br><br>창밖의 비옷이 고개를 들어 기계실을 봤다.<br>레버를 되돌리다 손가락이 톱니에 끼었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-14 } }
  ] },

{ at:'B3', t:'기관실 문 — 기관사가 둘',
  x:`기관실 문 앞에 기관사가 둘이다. 같은 모자, 같은 제복, 같은 얼굴. 둘 다 이쪽을 보고 말한다.<br>
    <span style="color:#9fb4c8;">"저쪽이 가짜예요."</span><br><br>
    전술가는 둘 중 하나를 고를 때 얼굴을 안 본다. 얼굴은 바뀐다. 일하는 손은 안 바뀐다.<br>
    기관사는 이 열차의 판을 아는 사람이다. 가짜는 판의 겉만 안다.<br><br>
    종착까지 얼마 없다.`,
  o:[
    { l:'① 일하는 절차를 묻는다.', k:'fix', dc:22, wake:1,
      ok:`둘에게 같은 걸 물었다. 비 오는 밤에 다음 신호까지 거리를 어떻게 아느냐고.<br><br>하나는 바로 대답했다. 창밖 표지판을 본다고. 하나는 대답 대신 회중시계를 꺼냈다. 시계를 보며 손가락으로 무언가를 셌다. 이음매를 세는 손이다.<br>표지판은 이 비에 안 보인다. 판을 아는 사람은 판이 안 보일 때 하는 셈이 있다.<br><br>사람을 고를 때 늘 무엇을 아는지 물었다. 오늘은 모를 때 무엇을 하는지 물었다. 그 물음 하나가 얼굴 하나를 벗겼다. 다음 판에도 그 물음을 쥐고 간다.`,
      ng:`둘에게 물었다. 둘 다 똑같이 대답했다. 회중시계를 꺼내는 것까지.<br><br>가짜는 진짜 옆에 오래 서 있었다. 다 배웠다. 고르지 못했다.<br>그사이 하나가 이쪽 등 뒤로 돌았다. 목덜미에 찬 손가락이 닿았다.`,
      win:{ exp:25, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 둘 다 묶어 판에서 뺀다.', k:'break', dc:21,
      ok:`둘 다 묶었다. 하나는 가만히 있었다. 하나는 웃었다. 웃은 쪽을 한 번 더 묶었다.<br><br>모르는 판은 빈 판이 낫다.<br>가만히 있던 쪽이 묶인 채로 레버 이름을 하나씩 일러 줬다. 묻지도 않았는데.`,
      ng:`묶는 동안 하나가 이쪽 손목을 비틀었다. 둘 다 이쪽을 노려본다.<br><br>하나를 놓쳤다. 놓친 쪽이 통로로 사라졌다.<br>남은 쪽이 진짜였는지는 모른다. 손목이 퉁퉁 부었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'③ 먼저 말한 쪽을 믿는다.', k:'luck', dc:21,
      doom:{ title:'먼저 말한 얼굴', what:'가짜 기관사에게 끌려갑니다', dc:17, sec:50,
        text:`먼저 말한 쪽을 믿고 기관실 문을 열어 줬다. 그가 고개를 숙이고 들어간다.<br><br>안에서 레버 당기는 소리. 열차가 더 빨라진다.<br>남은 쪽이 이쪽을 보며 고개를 젓는다.<br><br>문이 다시 열린다. 손 하나가 이쪽 팔을 잡아 안으로 끈다. 화실 불빛 쪽으로.`,
        dieText:`열차는 04:39에 종착을 지났다. 서지 않았다.<br><br>기관실 안에 기관사가 둘 있었다. 하나는 바닥에, 하나는 레버 앞에.<br>레버 앞의 얼굴은 판을 짜던 사람 얼굴이었다.` },
      ok:`먼저 말한 쪽을 믿었다. 그가 기관실 문손잡이에 손을 뻗는다.<br><br>손잡이 높이를 더듬는다. 매일 여는 문이라면 더듬지 않는다. 처음 여는 문이다.<br>문을 도로 닫아 버렸다. 남은 쪽이 고개를 끄덕였다.<br><br>운으로 골랐다. 고른 다음에 셈이 왔다. 늦은 셈이 운을 바로잡았다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'B', t:'남은 칠 분 — 쪼갠 판',
  x:`출구까지 칠 분 남았다. 길은 셋으로 갈린다. 다 처음 보는 길이다.<br><br>
    판을 짤 시간이 없다. 짜는 데만 칠 분이 걸리는 판이다.<br>
    전술가는 시간이 없을 때 판을 버리지 않는다. 판을 쪼갠다.<br><br>
    일행이 숨을 몰아쉬며 이쪽을 본다.`,
  o:[
    { l:'① 일 분짜리 판 일곱 개로 쪼갠다.', k:'fix', dc:21,
      ok:`큰 판을 버리고 일 분짜리를 짰다. 일 분 동안 첫 갈림길까지. 거기서 다음 일 분. 바람이 오는 쪽. 셋째 일 분. 물 흐르는 쪽.<br><br>일 분마다 하나만 정했다. 일곱 번 정했다. 일곱째 일 분 끝에 출구가 있었다.<br><br>아무도 판 전체를 몰랐다. 판 전체가 없었다. 그래도 닿았다.`,
      ng:`쪼갠 판 셋째에서 막혔다. 막힌 일 분은 돌아가는 일 분이 된다. 돌아가는 판은 쪼갤 수가 없다.<br><br>마지막 일 분에 셔터 내려오는 소리를 들으며 뛰었다.<br>정강이가 셔터 밑단에 갈렸다.`,
      win:{ exp:18, dream:2, mind:5 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 제일 넓은 길로 판 없이 달린다.', k:'evade', dc:20,
      ok:`판을 버리고 넓은 길로 달렸다. 넓은 길은 대개 어딘가로 간다.<br><br>갔다. 판이 없으니 읽힐 것도 없다.<br>쫓는 쪽도 판 없이 쫓아야 했다. 판 없는 쫓기는 느리다.`,
      ng:`넓은 길은 넓은 마당에서 끝났다. 마당 한가운데 서 있는 것이 이쪽을 기다렸다.<br><br>넓은 길은 모두가 아는 길이다.<br>마당을 가로질러 뛰다 넘어져 손바닥이 다 찢겼다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-26, spirit:-14 } }
  ] },

{ at:'B', t:'돌멩이 판 — 제일 나쁜 자리',
  x:`비가 잦아들기를 기다리며 바닥에 판을 그렸다. 돌멩이 다섯. 하나가 한 사람이다.<br><br>
    다 빠져나가는 판이 하나 있다. 그 판에서 돌 하나는 제일 오래 남아야 한다. 탐조등 밑, 문 옆, 맨 마지막.<br>
    전술가는 그 자리를 오래 봤다. 누구를 놓을지.<br><br>
    제 돌을 집었다. 손바닥 안에서 돌이 차다.`,
  o:[
    { l:'① 제 돌을 그 자리에 놓고 돌아올 길까지 그린다.', k:'fix', dc:22, wake:1,
      ok:`제 돌을 마지막 자리에 놓았다. 그 돌에서 바깥까지 선을 하나 더 그었다. 돌아오는 길이다.<br><br>다른 넷이 그 선 위에 제 돌을 하나씩 얹었다. 문을 잡아 주는 자리, 손을 뻗는 자리. 마지막 자리가 혼자가 아니게 됐다.<br>판대로 했다. 탐조등 밑에서 이쪽이 오래 남았고, 넷이 놓은 자리마다 손이 왔다. 다 나왔다.<br><br>제 돌은 늘 판 밖에 두던 손이다. 오늘은 판 안 제일 나쁜 자리에 두고, 그 자리를 판 전체가 받치게 했다. 판을 보는 눈이 한 칸 넓어졌다.`,
      ng:`제 돌을 놓았는데 돌아오는 선이 안 그려진다. 어디로 그어도 탐조등이 지난다.<br><br>그대로 갔다. 마지막에 혼자 남았다. 빛이 이쪽에서 멈췄다.<br>담을 넘다 철조망에 등이 다 긁혔다. 판은 맞았다. 이쪽만 틀렸다.`,
      win:{ exp:25, dream:4, spirit:6 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 판을 다 같이 보게 한다.', k:'bond', dc:20,
      ok:`판을 일행에게 보였다. 마지막 자리를 손가락으로 짚었다.<br><br>하나가 제 돌을 집어 거기 놓았다. 제일 빠른 사람이다. 그 사람이 맞다.<br>판을 혼자 쥐면 제 돌만 보인다. 같이 보면 맞는 돌이 보인다.`,
      ng:`판을 보이자 다들 마지막 자리를 피해 제 돌을 앞으로 옮겼다. 판이 무너졌다.<br><br>다시 짜는 동안 비가 그쳤다.<br>비가 그치면 발소리가 들린다. 저쪽 발소리도.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-14 } }
  ] }

]);

// ── 부여술사 ──────────────────────────────
kJob('enchanter', 'B', [

{ at:'B', t:'빗속 — 우는 밑창',
  x:`젖은 신발은 소리가 난다. 철벅, 끽. 다섯 켤레가 다 운다.<br><br>
    뒤쫓는 발소리가 그 소리를 따라온다. 서두르지 않는다.<br>
    부여술사는 물건에 무언가를 덧입힌다. 늘 더하는 쪽이었다. 날카로움, 질김, 밝음.<br><br>
    지금 필요한 것은 더하는 것이 아니다. 빼는 것이다.`,
  o:[
    { l:'① 마력을 써서 밑창에 고요를 입힌다.', k:'fix', dc:21, cost:{ mana:24 }, wake:1,
      ok:`한 사람씩 발목을 잡고 밑창을 손바닥으로 훑었다. 소리를 덧입히는 대신 소리 없음을 입혔다. 처음 해 보는 부여다. 빈 것을 입힌다.<br><br>철벅이 사라졌다. 젖은 바닥을 디뎌도 물만 튄다. 다섯이 소리 없이 골목을 지났다.<br>뒤쫓던 발소리가 골목 어귀에서 멈췄다. 따라올 소리가 없다.<br><br>있는 것만 입히는 줄 알았다. 없는 것도 입혀진다. 손바닥이 빈 것의 무게를 처음 알았다. 가볍지 않다.`,
      ng:`넷째 신발에서 마력이 엉켰다. 고요가 아니라 무거움이 들어갔다.<br><br>그 사람 발이 한 걸음마다 쿵 하고 떨어진다. 더 크다. 뒤쫓는 발소리가 빨라졌다.<br>셋이 그 사람을 부축해 뛰었다. 넘어지며 무릎이 깨졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 신발을 벗어 들고 걷는다.', k:'hide', dc:20,
      ok:`다들 신발을 벗어 손에 들었다. 맨발에 빗물이 차다.<br><br>맨발은 소리가 작다. 발바닥이 길바닥을 먼저 읽는다.<br>마력은 아꼈다. 아낀 마력은 나중 몫이다.`,
      ng:`맨발로 걷다 깨진 유리를 밟았다. 소리를 삼켰다.<br><br>피가 빗물에 번진다.<br>피 냄새는 소리보다 멀리 간다. 뒤쫓는 발소리가 웅덩이마다 멈췄다 온다.`,
      win:{ exp:14, dream:1, mana:6 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B1', t:'3번 창고 — 양동이 물',
  x:`청소부의 양동이가 셔터 옆에 놓여 있다. 주인은 잠깐 자리를 비웠다.<br><br>
    물이 맑다. 너무 맑다. 대걸레가 수백 번 들어갔다 나왔을 물이다.<br>
    부여술사 눈에는 물 위에 덧입힌 것이 보인다. 지움. 닿은 것을 남기지 않음.<br><br>
    오래된 부여다. 손 하나가 매일 밤 새로 입혔다. 셔터 사슬 자물쇠는 바로 옆이다.`,
  o:[
    { l:'① 마력을 써서 물을 떠 자물쇠에 붓는다.', k:'fix', dc:21, cost:{ mana:25 },
      ok:`손은 담그지 않았다. 빈 깡통으로 물을 떴다. 지움이 흘러넘치지 않게 마력으로 깡통 테두리를 막았다.<br><br>자물쇠에 부었다. 쇠가 지워진다. 녹이 슨 게 아니다. 처음부터 없던 것처럼. 사슬이 바닥에 떨어졌다.<br><br>남의 부여를 빌려 썼다. 빌린 것은 갚게 된다. 깡통도 지워져 손잡이만 남았다.`,
      ng:`깡통 테두리를 막던 마력이 한쪽에서 샜다. 물이 손등에 튀었다.<br><br>손등 살갗이 지워진다. 아프지 않다. 그게 더 무섭다.<br>소매로 문질렀다. 손등에 동전만 한 자리가 반들반들하다. 지문도 없다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-14 } },
    { l:'② 물에 덧입힌 지움을 한 겹 걷어 본다.', k:'gaze', dc:21,
      doom:{ title:'지우는 물', what:'양동이 물이 손을 끌어당깁니다', dc:17, sec:55,
        text:`물 위에 손을 펴고 덧입힌 것을 한 겹 걷었다. 두껍다. 매일 밤 한 겹씩 쌓였다.<br><br>두 겹째에서 물이 손바닥을 당겼다. 손끝이 물에 닿았다. 손끝이 지워진다.<br>손목까지 들어갔다. 양동이가 이렇게 깊을 리 없다.<br><br>멀리서 장화 소리가 돌아온다. 서두르지 않고.`,
        dieText:`청소부는 양동이를 들고 다음 구역으로 갔다.<br><br>3번 창고 바닥은 깨끗했다. 아무것도 남지 않았다.<br>양동이 물은 여전히 맑았다. 조금 무거워졌을 뿐이다.` },
      ok:`물 위에 손을 펴고 한 겹 걷었다. 두 겹째에서 물이 손바닥을 당겼다. 손을 뺐다.<br><br>손바닥에 걷은 한 겹이 남았다. 지움. 작은 몫이다. 일행 발자국 위에 뿌렸다. 젖은 발자국이 바닥에서 지워졌다. 청소부가 따라올 것이 없다.<br><br>덜어 낸 양동이 물이 조금 탁해졌다. 돌아온 청소부가 그 물을 한참 들여다볼 것이다.`,
      win:{ exp:22, dream:3 } },
    { l:'③ 양동이를 건드리지 않고 쪽문을 찾는다.', k:'sense', dc:20,
      ok:`양동이는 그대로 두었다. 남의 부여는 남의 것이다.<br><br>바닥 물이 기우는 쪽을 따라갔다. 구석에 쪽문이 있다. 문턱 밑으로 바람이 든다.<br>문틈에 녹이 슬었다. 손으로 밀어 열렸다.`,
      ng:`쪽문을 찾아 벽을 더듬다 양동이를 발로 찼다.<br><br>물이 바닥에 쏟아졌다. 맑은 물이 번지는 자리마다 먼지도 얼룩도 사라진다. 이쪽 신발 끝도.<br>발가락 끝이 차다. 신발 앞코가 없다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B2', t:'7층 — 붙잡는 가죽 띠',
  x:`손목이 침대 난간에 묶였다. 가죽 띠. 버클은 손 닿지 않는 쪽에 있다.<br><br>
    부여술사 눈에는 띠 위에 덧입힌 것이 보인다. 붙잡음. 당길수록 조이는 부여다.<br>
    많은 사람이 당겼다. 당긴 힘이 띠에 다 먹혔다.<br><br>
    정각 오 분 전이다.`,
  o:[
    { l:'① 마력을 써서 붙잡음의 결을 뒤집는다.', k:'fix', dc:21, cost:{ mana:22 }, wake:1,
      ok:`당기지 않았다. 띠에 손가락을 대고 덧입힌 것의 결을 읽었다. 조이는 쪽으로 감겨 있다.<br><br>결 반대로 마력을 흘렸다. 붙잡음이 한 바퀴 돌아 놓음이 됐다. 띠가 스르르 풀렸다. 옆 침대 띠도, 그 옆도.<br><br>덧입힌 것은 벗기는 줄만 알았다. 남이 입힌 것을 뒤집어 쓸 수도 있다. 결을 읽는 손가락이 생겼다. 손끝이 아직 그 결을 쥐고 있다.`,
      ng:`결 반대로 흘린다는 게 결을 따라 흘렸다. 띠가 한 번 더 조였다.<br><br>손끝이 하얘진다. 정각이 됐다. 딸깍.<br>손목을 내려다보며 간호사가 고개를 끄덕였다. 잘 묶였다는 듯이.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, mind:-16 } },
    { l:'② 버클 핀을 이로 문다.', k:'evade', dc:20,
      ok:`몸을 비틀어 버클에 얼굴을 댔다. 이로 핀을 물고 당겼다. 이가 시리다.<br><br>핀이 빠졌다. 한쪽이 풀리자 다른 쪽은 손으로 풀었다.<br>마력은 한 방울도 안 썼다. 부여술사도 이가 있다.`,
      ng:`이로 물었는데 핀이 이를 긁었다. 앞니 끝이 깨졌다.<br><br>입안에 쇠 맛과 피 맛.<br>딸깍 소리가 문 앞에서 멈췄다. 입을 다물고 숨을 골랐다. 피를 삼켰다.`,
      win:{ exp:15, dream:1, mana:6 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B3', t:'9호차 — 편도라고 찍힌 표',
  x:`손에 표가 쥐여 있다. 개찰 구멍이 이미 뚫렸다. 행선지 칸은 비었고, 밑에 작게 편도.<br><br>
    부여술사 눈에는 그 글씨 위에 덧입힌 것이 보인다. 돌아가지 못함. 쥔 사람에게 옮겨 붙는 부여다.<br>
    벌써 손바닥에 조금 옮아 왔다. 표를 놓으려는데 손가락이 안 펴진다.<br><br>
    일행 다섯이 다 같은 표를 쥐고 있다.`,
  o:[
    { l:'① 마력을 써서 표의 부여를 벗기고 덧칠한다.', k:'fix', dc:22, cost:{ mana:25 }, wake:1,
      ok:`표를 쥔 채로 엄지로 글씨를 문질렀다. 돌아가지 못함을 한 올씩 벗겼다. 벗겨진 자리에 마력을 얇게 입혔다. 내릴 수 있음.<br><br>손가락이 펴졌다. 다섯 장을 다 그렇게 했다. 손바닥이 따끔하다.<br>표 위의 편도 글씨는 그대로다. 글씨 위의 것이 바뀌었다.<br><br>벗기는 손과 입히는 손이 따로였다. 오늘 한 손짓이 됐다. 엄지가 그 한 번을 기억한다.`,
      ng:`벗기는데 돌아가지 못함이 손가락을 타고 손목까지 올라왔다.<br><br>표를 놓았다. 손은 아직 쥔 모양이다. 펴지지 않는다.<br>한참 주물렀다. 새끼손가락 하나가 끝내 반쯤 굽은 채다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 표를 창밖으로 던진다.', k:'luck', dc:21,
      ok:`창을 한 뼘 열고 표를 던졌다. 비가 표를 낚아챘다. 손가락이 펴졌다.<br><br>행선지 없는 표는 행선지 없는 데로 갔다. 다른 넷도 따라 던졌다.<br>검표원이 오면 표가 없다. 그건 그때 일이다.`,
      ng:`던진 표가 바람에 밀려 도로 창틈으로 들어왔다. 손바닥에 붙었다. 젖어서.<br><br>다시 떼는 데 손바닥 살갗이 같이 벗겨졌다.<br>표는 이번엔 주머니에 넣었다. 주머니 안이 차다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B', t:'쫓기는 골목 — 지나온 바닥',
  x:`좁은 골목을 뛴다. 뒤에서 장화 소리 셋. 가까워진다.<br><br>
    바닥은 젖은 타일이다. 이미 미끄럽다. 조금만 더 미끄러우면 아무도 못 선다.<br>
    부여술사는 땅에도 덧입힐 줄 안다. 넓은 데는 마력이 많이 든다. 이 골목은 좁다.<br><br>
    다만 입힌 땅은 입힌 사람도 안 가린다.`,
  o:[
    { l:'① 마력을 써서 지나온 바닥에 미끄러움을 입힌다.', k:'fix', dc:21, cost:{ mana:24 },
      ok:`맨 뒤에서 뛰며 손바닥을 바닥에 쓸었다. 지나온 타일에 미끄러움을 한 줄로 입혔다.<br><br>뒤에서 장화 하나가 넘어졌다. 둘째가 첫째에 걸렸다. 셋째는 섰다. 서서 바닥을 본다.<br>셋째가 벽을 짚고 온다. 느리다.<br><br>느리면 됐다. 골목 끝 철문을 닫을 시간은 그만큼이다.`,
      ng:`손바닥을 쓸다 이쪽이 먼저 미끄러졌다. 입힌 땅이 입힌 사람을 안 가렸다.<br><br>골목 가운데 엎어졌다. 장화 하나가 등을 밟고 지나갔다.<br>일행이 돌아와 끌어냈다. 등에 장화 바닥 무늬가 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 손을 잡고 한 줄로 뛴다.', k:'bond', dc:20,
      ok:`손을 잡게 했다. 부여는 안 했다. 사람 손은 원래 쥔다.<br><br>하나가 미끄러지면 넷이 세운다. 다섯이 넘어지지 않고 골목을 빠져나왔다.<br>손을 놓을 때 다들 손바닥이 얼얼했다. 아무것도 안 입혔는데 단단했다.`,
      ng:`앞사람이 미끄러지자 손 잡은 줄이 다 같이 넘어졌다.<br><br>다섯이 한 덩어리로 타일 위를 굴렀다.<br>장화 소리가 덩어리 바로 앞에서 멈췄다. 떨어져 뛰느라 팔꿈치가 다 까졌다.`,
      win:{ exp:15, dream:1, spirit:5 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B', t:'공짜 우산 — 손잡이의 표지',
  x:`골목 끝 가게 주인이 우산을 빌려줬다. 검은 우산. 공짜라고 했다. 이 비에 공짜는 없다.<br><br>
    부여술사 눈에는 손잡이에 덧입힌 것이 보인다. 표지. 이 우산이 어디 있는지 누군가 안다.<br>
    빗속에서 우산은 고맙다. 다섯이 한 우산 밑에 붙었다.<br><br>
    멀리서 회색 밴이 천천히 따라온다. 전조등을 끈 채로.`,
  o:[
    { l:'① 마력을 써서 표지를 벗겨 다른 데 옮겨 입힌다.', k:'fix', dc:21, cost:{ mana:24 }, wake:1,
      ok:`손잡이를 쥐고 표지를 한 올씩 벗겼다. 벗긴 것을 손바닥에 쥐었다. 버리지 않았다.<br><br>하수구로 떠내려가는 빈 깡통에 옮겨 입혔다. 깡통이 빗물을 타고 큰길 쪽으로 굴러간다. 회색 밴이 깡통을 따라 큰길로 꺾었다.<br>다섯은 우산 밑에서 반대 골목으로 들어갔다. 우산은 그냥 우산이 됐다.<br><br>벗긴 것은 버리는 줄만 알았다. 다른 데 입히면 그것도 쓸 데가 있다. 남의 부여를 떼어다 붙이는 손이 생겼다. 손바닥이 아직 미지근하다.`,
      ng:`표지를 벗기는데 손잡이가 따뜻해졌다. 벗기는 것을 저쪽도 느낀다.<br><br>회색 밴 전조등이 켜졌다. 골목이 하얘졌다.<br>우산을 버리고 뛰었다. 담을 넘다 손바닥이 철조망에 찢겼다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 우산을 처마 밑에 세워 두고 비를 맞는다.', k:'evade', dc:20,
      ok:`우산을 펼친 채 처마 밑에 세워 두었다. 다섯은 비를 맞고 걸었다. 젖는다. 춥다.<br><br>회색 밴이 처마 앞에 섰다. 한참. 누가 내려서 우산을 본다. 빈 우산이다.<br>공짜로 받은 것은 공짜로 돌려줬다.`,
      ng:`우산을 세우는데 바람이 우산을 채 갔다. 골목 한가운데에 뒤집혀 굴렀다.<br><br>밴 전조등이 켜졌다. 우산이 구른 쪽에 다섯이 서 있었다.<br>흩어져 뛰었다. 다시 모이는 데 반 시진이 걸렸다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B1', t:'냉동 창고 — 언 손끝',
  x:`냉동 창고에서는 숨이 얼어 떨어진다. 손가락이 굳는다.<br><br>
    부여술사의 손은 부여하는 손이다. 손끝이 굳으면 마력이 손끝에서 막힌다. 물건에 닿아도 결이 안 읽힌다.<br>
    구석에 늙은 하역부가 앉아 있다. 두꺼운 장갑을 꼈다. 이쪽 손을 본다.<br><br>
    창고 문은 밖에서 잠겼다. 안에서 열 방법을 찾는 데는 손이 필요하다.`,
  o:[
    { l:'① 마력을 써서 장갑 안감에 따뜻함을 입힌다.', k:'heal', dc:21, cost:{ mana:22 },
      ok:`제 손을 겨드랑이에 넣어 녹이고, 녹은 손끝으로 일행 장갑 안감을 하나씩 훑었다. 따뜻함을 얇게. 두껍게 입히면 땀이 나고, 땀은 언다.<br><br>다섯 손이 풀렸다. 손이 풀리자 문 경첩이 보였다. 손톱으로 핀을 뽑을 수 있는 경첩이다.<br>장갑 낀 손으로 핀을 뽑았다. 하역부가 그걸 보고 고개를 끄덕였다. 처음으로.`,
      ng:`따뜻함을 너무 두껍게 입혔다. 장갑 안이 땀으로 젖었다.<br><br>젖은 장갑은 금방 언다. 손가락이 장갑 안에서 붙었다.<br>벗기는 데 살갗이 같이 벗겨졌다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 하역부에게 장갑을 빌린다.', k:'bond', dc:20,
      ok:`하역부 앞에 쪼그려 앉아 손을 내밀었다.<br><br>하역부가 한참 보다가 장갑 한 짝을 벗어 줬다. 다른 손은 낀 채다. 한 짝이면 한 손은 쓴다.<br>하역부가 남은 손으로 문 경첩 쪽을 가리켰다. 말은 없었다.<br><br>장갑 속에 말린 고기 한 줄이 들어 있었다. 하역부 몫이었다.`,
      ng:`손을 내밀자 하역부가 고개를 돌렸다. 다시 내밀었다.<br><br>하역부가 이쪽 손목을 잡았다. 장갑 안의 손이 이쪽보다 차다. 그 손이 놓아주지 않는다.<br>한참 뒤에 놓았다. 손목에 서리 자국이 남았다.`,
      win:{ exp:15, dream:1, item:'말린 고기' }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B2', t:'처치실 — 잠을 입힌 바늘',
  x:`처치실 쟁반에 주사기가 줄지어 놓였다. 다 같은 양. 이름표는 없다. 침대 번호만.<br><br>
    부여술사 눈에는 바늘마다 덧입힌 것이 보인다. 잠. 깊고 오래가는 잠. 정각에 숫자가 안 맞는 침대에 놓는 것이다.<br>
    복도에서 딸깍 소리가 다가온다. 간호사가 쟁반을 가지러 온다.<br><br>
    계수기가 딸깍일 때마다 바늘들이 조금씩 떤다.`,
  o:[
    { l:'① 마력을 써서 바늘의 잠을 덜어 계수기에 입힌다.', k:'fix', dc:22, cost:{ mana:26 }, wake:1,
      ok:`바늘 위로 손을 펴고 잠을 덜었다. 한 바늘에 한 줌. 손바닥에 잠이 고인다. 무겁고 축축하다.<br><br>간호사가 들어와 쟁반을 들었다. 그 순간 계수기 쥔 손등을 스치며 덜어 둔 잠을 계수기에 입혔다.<br>간호사가 복도로 나간다. 딸깍. 딸깍. 소리가 점점 느려진다. 세 칸 뒤에 멎었다. 계수기가 잔다. 간호사가 계수기를 흔들며 서 있다. 숫자가 안 오른다.<br><br>사람에게 입히려던 것을 물건에 입혔다. 무엇을 입힐지보다 어디에 입힐지가 큰 셈이다. 손이 그 셈을 먼저 했다.`,
      ng:`잠을 더는데 바늘 하나가 손바닥을 찔렀다. 잠이 이쪽으로 들어왔다.<br><br>눈꺼풀이 무겁다. 일행이 뺨을 쳤다. 반쯤 깬 채로 질질 끌려 나왔다.<br>복도를 반이나 와서야 다리에 감각이 돌아왔다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-14 } },
    { l:'② 쟁반을 세면대에 엎는다.', k:'break', dc:20,
      ok:`쟁반을 들어 세면대에 엎었다. 주사기가 물에 잠겼다. 물이 잠을 먹었다.<br><br>수돗물이 고요해졌다. 흐르는데 소리가 없다.<br>간호사가 들어와 빈 쟁반을 보고 한참 서 있었다. 그리고 다른 쟁반을 가지러 갔다.`,
      ng:`엎는 소리가 컸다. 주사기가 바닥에 흩어졌다.<br><br>복도 딸깍 소리가 뛰기 시작했다.<br>바닥의 바늘 하나를 밟았다. 발바닥이 저리다. 다리가 무거워진다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'③ 바늘 하나를 쥐어 누구 몫인지 읽는다.', k:'gaze', dc:21,
      doom:{ title:'정각의 잠', what:'잠든 채 처치실 안쪽으로 실려 갑니다', dc:17, sec:55,
        text:`바늘 하나를 쥐고 결을 읽었다. 침대 번호가 아니다. 결 속에 이쪽 이름이 있다.<br><br>읽는 사이 잠이 손가락으로 번진다. 무릎이 꺾였다. 바닥이 차다. 차다는 것만 안다.<br>딸깍. 간호사가 들어와 이쪽을 내려다본다.<br><br>침대 바퀴 소리가 난다. 실린다. 처치실 안쪽, 문이 하나 더 있는 쪽으로.`,
        dieText:`정각에 숫자는 맞았다.<br><br>처치실 안쪽 방 침대에 한 사람이 잔다. 깊고 오래.<br>부여를 볼 줄 알던 사람이다. 잠도 결대로 들었다.` },
      ok:`바늘 하나를 쥐고 결을 읽었다. 침대 번호가 아니라 이름이 있다. 일행 하나의 이름이다.<br><br>손가락으로 잠이 번지려 했다. 바늘을 놓았다.<br>그 바늘만 꺼내 세면대 하수구에 버렸다. 이름이 든 바늘은 하나뿐이었다.<br><br>정각에 그 이름은 안 잔다. 다른 바늘들은 번호만 안다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'B3', t:'식당칸 — 빨간 외투',
  x:`식당칸 창가 의자에 빨간 외투가 걸려 있다. 주인은 없다. 의자는 따뜻하다.<br><br>
    부여술사 눈에는 외투 안감에 덧입힌 것이 보인다. 빌림. 입은 것에게 남의 얼굴을 빌려 주는 부여다. 안감에 얼굴 자국이 겹겹이 배었다.<br>
    얼굴 바꾸는 손님의 옷이다. 벗어 놓고 어딘가 갔다.<br><br>
    돌아오면 다시 입을 것이다.`,
  o:[
    { l:'① 안감의 얼굴 자국을 읽는다.', k:'gaze', dc:21,
      ok:`안감을 손끝으로 훑었다. 얼굴 자국이 하나씩 읽힌다. 검표원, 면도하던 남자, 웨이터.<br><br>맨 위 자국은 아직 마르지 않았다. 일행 하나의 얼굴이다. 그 얼굴을 쓰려고 준비했다.<br>그런데 그 자국에는 오른쪽 귀가 없다. 빌림은 다 빌리지 못했다.<br><br>일행에게 말했다. 그 얼굴이 다시 오면, 오른쪽 귀를 보라고.`,
      ng:`훑는 손끝에 얼굴 자국이 묻었다. 이쪽 손등에 남의 눈썹 모양이 비친다.<br><br>문질러도 안 지워진다.<br>한동안 이쪽을 보는 일행 눈이 낯설었다. 이쪽 얼굴이 조금 다른 모양이었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 마력을 써서 외투에 무거움을 입혀 의자에 붙인다.', k:'fix', dc:21, cost:{ mana:24 },
      ok:`외투 어깨를 쥐고 무거움을 입혔다. 의자에 걸린 채로. 외투가 쇳덩이처럼 처졌다. 의자가 삐걱한다.<br><br>한참 뒤 통로 끝에서 누가 돌아왔다. 외투를 들려다 못 들었다. 두 손으로 당긴다. 꿈쩍 않는다.<br>얼굴이 웨이터에서 검표원으로, 다시 웨이터로 바쁘게 바뀐다.<br><br>그사이 다섯이 식당칸 끝을 지났다. 옷이 없으면 얼굴도 오래 못 간다.`,
      ng:`무거움을 입히는데 외투가 이쪽 팔에 감겼다. 빌림이 먼저였다.<br><br>소매가 이쪽 팔을 꿴다. 입혀 주려는 것이다.<br>뿌리치느라 의자가 넘어졌다. 통로 끝에서 발소리가 돌아왔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-22, spirit:-16 } }
  ] },

{ at:'B', t:'계단참 — 바닥난 마력',
  x:`밤새 입히고 벗겼다. 손끝이 하얗다. 마력이 바닥에 가깝다.<br><br>
    일행 하나가 다리를 전다. 다음 계단은 길다.<br>
    부여술사는 남은 마력으로 할 수 있는 게 하나뿐이라는 걸 안다. 하나에 다 입히면 다른 넷은 맨몸이다.<br><br>
    비는 그치지 않는다.`,
  o:[
    { l:'① 마력을 써서 저는 무릎 하나에 몰아 입힌다.', k:'fix', dc:20, cost:{ mana:20 },
      ok:`그 사람 무릎을 두 손으로 감싸고 남은 마력을 다 흘렸다. 굳음. 무릎이 흔들리지 않게.<br><br>그 사람이 일어섰다. 계단을 내려간다. 절지 않는다.<br>이쪽 손은 떨린다. 떨리는 손으로는 아무것도 안 입혀진다. 다음 계단까지 이쪽은 맨손이다.<br><br>그래도 된다. 맨손도 손이다.`,
      ng:`흘리는데 마력이 중간에 끊겼다. 무릎 반만 굳었다.<br><br>그 사람이 한 걸음 디디다 반만 굳은 무릎이 꺾였다. 계단에서 미끄러졌다.<br>받아 내느라 이쪽 팔이 계단 모서리에 찍혔다.`,
      win:{ exp:18, dream:2, spirit:5 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 입히지 않고 앉아서 마력을 고인다.', k:'steady', dc:19,
      ok:`계단참에 앉아 눈을 감았다. 빗소리를 들으며 숨을 셌다.<br><br>마력은 쉬면 고인다. 천천히.<br>저는 사람은 다른 일행 어깨에 기대 내려갔다. 느렸다. 느린 사이 손끝에 핏기가 돌아왔다.`,
      ng:`눈을 감자 빗소리 사이로 다른 소리가 섞였다. 계단 아래에서 올라오는 발소리.<br><br>눈을 뜨고 일어섰다. 쉬지 못했다. 마력도 안 고였다.<br>손끝은 그대로 하얗다.`,
      win:{ exp:14, dream:1, mana:8 }, lose:{ mind:-14, spirit:-14 } }
  ] },

{ at:'B', t:'번지는 지도',
  x:`지도 한 장. 길에서 만난 노인에게서 받았다. 연필로 그렸다. 비에 번지기 시작한다.<br><br>
    골목 셋이 벌써 하나로 번졌다.<br>
    부여술사는 종이에 막음을 입힐 수 있다. 물이 종이를 모르게.<br><br>
    다만 막음을 입힌 종이는 접히지 않는다. 품에 못 넣는다. 손에 들고 다녀야 한다.`,
  o:[
    { l:'① 마력을 써서 지도에 막음을 입힌다.', k:'fix', dc:20, cost:{ mana:22 },
      ok:`지도를 손바닥에 펴고 막음을 얇게 입혔다. 번지던 연필 선이 멈췄다. 빗방울이 지도 위에서 구슬처럼 굴러 떨어진다.<br><br>손에 든 지도는 손 하나를 묶는다. 나머지 한 손으로 다 했다.<br>지도대로 갔다. 번진 골목 셋이 하나가 아니었다는 걸 알았다. 막지 않았으면 몰랐다.`,
      ng:`막음을 입히는데 이미 번진 데까지 굳었다. 번진 대로 굳었다.<br><br>셋째 골목이 없다. 지도에 없는 골목에서 장화 소리가 나왔다.<br>지도 든 손을 들어 막다 손등을 맞았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 다 같이 나눠 외우고 버린다.', k:'sense', dc:20,
      ok:`다 번지기 전에 다섯이 같이 봤다. 한 칸씩 외우게 했다. 둘째는 첫 갈림, 셋째는 다리, 넷째는 철문.<br><br>지도를 하수구에 버렸다.<br>다섯의 머리가 지도가 됐다. 머리는 안 젖는다.`,
      ng:`외우는 사이 지도가 다 번졌다. 다섯이 외운 칸이 서로 다르다.<br><br>갈림길마다 다퉜다.<br>다투는 소리를 듣고 무언가 골목 끝에서 걸음을 돌렸다.`,
      win:{ exp:15, dream:1, mind:5 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B1', t:'경매장 — 갈고리 장대',
  x:`경매가 시작됐다. 노란 비옷들이 갈고리 장대로 경매장 바닥을 훑는다. 생선 상자를 끌듯 바닥을 긁는다.<br><br>
    바닥은 얼음물이 흐르는 콘크리트다. 장대 끝 갈고리는 녹슬었지만 날카롭다.<br>
    부여술사는 날에 날카로움만 입히는 사람이 아니다. 날에서 빼는 법도 안다.<br><br>
    장대 다섯이 이쪽 줄로 다가온다.`,
  o:[
    { l:'① 마력을 써서 갈고리 끝에 무딤을 입힌다.', k:'fix', dc:21, cost:{ mana:24 },
      ok:`가장 가까운 장대가 이쪽 상자를 걸려고 내려올 때, 갈고리 끝을 손바닥으로 쳐 냈다. 치면서 무딤을 입혔다.<br><br>갈고리가 상자를 긁고 미끄러졌다. 다시 걸어도 안 걸린다. 쇠 끝이 숟가락처럼 둥글다.<br>비옷이 장대를 들여다본다. 그 틈에 다섯이 얼음 더미 뒤로 빠졌다.<br><br>장대 다섯 중 하나는 이제 무엇도 못 끈다.`,
      ng:`쳐 내는 손바닥에 갈고리가 먼저 걸렸다. 무딤이 들어가기 전이다.<br><br>끌려가다 상자를 붙잡고 버텼다.<br>손바닥이 찢기며 빠졌다. 비옷은 장대 끝에 묻은 것을 털고 다음 상자로 갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-12 } },
    { l:'② 얼음 더미 속에 몸을 묻는다.', k:'hide', dc:21,
      ok:`얼음 더미에 몸을 묻었다. 차다. 장대가 얼음 위를 긁고 지나간다. 얼음 밑은 안 긁는다.<br><br>얼음 속에 민물고기가 섞여 있었다. 얼어서 싱싱하다.<br>하나를 쥐고 나왔다.`,
      ng:`얼음 속에서 숨을 오래 참았다. 입술이 파래졌다.<br><br>장대가 지나갔다. 나오려는데 다리가 얼음에 붙었다.<br>떼는 데 바지와 살갗이 같이 남았다.`,
      win:{ exp:15, dream:1, item:'민물고기' }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B2', t:'세단실 — 사진 붙은 서류',
  x:`세단실에서 기계가 운다. 종이를 먹는 소리. 직원 하나가 서류를 한 장씩 넣는다.<br><br>
    서류마다 사진이 붙었다. 이쪽 일행 사진이 다섯 장. 넣을 차례가 가까워진다.<br>
    부여술사 눈에는 세단기 날 위에 덧입힌 것이 보인다. 지워짐. 갈린 종이에 적힌 사람은 바깥에서도 흐려진다.<br><br>
    세 장 남았다.`,
  o:[
    { l:'① 마력을 써서 세단기 날에 무딤을 입힌다.', k:'fix', dc:21, cost:{ mana:22 },
      ok:`직원이 돌아선 틈에 투입구에 손을 댔다. 날이 손끝 바로 밑에서 돈다. 날 위에 무딤을 입혔다.<br><br>다음 서류가 들어갔다. 갈리지 않고 구겨져서 나왔다. 직원이 들여다본다. 사진은 그대로다. 다시 넣는다. 또 구겨진다.<br>그사이 다섯 장을 다 빼 왔다. 구겨진 채로.<br><br>구겨진 얼굴도 얼굴이다. 펴면 된다.`,
      ng:`날 위에 손을 대는 순간 날이 손톱 끝을 물었다. 손톱이 갈려 들어갔다.<br><br>손을 뺐다. 손가락 끝이 피투성이다.<br>직원이 돌아본다. 다음 서류를 들고.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 서류 더미에서 사진 붙은 장만 빼낸다.', k:'luck', dc:20,
      ok:`직원 뒤 서류 더미에서 사진 붙은 장을 골라 빼냈다. 다섯 장. 대신 아무 장이나 넣어 두었다.<br><br>직원은 장수만 센다. 장수는 맞다.<br>빼낸 서류 뒷면에 침대 번호가 적혀 있다. 7층의 번호들이다.`,
      ng:`빼내다 한 장이 바닥에 떨어졌다. 직원이 주웠다. 사진을 본다. 이쪽 얼굴을 본다.<br><br>서류를 세단기에 넣었다. 갈리는 소리가 났다.<br>일행 하나가 잠깐 휘청였다. 그 사람 이름이 한동안 아무 입에서도 안 나왔다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B3', t:'등기 금고 — 두 겹의 자물쇠',
  x:`우편칸 끝에 등기 금고. 사람 키만 한 쇠상자다. 자물쇠에 숫자판이 없다. 열쇠 구멍도 없다.<br><br>
    부여술사 눈에는 자물쇠 위에 덧입힌 것이 보인다. 닫힘. 그 밑에 한 겹 더. 들임.<br>
    금고 안에서 무언가 두드린다. 똑똑. 열어 달라는 박자다.<br><br>
    문틈으로 열쇠 꾸러미 고리가 비어져 나와 있다. 꼬리표에 기관실.`,
  o:[
    { l:'① 닫힘을 벗겨 문을 연다.', k:'fix', dc:22,
      doom:{ title:'들이는 금고', what:'금고 안으로 끌려 들어갑니다', dc:17, sec:50,
        text:`닫힘을 한 겹 벗겼다. 문이 한 뼘 열렸다.<br><br>밑에 있던 들임이 드러났다. 그것이 이쪽 손을 먼저 들였다. 손목, 팔꿈치. 금고 안은 금고보다 깊다.<br>안에서 두드리던 손이 이쪽 어깨를 잡는다. 반갑게.<br><br>문이 닫히려 한다. 이쪽을 안에 두고.`,
        dieText:`금고는 다시 닫혔다. 닫힘이 한 겹 새로 입혀졌다.<br><br>안에서 두드리는 소리가 둘이 됐다. 똑똑, 똑똑.<br>열쇠 꾸러미 고리는 그대로 문틈에 걸려 있다. 다음 사람을 위해.` },
      ok:`닫힘을 벗기기 전에 밑의 들임부터 짚었다. 그 결 위에 막음을 덧대 눌러 두었다. 그다음 닫힘을 벗겼다.<br><br>문이 한 뼘 열렸다. 안의 손이 나오려 한다. 막음에 걸린다.<br>그 틈에 열쇠 꾸러미만 잡아 뺐다. 문을 놓았다.<br><br>안에서 두드리는 박자가 빨라졌다. 다시는 안 열었다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 금고를 두고 지나간다.', k:'steady', dc:20,
      ok:`두드리는 소리를 등지고 금고 옆을 지나갔다. 열쇠는 없다. 기관실 문은 다른 길로 연다.<br><br>안의 것이 열어 달라고 할 때는 안 여는 게 맞다.<br>두드리는 박자가 멀어진다.`,
      ng:`지나가는데 두드리는 소리가 일행 목소리로 바뀌었다. 열어 줘.<br><br>일행 하나가 걸음을 멈췄다. 그 사람 팔을 잡아끌었다. 그 사람이 이쪽 손을 물었다.<br>한참 뒤에야 제정신이 돌아왔다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-22, spirit:-16 } }
  ] },

{ at:'B', t:'정전 — 제 눈에 입히기',
  x:`네온이 꺼졌다. 정전이다. 비 오는 골목이 통째로 까맣다.<br><br>
    손전등은 켜면 들킨다. 일행이 서로의 옷자락을 더듬는다.<br>
    부여술사는 불에 밝음을 입혀 왔다. 횃불에, 등잔에. 눈에 입혀 본 적은 없다. 제 눈에는 더욱.<br><br>
    제 눈은 거울 없이 제 등을 보는 것처럼 멀다.`,
  o:[
    { l:'① 마력을 써서 제 눈에 밝음을 입힌다.', k:'gaze', dc:22, cost:{ mana:25 }, wake:1,
      ok:`눈을 감고 눈꺼풀 위에 손끝을 얹었다. 마력을 아주 조금씩. 불에 입히듯 하면 눈이 탄다.<br><br>눈을 떴다. 어둠이 회색이다. 벽의 금, 웅덩이의 깊이, 모퉁이 너머 장화 끝. 다 보인다.<br>빛을 만든 게 아니다. 보는 쪽을 바꿨다. 일행 손을 잡아 이끌고 골목을 빠져나왔다.<br><br>밖에 입히는 줄만 알았다. 안에도 입혀진다. 제 몸이 처음으로 부여할 물건이 됐다. 눈이 따끔하다. 그 따끔함을 다음에도 찾을 것이다.`,
      ng:`마력이 눈꺼풀에서 멈추지 않고 들어갔다. 너무 밝다. 어둠이 하얗다. 아무것도 안 보인다.<br><br>눈물이 쏟아진다. 일행이 이쪽을 끌고 갔다.<br>한참 동안 눈 안에 하얀 얼룩이 떠 있었다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-22, mind:-16 } },
    { l:'② 벽에 손을 대고 더듬어 간다.', k:'sense', dc:20,
      ok:`오른손을 벽에 대고 걸었다. 벽이 꺾이면 꺾었다. 일행은 이쪽 허리띠를 잡고 줄줄이.<br><br>느리다. 그래도 벽은 거짓말을 안 한다.<br>골목 끝에서 네온이 다시 켜졌다.`,
      ng:`벽을 짚고 가는데 벽이 따뜻해졌다. 벽이 아니다. 비옷 등이다. 서 있던 사람이다.<br><br>그 사람이 천천히 돌아선다.<br>손을 떼고 뒷걸음질했다. 일행이 줄줄이 넘어졌다.`,
      win:{ exp:14, dream:1 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B2', t:'세탁실 — 다림질된 가운',
  x:`다림질대 옆에 가운이 줄줄이 걸렸다. 흰 가운, 빳빳하다. 명찰 자리에 숫자.<br><br>
    부여술사 눈에는 가운마다 덧입힌 것이 보인다. 셈에서 빠짐. 이 가운을 입은 사람은 점검에서 세지 않는다. 직원이니까.<br>
    그 밑에 한 겹 더 있다. 오래 입으면 벗겨지지 않음.<br><br>
    복도 끝에서 보호사 둘이 이쪽으로 걸어온다.`,
  o:[
    { l:'① 마력을 써서 밑의 한 겹만 벗기고 입힌다.', k:'fix', dc:22, cost:{ mana:26 }, wake:1,
      ok:`가운 다섯 벌을 내려 하나씩 안감을 훑었다. 벗겨지지 않음을 한 올씩 뽑았다. 셈에서 빠짐은 남겼다.<br><br>다섯이 입었다. 보호사 둘이 지나간다. 고개를 까딱한다. 동료에게 하듯.<br>다음 층에서 가운을 벗었다. 잘 벗겨졌다.<br><br>겹친 부여는 통째로 벗기거나 통째로 두는 줄 알았다. 한 겹만 골라 남길 수도 있다. 겹을 갈라 보는 눈이 생겼다. 손가락이 그 사이를 안다.`,
      ng:`벗기다 다섯째 가운에서 시간이 다 됐다. 그 사람은 두 겹 다 입었다.<br><br>다음 층에서 가운이 안 벗겨진다. 단추를 뜯어도 천이 살에 붙었다.<br>한참 걸려 찢어 벗겼다. 그 사람 등에 흰 실 자국이 남았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 세탁 수레에 들어가 시트를 덮는다.', k:'hide', dc:21,
      ok:`세탁 수레에 둘씩 들어가 젖은 시트를 덮었다. 이쪽이 수레를 밀었다.<br><br>보호사 둘이 지나간다. 수레는 안 본다. 수레는 늘 지나간다.<br>승강기 앞에서 시트를 걷었다. 다들 젖었다. 표백제 냄새가 오래 남았다.`,
      ng:`수레 바퀴 하나가 삐걱댔다. 보호사가 섰다. 시트 끝을 들춘다.<br><br>손가락이 이쪽 발목에 닿았다.<br>수레를 밀어 버리고 뛰었다. 다들 수레에서 굴러 나왔다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B1', t:'선착장 — 선체와 부두 사이',
  x:`해무호가 부두에 붙었다. 선체와 부두 사이에 검은 물이 출렁인다. 한 걸음 반.<br><br>
    배에 오를 생각은 없다. 배 갑판을 밟고 반대편 부두로 건너가야 한다.<br>
    부두 기둥에 밧줄이 걸려 있다. 낡았다. 젖었다.<br><br>
    파도가 칠 때마다 배와 부두 사이가 벌어졌다 붙는다. 붙을 때 사람 다리 하나쯤은 그냥 으깨진다.`,
  o:[
    { l:'① 마력을 써서 밧줄에 질김을 입혀 난간에 건다.', k:'fix', dc:21, cost:{ mana:24 },
      ok:`밧줄을 훑으며 질김을 입혔다. 젖은 올마다. 배 난간에 던져 걸었다. 팽팽하다.<br><br>다섯이 밧줄을 잡고 벌어질 때 넘었다. 배가 붙을 때 줄도 같이 휘었다 돌아온다. 끊어지지 않는다.<br>갑판을 지나 반대편 부두로 내려섰다.<br><br>갑판 아래 화물칸에서 누가 문을 두드렸다. 대답하지 않았다.`,
      ng:`질김을 입히는데 줄 중간이 이미 썩어 있었다. 입힌 데와 안 입힌 데 사이가 끊어졌다.<br><br>둘째 사람이 줄과 함께 떨어졌다. 배가 붙기 직전에 끌어 올렸다.<br>이쪽 팔이 배와 부두 사이에 낄 뻔했다. 소매가 찢겨 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-12 } },
    { l:'② 붙는 순간에 뛰어 건넌다.', k:'evade', dc:21,
      doom:{ title:'벌어지는 틈', what:'선체와 부두 사이로 빨려 들어갑니다', dc:18, sec:45,
        text:`배가 붙는 순간 뛰었다. 갑판에 발이 닿았다.<br><br>젖은 철판이다. 발이 미끄러졌다. 뒤로. 배가 벌어진다. 틈이 넓어진다.<br>검은 물이 발목을 잡는다. 아래로 당긴다. 물이 아니라 손 같다.<br><br>배가 다시 붙으러 온다.`,
        dieText:`해무호는 다섯 시 십 분에 떴다.<br><br>부두와 배 사이 검은 물에 무언가 떠올랐다가 가라앉았다.<br>청소부의 수첩에 줄이 하나 그어졌다. 수첩을 닫는 손이 서두르지 않았다.` },
      ok:`배가 붙는 순간 뛰었다. 젖은 철판에 발이 미끄러졌다.<br><br>무릎을 꿇으며 몸을 앞으로 던졌다. 난간 기둥을 잡았다. 등 뒤에서 배와 부두가 쿵 붙었다.<br>일어나 손을 뻗었다. 뒤따라 뛰는 일행을 하나씩 받았다.<br><br>반대편 부두로 내려섰다. 무릎이 철판 맛을 한참 기억했다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'B3', t:'기관실 — 비상 제동 손잡이',
  x:`진짜 기관사가 바닥에서 손잡이를 가리킨다. 비상 제동. 둘이 당겨야 한다. 녹슬었다. 한 번도 당긴 적 없는 손잡이다.<br><br>
    둘이 당겨도 모자랄 것 같다. 열차가 너무 빠르다.<br>
    부여술사는 사람에게 힘을 입혀 본 적이 있다. 하나에게 하나씩. 둘에게 한꺼번에 같은 힘을 입힌 적은 없다.<br><br>
    창밖에 종착역 불빛이 보인다.`,
  o:[
    { l:'① 마력을 써서 두 팔을 한 힘으로 묶는다.', k:'fix', dc:22, cost:{ mana:28 }, wake:1,
      ok:`일행 하나와 손잡이를 같이 쥐었다. 이쪽 손등을 그 사람 손등 위에 겹쳤다. 마력을 둘에게 한꺼번에 흘렸다.<br><br>하나의 힘을 둘로 나누는 게 아니다. 둘을 하나로 묶었다. 당겼다. 손잡이가 끽 울며 내려왔다. 쇠가 쇠를 문다.<br>열차가 비명을 지르며 느려진다. 종착역 불빛이 다가오다 멈췄다. 손을 놓았는데 둘의 손바닥이 한참 같이 떨렸다. 같은 박으로.<br><br>하나에 하나씩 입히던 손이 둘을 한 물건처럼 입혔다. 사람과 사람 사이도 덧입힐 자리다. 손이 그 자리를 찾았다.`,
      ng:`둘에게 흘리는데 마력이 둘 사이에서 엇갈렸다. 그 사람 팔에는 힘이, 이쪽 팔에는 무거움이 들어갔다.<br><br>손잡이가 반만 내려왔다. 열차가 덜컹이며 비틀렸다.<br>둘 다 계기판에 처박혔다. 이마가 찢겼다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-32, mind:-12 } },
    { l:'② 마력을 써서 손잡이 끝에 무거움을 입힌다.', k:'steady', dc:21, cost:{ mana:24 },
      ok:`손잡이 끝에 무거움을 입히고 둘이 매달렸다. 손잡이가 제 무게로 내려간다. 천천히.<br><br>열차가 느려진다. 천천히.<br>종착역 바로 앞에서 섰다. 문이 열렸다. 빗소리가 들어왔다.`,
      ng:`무거움을 너무 많이 입혔다. 손잡이가 뿌리째 부러졌다.<br><br>부러진 쇠막대를 쥔 채 둘이 바닥에 떨어졌다. 열차는 그대로 달린다.<br>기관사가 다른 손잡이를 가리킨다. 손이 떨려 잘 안 가리켜진다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-14 } }
  ] },

{ at:'B', t:'막다른 골목 — 녹슨 경첩',
  x:`막다른 골목이다. 끝에 녹슨 철문. 잠겼다. 뒤에서 발소리가 골목으로 들어온다.<br><br>
    문은 두껍다. 자물쇠는 새것이다. 경첩만 오래됐다.<br>
    부여술사가 단단하게만 하는 줄 아는 사람이 많다. 무르게도 한다.<br><br>
    무른 것은 한 번 무르면 못 돌린다.`,
  o:[
    { l:'① 마력을 써서 경첩에 무름을 입힌다.', k:'break', dc:21, cost:{ mana:25 },
      ok:`경첩 셋에 손바닥을 대고 차례로 무름을 입혔다. 쇠가 진흙처럼 물러진다. 손가락으로 밀자 핀이 휘었다.<br><br>어깨로 문을 밀었다. 경첩 쪽이 먼저 떨어져 문이 비스듬히 넘어갔다. 자물쇠는 잠긴 채로 버텼다. 문 없는 자물쇠다.<br><br>이 문은 다시 못 닫는다. 쫓아오는 쪽도 이 문을 지날 것이다. 그건 다음 셈이다.`,
      ng:`첫 경첩에 무름을 입히는데 손바닥 밑에서 녹이 같이 물러졌다. 녹물이 손바닥에 스몄다.<br><br>손이 무르다. 쥐어지지 않는다.<br>둘째 경첩까지 하고 손이 떨렸다. 발소리가 골목 안쪽까지 들어섰다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 문 말고 문틀을 살핀다.', k:'gaze', dc:20,
      ok:`문 말고 문틀을 봤다. 벽돌 사이 시멘트가 위쪽만 새것이다. 아래쪽은 오래됐다.<br><br>아래쪽 벽돌 하나를 뽑으니 바깥 빛이 들어온다. 쥐구멍처럼 넓혀 기어 나갔다.<br>문은 잠긴 채로 남았다. 잠긴 문을 지키는 쪽은 문만 본다.`,
      ng:`문틀을 살피는데 문틀 위에 덧입힌 것이 보였다. 다가오지 마. 오래된 부여다.<br><br>손을 대기도 전에 그 말이 머리를 먼저 쳤다.<br>귀에서 피가 났다. 한동안 빗소리가 한쪽 귀로만 들렸다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-20, spirit:-18 } }
  ] },

{ at:'B', t:'마지막 문 — 벗겨지지 않는 것',
  x:`마지막 문 앞이다. 다섯이 다 지쳤다. 손이 떨린다. 문 너머는 비다. 비 너머가 끝이다.<br><br>
    문 앞에 무언가 서 있다. 다섯이 한 번에 지나야 한다. 하나라도 떨면 그것이 그 하나를 잡는다.<br>
    부여술사는 손목에 굳음을 입혀 본 적이 있다. 오래 안 갔다. 덧입힌 것은 손을 떼면 벗겨진다.<br><br>
    이번에는 문을 지날 때까지 손을 떼고 있어야 한다.`,
  o:[
    { l:'① 마력을 써서 다섯 손에 입히고 그 손에 쥐여 준다.', k:'fix', dc:22, cost:{ mana:28 }, wake:1,
      ok:`한 사람씩 손을 잡았다. 짧게. 굳음을 입혔다. 이번에는 입히고 나서 그 사람 손을 그 사람 다른 손으로 쥐게 했다. 제 손으로 제 것을 붙잡게.<br><br>손을 뗐다. 벗겨지지 않는다. 덧입힌 것을 그 사람이 쥐고 있다. 다섯이 한 번에 지났다. 그것이 손을 뻗다가 거두었다. 떠는 손이 없다.<br>문 밖 빗속에서 다들 제 손을 내려다본다. 아직 굳다.<br><br>이제 그건 그 사람 것이다. 입히는 일이 건네는 일이 됐다. 손이 그 차이를 알았다.`,
      ng:`넷째 사람 손에서 마력이 미끄러졌다. 떨림이 이쪽으로 왔다. 다섯째인 이쪽 손이 제일 떨렸다.<br><br>문을 지나는데 그것의 손이 이쪽 소매를 잡았다.<br>소매가 찢겨 남았다. 팔에 손가락 자국이 새파랗다.`,
      win:{ exp:25, dream:4, spirit:6 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 아무것도 입히지 않고 다섯이 손을 잡는다.', k:'bond', dc:21,
      ok:`손을 잡았다. 다섯이 한 줄. 떠는 손을 양옆이 쥔다. 떨림이 양옆으로 나뉘어 옅어진다.<br><br>부여 없이 지났다. 그것이 고개를 갸웃했다.<br>사람 손이 사람 손에 입힌 것은 그것 눈에 안 보인다.`,
      ng:`손을 잡은 줄 가운데가 떨었다. 떨림이 줄을 타고 다섯에게 다 갔다.<br><br>그것이 줄 가운데를 잡았다. 다섯이 같이 버텼다.<br>가운데 사람 어깨가 빠졌다. 빠진 어깨를 끼우는 데 빗속에서 한참 걸렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] }

]);

// ── 분대장 ────────────────────────────────
kJob('squad', 'B', [

{ at:'B', t:'처마 밑 점호 — 대답 여섯',
  x:`처마 밑에서 머릿수를 셌다. 빗소리가 커서 크게 불렀다.<br><br>
    <span style="color:#d4af37;">"번호!"</span><br>
    하나, 둘, 셋, 넷, 다섯. 여섯.<br><br>
    분대장은 숫자가 모자라면 찾으러 간다. 남으면 어떻게 하는지는 아무도 안 가르쳐 줬다.<br>
    여섯째 대답은 처마 끝 빗줄기 너머에서 났다.`,
  o:[
    { l:'① 대답 대신 손을 잡게 하고 다시 센다.', k:'fix', dc:21, wake:1,
      ok:`말로 세지 않았다. 손을 내밀었다. 하나씩 이쪽 손을 잡게 했다.<br><br>손바닥으로 셌다. 굳은살, 떨림, 젖은 장갑. 다 아는 손이다. 다섯. 여섯째는 손을 내밀지 않았다. 빗줄기 너머에서 대답만 한 번 더 했다. 여섯.<br>그쪽을 등지고 다섯을 데리고 처마 밑을 떠났다.<br><br>목소리는 빌릴 수 있다. 손은 못 빌린다. 귀로 세던 셈이 손바닥으로 내려왔다. 손바닥이 이제 분대를 외운다.`,
      ng:`손을 내밀었는데 손 여섯이 잡혔다. 하나가 차다. 아주 차다.<br><br>그 손이 놓지 않는다. 빗속으로 당긴다. 다른 손들이 이쪽 허리를 끌어안아 버텼다.<br>겨우 뺐다. 손등에 손톱 자국이 다섯.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-14 } },
    { l:'② 무력을 써서 여섯째 쪽으로 몸을 던진다.', k:'break', dc:21, cost:{ might:24 },
      ok:`대답한 쪽으로 어깨부터 몸을 던졌다. 빗줄기를 뚫었다.<br><br>아무것도 없다. 벽이다. 어깨가 벽을 쳤다. 벽 밑 하수구 쇠창살 틈에서 무언가 물러났다.<br>다시 셌다. 다섯.<br><br>쫓으면 숫자가 맞는다. 분대장은 그 한 번을 안다.`,
      ng:`몸을 던졌는데 빗줄기 너머가 비탈이었다. 굴렀다.<br><br>다섯이 뛰어와 끌어올렸다.<br>굴러 떨어진 사이 처마 밑에서 대답이 한 번 더 났다. 아무도 안 불렀는데.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B1', t:'3번 창고 — 벽을 보고 앉은 사람',
  x:`창고 구석에 사람 하나가 벽을 보고 앉아 있다. 작업복. 무릎을 끌어안았다. 등이 떨린다.<br><br>
    칠판에는 다섯이라고 적혔다. 일행이 다섯이다. 이 사람까지면 여섯이다.<br>
    분대장은 분대 밖의 사람도 센다. 세고 나면 책임이 생긴다.<br><br>
    그 사람이 벽에 대고 말한다. <span style="color:#a9b7c6;">"데려가 줘요. 셋이서 왔어요. 나만 남았어요."</span>`,
  o:[
    { l:'① 일으켜 대열 가운데 넣는다.', k:'fix', dc:21,
      ok:`어깨를 잡아 일으켰다. 얼굴이 하얗다. 겁먹은 사람 얼굴이지, 겁나는 것의 얼굴이 아니다.<br><br>대열 가운데 넣었다. 분대장 바로 뒤. 제일 안전한 자리다. 그렇게 믿게 했다.<br>쪽문까지 갔다. 그 사람이 걷는 내내 이쪽 등 옷자락을 쥐고 있었다.<br><br>여섯을 데리고 나왔다. 칠판 숫자는 다섯이다. 틀린 쪽은 칠판이다.`,
      ng:`일으키는 순간 그 사람이 이쪽 손목을 꽉 잡았다. 놓지 않는다. 겁이 놓지 않는 것이다.<br><br>손목이 꺾인 채 걸었다. 대열이 느려졌다.<br>장화 소리가 그 느린 만큼 가까워졌다.`,
      win:{ exp:20, dream:2, spirit:5 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 대열을 세운 채 그대로 지나간다.', k:'steady', dc:20,
      ok:`대열을 멈추지 않았다. 그 사람 옆을 지났다.<br><br>뒤에서 그 사람이 따라 일어나는 소리가 났다. 맨 끝에 붙었다. 부르지 않았는데 온 사람이다. 쫓지 않았다. 세지도 않았다.<br>쪽문을 나서니 맨 끝이 없었다.<br><br>돌아보니 그 사람은 벽을 보던 자리에 다시 앉아 있다. 처음부터 그 자리 사람이었다.`,
      ng:`지나가는데 일행 하나가 걸음을 멈췄다. 그 사람을 두고 못 간다고.<br><br>분대가 둘로 나뉘었다. 다투는 사이 대걸레 소리가 다가왔다.<br>셋을 끌고 둘을 기다리게 했다. 다시 모이는 데 오래 걸렸다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'③ 돌려세워 얼굴부터 확인한다.', k:'gaze', dc:21,
      doom:{ title:'벽을 보던 얼굴', what:'벽을 보던 사람에게 끌려갑니다', dc:17, sec:55,
        text:`어깨를 잡아 돌려세웠다.<br><br>얼굴이 없다. 벽을 오래 봐서 벽처럼 평평하다. 입만 있다. 입이 웃는다. <span style="color:#a9b7c6;">"이제 둘 남았네."</span><br>그 손이 이쪽 손목을 잡고 벽 쪽으로 당긴다. 벽에 이쪽 뺨이 닿는다. 차다.<br><br>등 뒤에서 일행이 이쪽 허리띠를 잡는다.`,
        dieText:`창고 구석에 사람 하나가 벽을 보고 앉아 있다.<br><br>무릎을 끌어안았다. 등이 떨린다.<br>다음에 오는 일행에게 말할 것이다. 데려가 달라고. 분대장 목소리로.` },
      ok:`어깨를 잡아 돌려세웠다. 얼굴이 있다. 젊은 하역부다. 울어서 퉁퉁 부었다. 진짜다.<br><br>그 사람 주머니에서 말린 고기 꾸러미가 떨어졌다. 같이 온 둘이 남기고 간 것이라고 한다.<br>대열에 넣었다. 먹을 것을 나눴다.<br><br>남겨진 사람이 남은 몫까지 쥐고 있었다. 세고 나니 책임이 생겼다. 무겁지 않았다.`,
      win:{ exp:22, dream:3, item:'말린 고기' } }
  ] },

{ at:'B2', t:'7층 — 맞지 않는 머릿수',
  x:`정각 점검이 온다. 간호사가 침대마다 이름을 부르고 계수기를 누른다. 엄지가 반 박씩 늦다.<br><br>
    지난 정각에 일행 둘이 대답을 엇갈렸다. 하나는 둘로, 하나는 없음으로 세어졌다. 숫자가 맞을 때까지 센다고 했다.<br>
    분대장은 남이 제 분대를 세는 게 싫다. 셀 줄 모르는 손이 세면 꼭 틀린다.<br><br>
    딸깍 소리가 문 앞에 섰다.`,
  o:[
    { l:'① 먼저 분대 점호를 끝내고 숫자를 댄다.', k:'fix', dc:21, wake:1,
      ok:`간호사가 첫 이름을 부르기 전에 일어섰다. <span style="color:#d4af37;">"번호."</span> 낮게. 다섯이 차례로 받았다.<br><br>간호사를 보고 말했다. <span style="color:#d4af37;">"다섯. 이상 없습니다."</span><br>간호사가 이쪽을 오래 본다. 마스크 위 눈이 깜박이지 않는다. 엄지가 계수기 위에서 다섯 번 내려갔다. 정확히. 이름은 안 불렀다.<br><br>남의 분대를 세는 손이 이쪽 셈을 받아 적었다. 세는 사람이었다. 오늘은 분대를 대신해 대답하는 사람이었다. 다섯 목소리를 한 목소리에 담았다. 목이 그 무게를 기억한다.`,
      ng:`번호를 붙이는데 간호사가 끼어들어 이름을 불렀다. 분대가 번호와 이름 사이에서 헷갈렸다.<br><br>하나는 번호로, 하나는 이름으로 대답했다. 딸깍 일곱.<br>간호사가 볼펜으로 화이트보드에 줄을 하나 그었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-14 } },
    { l:'② 무력을 써서 커튼 뒤 여섯째를 끌어낸다.', k:'break', dc:21, cost:{ might:24 },
      ok:`침대 사이에 커튼이 하나 더 쳐져 있다. 아까 없던 커튼이다.<br><br>한 손으로 커튼을 걷고 한 손으로 그 뒤를 움켜잡았다. 흰 가운 소매가 잡혔다. 끌어내 복도로 밀어 버렸다. 문을 닫았다.<br>딸깍 다섯. 숫자가 맞았다.<br><br>셀 것이 많으면 덜어 낸다.`,
      ng:`커튼을 걷었는데 뒤에 아무도 없다. 커튼 걷는 소리만 컸다.<br><br>간호사가 돌아본다. 빈 침대를 본다. 명패를 하나 더 건다.<br>이쪽 침대 명패와 같은 이름이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, mind:-16 } }
  ] },

{ at:'B3', t:'9호차 — 표가 넷',
  x:`검표원이 온다. 집게를 딸깍거리며. 구두에 물기가 없다.<br><br>
    일행 표를 셌다. 넷. 하나가 표를 잃어버렸다. 화장실 앞에서 떨어뜨린 것 같다고 한다.<br>
    분대장은 표 없는 사람이 어떻게 되는지 들었다. 다음 역에서 내리게 한다. 이 열차는 서지 않는다.<br><br>
    검표원이 세 줄 앞까지 왔다.`,
  o:[
    { l:'① 분대 표를 한 손에 모아 한꺼번에 내민다.', k:'fix', dc:21,
      ok:`넷의 표를 받아 한 손에 부채처럼 폈다. 이쪽 표를 맨 위에.<br><br>검표원이 손을 내밀자 묶음째 내밀었다. <span style="color:#d4af37;">"다섯입니다. 일행입니다."</span><br>검표원이 집게로 맨 위를 뚫었다. 묶음을 돌려준다. 넘겨 보지도 않았다.<br><br>다섯이라는 말을 믿었는지 세기 싫었는지는 모른다. 묶음으로 내밀면 묶음으로 뚫린다.`,
      ng:`묶음을 내밀자 검표원이 하나씩 뽑아 셌다. 천천히. 넷.<br><br>눈이 다섯째를 찾는다. 표 없는 사람 얼굴에서 멈춘다. 집게가 딸깍한다. 그 사람 소매 단추에 구멍을 뚫었다.<br>그 사람 손목이 한동안 차가웠다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 무력을 써서 검표원 손목을 잡아 둔다.', k:'steady', dc:21, cost:{ might:22 },
      ok:`검표원이 표 없는 사람 앞에 서려 할 때 그 손목을 잡았다. 세게. 웃으며 이쪽 표를 쥐여 줬다.<br><br>검표원이 손목을 빼려 한다. 안 놓았다. 집게가 허공에서 딸깍거린다.<br>한참 뒤 검표원이 이쪽 표만 뚫고 지나갔다. 손목을 문지르며.`,
      ng:`잡았는데 손목이 차고 미끄럽다. 손목이 얇아지며 빠져나갔다. 사람 손목이 그렇게 얇아질 수 없다.<br><br>집게가 이쪽 손등을 뚫었다. 구멍 하나.<br>피가 안 났다. 그게 더 오래 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-14 } },
    { l:'③ 화장실 앞까지 되돌아가 표를 찾는다.', k:'sense', dc:21,
      ok:`검표원이 세 줄 앞일 때 뛰었다. 화장실 앞 바닥. 젖은 표가 이음매 틈에 끼어 있다.<br><br>손톱으로 빼냈다. 돌아오니 검표원이 막 일행 앞에 섰다.<br>표를 내밀었다. 다섯. 딸깍, 딸깍.`,
      ng:`화장실 앞에 표가 없다. 화장실 문은 사용 중이다. 안에서 누가 표에 구멍 뚫는 소리를 낸다. 딸깍. 딸깍.<br><br>돌아왔을 때 검표원은 이미 지나갔다.<br>표 없던 사람 손에 표가 쥐여 있다. 구멍이 뚫렸다. 누가 쥐여 줬는지 모른다.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B', t:'쫓기는 골목 — 맨 뒤 자리',
  x:`쫓긴다. 골목 다섯 개째. 다들 숨이 턱에 찼다.<br><br>
    뒤에서 오는 발소리가 하나다. 무겁다. 서두르지 않는다.<br>
    분대장은 쫓길 때 맨 뒤에 선다. 맨 뒤가 무너지면 분대 전체가 뒤를 본다. 뒤를 보는 분대는 넘어진다.<br><br>
    골목 끝 철문까지 서른 걸음. 여는 데 숨 다섯.`,
  o:[
    { l:'① 무력을 써서 맨 뒤에서 돌아서 막아선다.', k:'steady', dc:21, cost:{ might:25 },
      ok:`넷을 앞으로 보내고 돌아섰다. 어깨를 낮추고 섰다.<br><br>발소리가 모퉁이를 돈다. 회색 비옷이다. 이쪽을 보고 섰다. 서로 보는 숨 다섯. 그동안 철문이 열렸다.<br>뒷걸음으로 열 걸음. 돌아서 스무 걸음. 철문을 닫았다. 문 너머에서 서두르지 않는 발소리가 문 앞에 멈췄다.<br><br>분대장 등은 분대의 벽이다. 벽은 숨 다섯만 버티면 된다.`,
      ng:`막아섰는데 상대가 멈추지 않았다. 걸음 그대로 왔다.<br><br>어깨로 받았다. 받아 냈다. 대신 갈비뼈가 울었다.<br>밀려 넘어지며 철문에 닿았다. 넷이 문을 열고 이쪽을 끌어 들였다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-12 } },
    { l:'② 구령으로 넷을 둘씩 갈라 달리게 한다.', k:'evade', dc:20,
      ok:`<span style="color:#d4af37;">"둘씩! 좌우로!"</span><br><br>넷이 둘씩 나뉘어 골목 양옆 틈으로 뛰었다. 발소리 하나로는 둘을 못 쫓는다. 갈림에서 섰다.<br>이쪽은 가운데로 뛰어 철문에 닿았다. 양옆 틈이 철문 앞에서 다시 만났다. 다섯.`,
      ng:`갈라 뛰라고 했는데 넷이 다 같은 쪽으로 뛰었다. 겁은 한 방향이다.<br><br>그쪽 틈은 막혀 있었다. 발소리가 틈 앞에 섰다.<br>넷을 끌어내느라 팔이 벽에 갈렸다.`,
      win:{ exp:15, dream:1, mind:5 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B', t:'어둠 — 흉내 낸 구령',
  x:`어둠 속에서 구령이 들린다. <span style="color:#d4af37;">"뛰어!"</span><br><br>
    이쪽 목소리다. 이쪽은 말하지 않았다.<br>
    일행 둘이 벌써 뛰기 시작했다. 분대장 목소리에 몸이 먼저 가도록 연습했다. 연습한 대로다.<br><br>
    분대장은 제 목소리를 남이 쓰면 분대가 남의 것이 된다는 걸 안다. 목소리가 다시 부른다. 왼쪽으로.`,
  o:[
    { l:'① 구령 끝에 약속을 붙인다.', k:'fix', dc:21, wake:1,
      ok:`뛰던 둘의 뒷덜미를 잡아 세웠다. 낮게 말했다. <span style="color:#d4af37;">"지금부터 내 구령 끝엔 손뼉 한 번."</span> 손뼉을 쳤다. 짝.<br><br>어둠 속 목소리가 다시 불렀다. 왼쪽으로. 손뼉이 없다. 아무도 안 움직였다. 이쪽이 불렀다. 오른쪽. 짝. 다섯이 오른쪽으로 갔다.<br>목소리는 그 뒤로 몇 번 더 불렀다. 손뼉 없이.<br><br>구령은 목소리인 줄 알았다. 목소리는 빼앗긴다. 약속은 안 빼앗긴다. 손뼉 하나가 분대를 다시 이쪽으로 돌려놓았다. 손이 그 손뼉을 버릇으로 삼았다.`,
      ng:`약속을 정하는데 어둠 속 목소리가 끼어들었다. 이쪽 목소리로. 손뼉은 두 번.<br><br>일행 하나가 그 말을 믿었다. 두 번 쳤다. 왼쪽으로 뛰었다.<br>찾아 데려오는 데 손바닥이 철조망에 찢겼다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 무력을 써서 목소리 난 쪽을 들이받는다.', k:'break', dc:21, cost:{ might:25 },
      ok:`목소리 난 쪽으로 어깨부터 들이받았다. 무언가 부딪쳤다. 물렁하다. 고무 비옷 감촉.<br><br>어둠 속에서 그것이 이쪽 목소리로 끙 하고 앓았다.<br>그 뒤로 구령이 안 들렸다. 남의 목소리를 쓰는 것도 아프면 운다.`,
      ng:`들이받았는데 아무것도 없다. 벽이다. 어깨가 벽을 쳤다.<br><br>벽 너머에서 이쪽 목소리가 웃었다.<br>일행 둘은 이미 왼쪽 골목 끝에 있었다. 셋을 끌고 쫓아갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B1', t:'냉동 창고 — 꺼진 불',
  x:`냉동 창고 불이 꺼졌다. 한꺼번에. 완전히 까맣다.<br><br>
    매달린 고기들이 레일 위에서 흔들린다. 끼익. 차가운 것이 뺨을 스친다. 고기인지 손인지 모른다.<br>
    분대장은 어둠에서 제일 먼저 머릿수를 센다. 어둠에서 사람은 서로를 놓친다.<br><br>
    숨 셋 만에 하나를 놓쳤다. 대답이 넷.`,
  o:[
    { l:'① 허리띠를 이어 줄을 만들고 끝을 쥔다.', k:'fix', dc:21,
      ok:`<span style="color:#d4af37;">"제자리. 허리띠 풀어."</span><br><br>대답 넷이 허리띠를 이었다. 한쪽 끝을 넷이 차례로 쥐고 다른 끝을 이쪽이 쥐었다. 줄을 쥔 채 놓친 하나 쪽으로 걸었다. 줄이 팽팽해질 때까지.<br>손끝에 옷자락이 닿았다. 떨고 있다. 다섯째다. 줄 끝을 쥐여 줬다.<br><br>불이 다시 켜질 때까지 아무도 줄을 놓지 않았다.`,
      ng:`줄을 쥐고 걸었는데, 줄이 팽팽해지기 전에 무언가 줄 한가운데를 잡았다. 당긴다.<br><br>넷이 줄을 놓쳤다. 다시 이어 잡는 데 한참.<br>놓친 하나는 불이 켜진 뒤 고기 사이에서 찾았다. 입술이 파랬다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 무력을 써서 문을 어깨로 밀어 연다.', k:'break', dc:22, cost:{ might:24 },
      ok:`기억해 둔 문 쪽으로 어깨를 던졌다. 한 번, 두 번. 셋째에 문짝이 밀렸다.<br><br>바깥 네온 빛이 한 줄 들어왔다. 빛 한 줄이면 다섯이 다 보인다.<br>놓쳤던 하나가 빛 쪽으로 기어 나왔다.`,
      ng:`어깨를 던졌는데 문이 아니라 고기였다. 매달린 고기가 이쪽을 받아 내고 흔들렸다.<br><br>레일이 끼익 울었다. 어둠 속에서 사슬 당기는 손이 레일을 멈췄다.<br>그리고 반대로 당겼다. 이쪽 쪽으로. 빈 갈고리가 귀를 스쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B2', t:'계단참 — 예순하나',
  x:`4층 계단참에 보호사 둘이 벽을 보고 섰다. 코가 벽에 닿을 만큼. 같이 숨 쉬며 숫자를 센다. 예순하나.<br><br>
    백이 되면 돌아설 것이다. 계단참을 지나야 아래층이다. 다섯이 한꺼번에 지나기엔 좁다.<br>
    분대장은 남이 세는 숫자도 구령으로 쓴다. 숫자는 누가 세든 숫자다.<br><br>
    예순둘.`,
  o:[
    { l:'① 저쪽 숫자에 맞춰 하나씩 넘긴다.', k:'fix', dc:22,
      ok:`손가락으로 일행에게 보였다. 저쪽 숫자 다섯에 하나씩. 예순다섯에 첫째. 일흔에 둘째. 일흔다섯에 셋째.<br><br>걸음은 숫자 사이로. 숫자를 세는 입은 다음 숫자만 생각한다. 뒤를 안 본다.<br>아흔에 이쪽이 마지막으로 넘었다. 아흔다섯에 아래층 문을 닫았다.<br><br>문 너머에서 백. 그리고 돌아서는 운동화 소리.`,
      ng:`일흔다섯에 셋째가 발을 헛디뎠다. 계단 고무가 끽 울었다.<br><br>숫자가 멈췄다. 일흔여섯이 안 나온다. 보호사 둘이 천천히 돌아서려 한다.<br>나머지를 밀어 넘기고 맨 뒤에서 정강이를 걷어차였다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 무력을 써서 둘을 벽에 눌러 붙든다.', k:'steady', dc:21, cost:{ might:26 },
      doom:{ title:'백까지 센 뒤', what:'보호사들에게 붙들려 끌려갑니다', dc:17, sec:55,
        text:`둘 사이에 서서 두 어깨를 벽에 눌렀다. 돌아서지 못하게. 넷이 등 뒤로 지나간다.<br><br>여든. 아흔. 손바닥 밑 어깨가 단단하다. 사람 어깨가 아니다. 벽 같다.<br>백.<br><br>둘이 동시에 돌아섰다. 둘의 손이 이쪽 양팔을 잡는다. 계단 위쪽으로 데려간다. 4라고 적힌 쪽으로.`,
        dieText:`넷은 아래층으로 내려왔다. 벽에 3.<br><br>위쪽 계단참에 셋이 벽을 보고 서 있다. 같이 숨을 쉬며 센다.<br>가운데 하나의 어깨가 조금 넓다. 분대장 어깨다.` },
      ok:`둘 사이에 서서 두 어깨를 벽에 눌렀다. 넷이 등 뒤로 지나간다.<br><br>여든. 아흔. 손바닥 밑 어깨가 벽처럼 단단하다.<br>아흔아홉에 손을 떼고 계단을 뛰어 내렸다. 백. 둘이 돌아섰을 때 계단참은 비어 있었다.<br><br>손바닥이 얼얼하다. 벽을 한참 민 손이다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'B3', t:'침대칸 — 커튼 친 침대 여섯',
  x:`침대칸 통로 양옆으로 침대가 이 층씩. 커튼이 다 쳐졌다. 여섯 칸.<br><br>
    그중 하나에 얼굴 바꾸는 것이 누워 있다. 이쪽을 따라오던 마른 발자국이 이 칸 어딘가에서 끝난다.<br>
    분대장은 칸을 뒤질 때 혼자 뒤지게 하지 않는다. 혼자 연 커튼 뒤에서 무엇이 나오면 그 사람이 혼자 본다.<br><br>
    통로 끝 문까지 가려면 여섯 칸을 지나야 한다.`,
  o:[
    { l:'① 둘씩 짝지어 하나씩 열며 넘어간다.', k:'fix', dc:21,
      ok:`둘이 커튼을 열고 하나가 뒤에서 본다. 이쪽은 맨 앞.<br><br>첫 칸, 비었다. 둘째 칸, 사람이 잔다. 귀가 둘 다 있다. 사람이다. 셋째, 넷째.<br>다섯째 칸 커튼을 여는 순간 안의 것이 일어났다. 둘이 같이 봤다. 둘이 같이 본 얼굴은 바꿀 수 없다.<br><br>그것이 웃다 말고 커튼을 도로 쳤다. 그 옆을 지났다.`,
      ng:`짝을 짓는데 하나가 남았다. 다섯은 둘씩 안 나뉜다. 남은 하나가 이쪽이다.<br><br>이쪽 혼자 연 커튼 뒤에서 이쪽 얼굴이 눈을 떴다. 이쪽 목소리로 하품을 했다.<br>한참 뒤에야 다리가 움직였다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 커튼을 닫힌 채로 두고 지나간다.', k:'hide', dc:20,
      ok:`아무것도 안 건드렸다. 숨을 죽이고 한 줄로 지나갔다.<br><br>커튼 하나가 조금 움직였다. 안에서 손가락이 커튼 끝을 들춘다. 보지 않았다. 앞만 봤다.<br>통로 끝 문을 지났다. 문 닫히는 소리에 커튼 여섯이 한꺼번에 열렸다.`,
      ng:`지나가는데 커튼 하나에서 손이 나와 일행 하나의 발목을 잡았다. 침대 쪽으로 끈다.<br><br>다 같이 당겨 뺐다.<br>그 사람 신발 한 짝이 커튼 안에 남았다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-24, mind:-14 } },
    { l:'③ 무력을 써서 커튼 줄을 한꺼번에 뜯는다.', k:'break', dc:21, cost:{ might:22 },
      ok:`커튼 줄을 잡고 통로 끝까지 한 번에 뜯으며 뛰었다. 커튼 여섯이 다 떨어졌다.<br><br>침대마다 다 보인다. 하나에 그것이 앉아 있었다. 다섯이 다 그것을 봤다. 다 본 것은 숨지 못한다.<br>그것이 창밖 빗속으로 사라졌다. 창 열리는 소리도 안 났다.`,
      ng:`줄이 안 뜯겼다. 줄에 매달려 이쪽이 휘청였다. 커튼 여섯이 한꺼번에 출렁였다.<br><br>다섯째 칸 커튼 안에서 손이 이쪽 손목을 잡았다.<br>떼어 내고 나니 손목에 손가락 자국이 박혀 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-14 } }
  ] },

{ at:'B', t:'잠기지 않는 방 — 불침번',
  x:`잠시 숨을 돌릴 방이 생겼다. 창고 사무실이다. 문은 하나, 잠기지 않는다.<br><br>
    다들 쓰러지듯 앉는다. 누군가는 깨어 있어야 한다.<br>
    분대장은 불침번을 세울 때 제일 힘든 시간을 제가 맡는다. 오늘은 모든 시간이 제일 힘든 시간이다.<br><br>
    문밖 복도에서 가끔 장화 소리가 지나간다.`,
  o:[
    { l:'① 둘씩 묶어 세우고 저는 두 번 선다.', k:'fix', dc:20,
      ok:`둘씩 묶었다. 하나가 졸면 하나가 찌른다. 이쪽은 첫 번과 마지막 번.<br><br>장화 소리가 문 앞에서 두 번 멈췄다. 문 유리에 서 있는 둘이 비친다. 장화가 갔다.<br>둘씩 서 있는 방은 셋째가 있다고 보게 만든다. 저쪽은 혼자다.`,
      ng:`둘이 같이 졸았다. 둘씩 묶으면 둘이 같이 졸 수도 있다.<br><br>깨어 보니 문이 한 뼘 열려 있었다. 아무도 안 열었다.<br>문틀이 젖었다. 그 틈으로 누가 오래 들여다봤다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 무력을 써서 혼자 밤새 등으로 문을 받친다.', k:'steady', dc:21, cost:{ might:22 },
      ok:`다 재우고 문 앞 의자에 앉았다. 등으로 문을 받쳤다.<br><br>장화 소리가 문 앞에서 멈출 때마다 등에 힘을 줬다. 문이 안 열린다. 장화가 간다.<br>새벽에 다들 깨어 이쪽 눈 밑을 봤다. 아무 말 안 했다. 분대장 눈 밑은 원래 그렇다.`,
      ng:`새벽 직전에 졸았다. 등이 문에서 떨어졌다.<br><br>깨어 보니 문이 열려 있고, 이쪽 의자 앞에 젖은 장화 자국 두 개.<br>이쪽을 오래 내려다본 자리다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B', t:'갈림 — 모일 자리 둘',
  x:`길이 둘이다. 하나는 물에 잠긴 수로, 하나는 지붕 위. 둘 다 끝까지 가 봐야 맞는 길인지 안다.<br><br>
    다 같이 하나를 가면 틀렸을 때 돌아올 시간이 없다. 둘로 나누면 잃을 수 있다.<br>
    분대장은 나눌 때 다시 모일 자리부터 정한다. 그게 나누는 일의 전부다.<br><br>
    모일 자리가 마땅치 않다. 어디로든 비옷이 지나간다.`,
  o:[
    { l:'① 모일 자리와 때, 못 올 때 할 일까지 정한다.', k:'fix', dc:21, wake:1,
      ok:`모일 자리를 둘 정했다. 첫 자리는 꺼진 간판 밑. 거기 못 오면 둘째 자리, 수로 끝 사다리. 때는 네온이 세 번 꺼졌다 켜질 때까지. 못 오면 기다리지 말고 둘째 자리로.<br><br>둘씩 보냈다. 이쪽은 첫 자리에 남았다. 네온이 두 번 깜박일 때 지붕 쪽 둘이 왔다. 세 번째에도 수로 쪽 둘은 안 왔다.<br>정한 대로 둘째 자리로 갔다. 수로 쪽 둘이 사다리 밑에서 기다리고 있었다. 정한 대로.<br><br>나누는 일은 모이는 일이었다. 못 모일 때까지 정해 두면 흩어져도 분대다. 이쪽이 없어도 도는 판을 처음 짰다.`,
      ng:`모일 자리를 하나만 정했다. 수로 쪽 둘이 오지 않았다.<br><br>기다렸다. 네온이 다섯 번 깜박였다. 찾으러 갔다. 수로가 불어 있었다.<br>둘을 끌어내느라 허리까지 젖었다. 다리에 쥐가 났다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 나누지 않고 다 같이 수로로 간다.', k:'bond', dc:20,
      ok:`나누지 않았다. 허리띠를 잡고 다섯이 수로에 들어갔다. 물이 허리까지.<br><br>다섯이 같이 버티면 물살도 하나를 못 데려간다.<br>수로 끝에 사다리가 있었다. 맞는 길이었다. 운이 반이다. 나머지 반은 같이 간 것이다.`,
      ng:`수로 끝이 쇠창살로 막혔다. 다 같이 돌아오는 길에 물이 불었다.<br><br>하나가 미끄러졌다. 넷이 붙잡았다.<br>다 같이 젖고 다 같이 떨었다. 지붕 길로 가는 데 남은 힘을 다 썼다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B1', t:'야적장 — 다리 저는 노인',
  x:`야적장에서 만난 노인이 따라온다. 늙은 하역부다. 다리를 전다. 모자를 눌러 썼다. 이 항구에서 사십 년을 짐을 졌다고 했다.<br><br>
    노인은 길을 안다. 노인은 느리다. 탐조등이 한 바퀴 도는 사이 노인은 열 걸음을 못 간다.<br>
    분대장은 분대 밖 사람을 넣으면 분대 걸음이 그 사람 걸음이 된다는 걸 안다.<br><br>
    노인이 가리킨 길은 지금까지 다 맞았다.`,
  o:[
    { l:'① 무력을 써서 노인을 업는다.', k:'bond', dc:21, cost:{ might:26 },
      ok:`노인을 등에 업었다. 가볍다. 사십 년 짐을 진 사람이 짐보다 가볍다.<br><br>노인이 등에서 길을 일러 준다. 왼쪽. 그다음 컨테이너 둘째 틈. 업은 쪽이 다리고 업힌 쪽이 눈이다.<br>탐조등이 한 바퀴 도는 사이 골목 셋을 지났다.<br><br>노인이 등에서 웃었다. 젊을 때도 이렇게 업혀 본 적이 없다고.`,
      ng:`업고 뛰다 컨테이너 모서리에 노인 다리가 부딪쳤다. 노인이 신음을 삼켰다.<br><br>탐조등이 신음 쪽으로 돌았다. 업은 채로 엎드렸다.<br>노인 무게가 등 위에서 한참 떨었다. 이쪽 무릎이 젖은 바닥에 갈렸다.`,
      win:{ exp:20, dream:2, spirit:5 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 노인을 가운데 넣고 대열을 노인 걸음에 맞춘다.', k:'fix', dc:21,
      ok:`노인을 가운데 넣었다. 대열 걸음을 노인 걸음에 맞췄다. 느리다.<br><br>탐조등이 올 때마다 다섯이 노인 둘레로 바짝 섰다. 쌓인 짐 모양으로. 빛은 짐 모양을 지나쳤다.<br>느려도 대열이 안 끊겼다. 끊기지 않는 대열은 느려도 닿는다.`,
      ng:`노인 걸음에 맞추는 사이 탐조등이 멈췄다. 대열 바로 위에서. 크레인 위에서 무전기가 울렸다.<br><br>노인을 컨테이너 틈에 밀어 넣고 나머지는 흩어졌다.<br>다시 모이는 데 손바닥이 철판에 다 쓸렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B2', t:'4층 — 직원 탈의실',
  x:`직원 탈의실이다. 사물함이 줄지어 섰다. 한 칸이 반쯤 열렸다. 흰 반팔과 흰 바지가 걸려 있다. 다섯 벌.<br><br>
    복도는 보호사들이 지나다닌다. 줄지어 걷는다. 같은 박자로. 같은 간격으로.<br>
    분대장은 줄지어 걷는 것을 안다. 가르쳐 본 사람이다.<br><br>
    옷만으로는 안 된다. 걸음이 같아야 한다.`,
  o:[
    { l:'① 옷을 입히고 보호사 걸음으로 줄 세운다.', k:'fix', dc:21,
      ok:`다섯이 흰 옷을 입었다. 줄을 세웠다. 간격은 팔 하나. 박자는 숨 하나에 두 걸음. 맨 앞은 이쪽. 고개는 앞만.<br><br>복도로 나갔다. 마주 오던 보호사 줄이 지나간다. 이쪽 줄도 지나간다. 서로 고개를 안 돌린다.<br>계단 문까지 갔다. 맨 뒤가 마지막 걸음을 같은 박자로 디뎠다.<br><br>처음 보는 걸음을 한 번에 따라 했다. 따라 할 줄 아는 게 분대다.`,
      ng:`줄을 세웠는데 셋째가 박자를 놓쳤다. 걸음이 반 박 빨랐다.<br><br>마주 오던 보호사 줄이 섰다. 전부. 고개가 한꺼번에 이쪽으로 돌았다.<br>줄을 버리고 뛰었다. 흰 옷이 문고리에 걸려 찢겼다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 사물함 안에 하나씩 숨는다.', k:'hide', dc:21,
      ok:`사물함 다섯 칸에 하나씩 들어가 문을 당겨 닫았다. 숨구멍으로 복도 빛이 든다.<br><br>보호사 둘이 들어와 옷을 갈아입고 나갔다. 제 칸만 연다. 남의 칸은 안 연다.<br>나와서 숨을 몰아쉬었다. 이쪽 칸 바닥에 꿀 한 줌이 종이에 싸여 있었다. 누군가의 간식이다.`,
      ng:`사물함 문이 안에서 안 열린다. 숨구멍이 작다. 숨이 찬다.<br><br>옆 칸에서 일행이 두드린다. 이쪽도 두드렸다.<br>보호사가 들어와 사물함을 하나씩 두드리며 지나갔다. 똑같은 박자로.`,
      win:{ exp:15, dream:1, item:'꿀 한 줌' }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B3', t:'2호차 — 빈 우리',
  x:`화물칸에 쇠 우리 여섯. 입마개 한 큰 개들이 엎드렸다. 꼬리표에 추적견. 자면서도 코가 움직인다.<br><br>
    우리 하나가 열려 있다. 비었다. 그 개가 지금 어디 있는지 모른다.<br>
    분대장은 분대 냄새를 생각했다. 다섯이 밤새 비를 맞고 뛰었다. 냄새가 진하다.<br><br>
    상자 더미 뒤에서 젖은 발톱이 철판을 긁는 소리.`,
  o:[
    { l:'① 무력을 써서 빈 우리 앞을 몸으로 막아선다.', k:'steady', dc:21, cost:{ might:24 },
      doom:{ title:'빈 우리의 개', what:'추적견에게 물려 끌려갑니다', dc:17, sec:50,
        text:`빈 우리 앞에 섰다. 넷을 등 뒤 통로로 보냈다. 발톱 소리가 상자 뒤에서 나온다.<br><br>크다. 입마개가 없다. 개가 이쪽을 본다. 이쪽 냄새가 아니라 다른 냄새를 맡는다. 이쪽 소매에 묻은 그것의 냄새.<br><br>개가 뛰어든다. 소매를 물었다. 끈다. 상자 더미 사이로. 놓지 않는다.`,
        dieText:`넷은 화물칸을 빠져나갔다. 등 뒤에서 개 짖는 소리가 한 번, 오래.<br><br>빈 우리 문이 닫혀 있었다. 우리 안에 무언가 엎드렸다.<br>꼬리표가 바뀌었다. 추적견이 아니다. 잡은 것.` },
      ok:`빈 우리 앞에 섰다. 넷을 등 뒤 통로로 보냈다. 상자 뒤에서 개가 나온다. 크다. 입마개가 없다.<br><br>개가 이쪽 소매 냄새를 맡는다. 그리고 고개를 돌려 통로 반대편 화장실 문을 본다. 이쪽 소매에 묻은 냄새보다 진한 쪽이다.<br>개가 그쪽으로 갔다. 화장실 문 앞에서 길게 짖었다.<br><br>막아선 자리에서 비켜나 넷을 따라갔다. 개는 사람을 쫓으라고 실린 게 아니었다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 석탄 가루를 묻혀 냄새를 덮게 한다.', k:'hide', dc:21,
      ok:`탄수차 쪽에서 흘러든 젖은 석탄 가루를 다섯이 손과 옷에 문질렀다. 까매졌다.<br><br>냄새가 석탄 냄새다. 개들이 코를 움직이다 고개를 묻었다.<br>상자 뒤 발톱 소리가 다가왔다가 멀어졌다. 석탄은 이 열차 어디에나 있는 냄새다.`,
      ng:`문지르는데 석탄 가루가 눈에 들어갔다. 눈물이 쏟아진다. 앞이 안 보인다.<br><br>우리 하나에 부딪쳤다. 입마개 한 개가 깨어 일어섰다.<br>쇠창살 사이로 앞발이 나와 이쪽 다리를 긁었다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B', t:'부러진 발목 — 업을 수 있는 무게',
  x:`일행 하나가 발목을 다쳤다. 접질린 게 아니다. 부러졌다. 혼자 못 걷는다.<br><br>
    출구까지 남은 길이 길다. 계단도 있다. 비도 온다. 쫓는 발소리도 있다.<br>
    분대장 등은 분대의 무게를 진다. 한 사람 무게는 질 수 있다. 지고 나면 손이 비지 않는다.<br><br>
    손이 비지 않는 분대장에게는 목소리밖에 없다.`,
  o:[
    { l:'① 무력을 써서 업고, 구령은 등에서 받는다.', k:'steady', dc:22, cost:{ might:28 }, wake:1,
      ok:`업었다. 무겁다. 업은 채로 일어섰다. <span style="color:#d4af37;">"앞으로."</span> 손이 없으니 목소리로만.<br><br>대열이 움직였다. 업힌 사람이 등에서 뒤를 본다. <span style="color:#d4af37;">"뒤에 하나."</span> 업힌 사람이 말하고 이쪽이 구령을 붙였다. 등에 업힌 사람이 이쪽 뒤통수의 눈이 됐다.<br>계단을 다 내려왔다. 등이 뜨겁다. 무릎이 떨린다. 쓰러지지 않았다.<br><br>업는 것은 짐을 지는 일인 줄 알았다. 오늘 등에 눈을 하나 달았다. 업힌 사람도 분대다. 그 사람 쓸 자리를 등에서 찾았다.`,
      ng:`업고 계단 셋째 칸에서 무릎이 꺾였다. 둘이 같이 굴렀다.<br><br>업힌 사람이 이쪽 위로 떨어졌다. 다행이다. 이쪽은 계단 모서리에 등이 찍혔다.<br>다시 업었다. 다시 일어섰다. 아까보다 느렸다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-32, mind:-12 } },
    { l:'② 외투와 막대로 들것을 만든다.', k:'fix', dc:21,
      ok:`외투 두 벌 소매에 막대 둘을 꿰었다. 들것이 됐다.<br><br>넷이 들고 이쪽이 앞에 섰다. 손이 비어야 앞을 본다.<br>계단에서 들것을 기울일 때마다 구령을 붙였다. 하나, 둘. 다친 사람이 한 번도 안 떨어졌다.`,
      ng:`들것이 계단에서 뒤틀렸다. 막대 하나가 부러졌다.<br><br>다친 사람이 미끄러져 부러진 발목이 계단에 닿았다.<br>비명이 계단을 타고 올라갔다. 위에서 대답하듯 발소리가 내려왔다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B2', t:'응급실 통로 — 톱니 박힌 셔터',
  x:`응급실 통로 셔터가 내려온다. 천장에서. 위잉. 한 칸씩. 셔터 너머가 1층으로 가는 길이다.<br><br>
    무릎 높이까지 남았다. 다섯이 기어서 지나야 한다. 한꺼번에 들이밀면 엉킨다.<br>
    분대장은 좁은 데를 지날 때 순서를 붙인다. 순서가 없으면 다 같이 끼인다.<br><br>
    셔터 밑단에 녹슨 톱니가 박혀 있다. 한 번 물면 안 놓는다.`,
  o:[
    { l:'① 구령으로 순서를 붙여 하나씩 굴려 보낸다.', k:'fix', dc:21,
      ok:`<span style="color:#d4af37;">"하나!"</span> 제일 마른 사람이 먼저 굴렀다. 먼저 간 몸이 셔터 높이를 재 준다.<br><br><span style="color:#d4af37;">"둘! 셋!"</span> 덩치 순서대로. 넷째가 지날 때 셔터가 정강이 높이. <span style="color:#d4af37;">"넷!"</span><br>마지막은 이쪽이다. 등을 바닥에 붙이고 미끄러졌다. 셔터 밑단이 코끝을 스쳤다.<br><br>다섯. 셔터가 바닥에 닿았다.`,
      ng:`셋째에서 구령이 엇갈렸다. 셋째와 넷째가 같이 들이밀었다. 어깨가 엉켰다.<br><br>셔터가 둘 위로 내려온다. 이쪽이 밑단을 손으로 받쳤다. 톱니가 손바닥을 물었다.<br>둘이 빠지고 나서야 손을 뺐다. 손바닥에 톱니 자국이 줄지어 박혔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-12 } },
    { l:'② 무력을 써서 셔터 밑단을 어깨로 받친다.', k:'steady', dc:21, cost:{ might:28 },
      doom:{ title:'물린 톱니', what:'셔터 밑에 깔렸습니다', dc:18, sec:45,
        text:`셔터 밑에 쪼그려 앉아 어깨로 밑단을 받쳤다. 셔터가 멈췄다. 넷이 이쪽 옆으로 기어 나간다.<br><br>넷째가 나갔다. 이쪽 차례다. 몸을 빼려는데 톱니가 어깨 옷을 물었다. 안 놓는다.<br>셔터 모터가 다시 운다. 위잉.<br><br>받치던 어깨가 밀린다. 무릎이 바닥에 닿는다.`,
        dieText:`셔터 너머에서 넷이 셔터를 두드렸다. 안에서 대답이 없다.<br><br>셔터 밑단 틈으로 소매 한쪽이 삐져나와 있다. 넷이 그 소매를 붙잡고 셌다.<br>다섯. 숫자는 맞았다. 대답하는 목소리만 넷이었다.` },
      ok:`셔터 밑에 쪼그려 앉아 어깨로 밑단을 받쳤다. 넷이 이쪽 옆으로 기어 나간다.<br><br>넷째가 나가자 몸을 빼려는데 톱니가 어깨 옷을 물었다.<br>웃옷을 벗어 버리고 빠져나왔다. 셔터가 웃옷을 문 채 바닥까지 내려앉았다.<br><br>맨 어깨에 셔터 자국이 붉게 남았다. 다섯.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'B1', t:'정문 — 다섯 시 십 분',
  x:`철문 틈에 회색 비옷이 섰다. 발밑에 양동이. 고무장갑을 벗어 양동이 손잡이에 건다. 안경을 닦아 쓴다.<br><br>
    그가 이쪽을 본다. 입술이 움직인다. 하나, 둘. 이쪽을 센다.<br>
    분대장은 남이 제 분대를 세는 걸 가만히 보고 있지 않는다. 세는 쪽이 정하는 숫자는 세는 쪽 숫자다.<br><br>
    하늘 끝이 회색으로 묽어진다. 일 분 남았다.`,
  o:[
    { l:'① 저쪽보다 먼저 세고 먼저 대답한다.', k:'fix', dc:22, wake:1,
      ok:`비옷의 입술이 셋에 닿기 전에 크게 불렀다. <span style="color:#d4af37;">"번호!"</span><br><br>하나, 둘, 셋, 넷, 다섯. 빗속에서 다섯 목소리가 철문에 부딪혔다. 이어 말했다. <span style="color:#d4af37;">"다섯. 전원 퇴근."</span><br>비옷의 입술이 멈췄다. 수첩을 꺼내지 않는다. 고개를 한 번 끄덕였다. 반걸음 비켜섰다. 정해진 일을 정해진 대로 하는 사람은 정해진 말에 진다. 다섯이 철문을 지났다.<br><br>세는 사람이었다. 오늘은 세는 판 전체를 이쪽 숫자로 덮었다. 목소리가 남의 셈 위로 올라갔다. 그 높이를 목이 기억한다.`,
      ng:`번호를 붙이는데 넷째가 늦었다. 비옷이 그 틈에 넷까지 셌다. 다섯째는 비옷이 셌다. 비옷의 숫자다.<br><br>비옷이 수첩을 꺼냈다. 줄을 하나 긋는다. 철문 틈이 좁아졌다.<br>다섯이 억지로 비집고 나오다 옆구리가 철문에 찢겼다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 무력을 써서 정면으로 밀고 나간다.', k:'break', dc:22, cost:{ might:28 },
      ok:`넷을 등 뒤에 붙이고 어깨를 낮춰 들이받았다. 비옷이 반걸음 밀렸다. 양동이가 넘어졌다. 물이 쏟아졌다.<br><br>그 반걸음으로 다섯이 철문을 지났다.<br>등 뒤에서 비옷이 엎어진 양동이를 바로 세우는 소리. 서두르지 않는다.`,
      ng:`들이받았는데 비옷이 꿈쩍 안 했다. 사람 무게가 아니다. 문 무게다.<br><br>어깨가 비옷 가슴에 박혔다. 고무장갑 낀 손이 이쪽 뒷덜미를 쥔다.<br>넷이 이쪽 허리를 끌어당겨 뺐다. 목덜미에 고무 냄새가 오래 남았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-32, mind:-14 } }
  ] },

{ at:'B3', t:'2호차 끝 — 열어 달라는 목소리',
  x:`화물칸 끝 문 너머에서 목소리가 들린다. 일행 하나의 목소리다. <span style="color:#d4af37;">"열어 줘. 나 여기 있어. 갇혔어."</span><br><br>
    뒤를 봤다. 그 사람이 이쪽 옆에 서 있다. 얼굴이 하얗다. 제 목소리를 듣고 있다.<br>
    분대장은 숫자가 맞으면 문을 안 연다. 문제는 숫자가 맞는지 모를 때다. 옆에 선 쪽이 진짜인지, 문 너머가 진짜인지.<br><br>
    문 두드리는 소리가 빨라진다.`,
  o:[
    { l:'① 손으로 다시 센다.', k:'fix', dc:21,
      ok:`다섯의 손을 하나씩 잡았다. 처마 밑에서 한 대로. 굳은살, 떨림, 젖은 장갑.<br><br>옆에 선 그 사람 손. 손바닥에 작은 흉터가 있다. 오늘 밤 철조망에 찢긴 자리다. 이쪽이 직접 봤다. 진짜다.<br>문 너머가 다시 부른다. 대답하지 않았다. 다섯을 데리고 반대쪽 문으로 나갔다.<br><br>두드리는 소리가 한참 따라왔다. 흉터는 따라 하지 못했다.`,
      ng:`손을 잡으려는데 옆에 선 그 사람이 손을 뺐다. 겁이 났다고 한다. 손을 못 셌다.<br><br>문 너머가 더 크게 부른다. 둘이 같은 목소리로 서로를 가짜라고 했다.<br>아무도 못 골랐다. 그사이 다른 칸에서 발소리가 왔다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 문을 열고 손을 뻗는다.', k:'bond', dc:21,
      doom:{ title:'열어 달라던 목소리', what:'문 너머로 끌려갑니다', dc:17, sec:50,
        text:`문을 열었다. 어둡다. 빗소리가 쏟아진다. 문 너머는 연결 통로다. 아무도 없다.<br><br>손을 뻗었다. 손목을 무언가 잡았다. 일행 목소리로 고맙다고 한다.<br>당긴다. 통로 밖으로.<br><br>철판 끝 너머는 레일이다. 빗속에서 침목이 빠르게 흘러간다.`,
        dieText:`다음 칸에서 다섯이 모였다. 맞는 숫자다.<br><br>분대장이 번호를 붙였다. 목소리가 맞다.<br>그 분대장은 끝까지 손을 내밀지 않았다. 손으로 세던 사람이었는데.` },
      ok:`문을 한 뼘만 열고 손을 뻗었다. 손목을 무언가 잡았다. 그 손을 이쪽이 먼저 쥐었다. 세게.<br><br>손바닥을 더듬었다. 흉터가 없다. 매끈하다. 방금 만든 손이다.<br>비틀어 떼고 문을 닫았다. 빗장을 걸었다.<br><br>문 너머에서 일행 목소리로 욕을 했다. 그 사람은 평생 그런 욕을 안 했다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'B', t:'백 걸음 앞 — 일어서는 구령',
  x:`다들 젖은 콘크리트 위에 주저앉았다. 이쪽도 앉았다.<br><br>
    출구까지 백 걸음. 백 걸음 안에 무엇이 있는지 안다. 그래서 다리가 안 움직인다.<br>
    분대장은 지친 분대를 일으키는 구령이 있다는 걸 안다. 먼저 일어나서 붙이는 구령이다.<br><br>
    먼저 일어날 다리가 이쪽에도 없다.`,
  o:[
    { l:'① 무력을 써서 제 다리부터 일으킨다.', k:'fix', dc:22, cost:{ might:25 }, wake:1,
      ok:`무릎을 짚었다. 다리가 떨린다. 떨리는 채로 섰다. 일어선다는 게 이렇게 무거운 줄 몰랐다.<br><br><span style="color:#d4af37;">"일어서."</span> 작게.<br>하나가 섰다. 둘, 셋. 다 섰다. 백 걸음을 걸었다.<br><br>구령은 남을 일으키는 말인 줄 알았다. 첫 구령은 제 다리에 붙인다. 남에게 들리는 것은 그 메아리다. 떨리는 다리로 붙인 구령이 오늘 제일 멀리 갔다.`,
      ng:`일어서다 무릎이 꺾였다. 도로 주저앉았다. 그걸 다들 봤다.<br><br>한 식경을 더 앉아 있었다.<br>그사이 몸이 식고 비가 옷 속으로 다 스몄다.`,
      win:{ exp:25, dream:3, mind:6 }, lose:{ hp:-24, mind:-16 } },
    { l:'② 앉은 채로 행군가를 부른다.', k:'bond', dc:20,
      ok:`앉은 채로 불렀다. 작게.<br><br>하나가 따라 불렀다. 둘째 소절에 다 따라 불렀다. 셋째 소절에 하나가 일어났다. 노래하면서.<br>노래가 끝날 때 다 서 있었다. 구령보다 느렸다. 덜 아팠다.`,
      ng:`노래를 시작했는데 빗소리 너머에서 누가 따라 불렀다. 다섯 중 아무도 아니다.<br><br>다른 소절을 부른다.<br>노래를 그만뒀다. 그쪽은 그만두지 않았다.`,
      win:{ exp:16, dream:2, spirit:5 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B', t:'나온 뒤 — 마지막 점호',
  x:`나왔다. 빗속이다. 등 뒤에서 문이 닫혔다.<br><br>
    분대장은 들어갈 때 세고, 쉴 때 세고, 나올 때 센다. 지금이 나올 때다.<br>
    다섯이 빗속에 서 있다. 셀 차례다.<br><br>
    오늘 밤 숫자는 몇 번이나 이쪽을 속였다. 여섯이었다가, 넷이었다가.`,
  o:[
    { l:'① 번호 대신 이름을 하나씩 부르고 기다린다.', k:'fix', dc:21, wake:1,
      ok:`번호를 붙이지 않았다. 이름을 불렀다. 하나씩. 대답이 오면 그 사람 얼굴을 봤다.<br><br>넷이 대답했다. 넷 다 제 얼굴이다. 마지막으로 제 이름을 소리 내어 불렀다. 이쪽이 대답했다. 다섯.<br><br>숫자는 셀 수 있다. 이름은 불러야 한다. 부르면 대답할 사람만 대답한다. 나올 때의 점호는 이제 이름이다. 목이 그 순서를 정했다.`,
      ng:`이름을 부르는데 넷째 이름에 대답이 두 번 왔다. 하나는 그 사람. 하나는 등 뒤 문 안쪽.<br><br>문 안쪽 대답이 조금 더 빨랐다.<br>아무도 뒤를 안 봤다. 다들 그 자리를 빨리 떴다. 한참 동안 다들 넷째를 힐끔거렸다.`,
      win:{ exp:25, dream:4, spirit:6 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 손을 잡아 체온으로 센다.', k:'sense', dc:20,
      ok:`손을 하나씩 잡았다. 다 따뜻하다. 빗속에서도. 따뜻한 것은 산 것이다.<br><br>다섯.<br>오늘 밤 처음으로 맞는 숫자가 반가웠다.`,
      ng:`손을 잡는데 하나가 미지근하다. 따뜻하지도 차지도 않다.<br><br>그 사람 얼굴을 봤다. 웃는다. 지친 웃음이다.<br>끝내 판단을 못 했다. 그날 밤 그 사람 옆에서 한숨도 못 잤다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] }

]);

// ── 진법가 ────────────────────────────────
kJob('formation', 'B', [

{ at:'B', t:'빗속 네거리 — 북쪽이 없다',
  x:`비 오는 밤거리에는 북쪽이 없다. 별도 해도 없다. 네온만 있다. 네온은 사방에서 빛난다.<br><br>
    진법가는 진을 놓기 전에 방위부터 정한다. 방위가 서야 생문과 사문이 선다.<br>
    골목이 여덟 갈래로 갈리는 네거리다. 어느 길이 사는 길인지 모른다.<br><br>
    빗물이 발목을 적시며 한쪽으로 흐른다.`,
  o:[
    { l:'① 빗물이 흘러 나가는 쪽을 개문으로 잡는다.', k:'fix', dc:21, wake:1,
      ok:`빗물을 봤다. 여덟 갈래 중 셋으로 흘러 나가고 하나에서 흘러 들어온다. 물은 열린 데로 나간다.<br><br>흘러 나가는 쪽 중 가장 센 물길을 개문으로 잡았다. 거기서 방위를 거꾸로 셈했다. 생문이 나왔다. 개문 옆 길이다.<br>그 길로 갔다. 막히지 않았다. 바람이 등 뒤에서 밀었다.<br><br>방위는 하늘에서 받는 줄 알았다. 땅에서 받아도 된다. 물이 가는 쪽으로 진을 세웠다. 발이 먼저 방위를 읽기 시작했다.`,
      ng:`흘러 나가는 쪽을 잡았는데 그 길 끝이 하수구였다. 물이 열린 데로 가는 건 맞다. 사람이 가는 데는 아니다.<br><br>막다른 길에서 돌아 나오는데 길 어귀에 우산 하나가 서 있었다.<br>피하다 웅덩이에 무릎을 찧었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 내공을 끌어올려 손바닥으로 기를 짚는다.', k:'gaze', dc:21, cost:{ qi:22 },
      ok:`호흡을 고르고 내공을 손끝까지 올렸다. 손바닥을 펴고 네거리를 한 바퀴 돌았다.<br><br>한 길 앞에서 손바닥이 따뜻하다. 비가 와도 기는 젖지 않는다.<br>그 길로 갔다. 손바닥이 나침반이다. 비 오는 밤에도.`,
      ng:`끌어올린 내공이 빗물에 흩어졌다. 젖은 손바닥은 기를 잘 못 잡는다.<br><br>여덟 길이 다 시리다. 아무 길이나 들어섰다.<br>장화 소리가 그 길에서 마주 왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B1', t:'3번 창고 — 팔레트 여덟 줄',
  x:`창고 바닥에 소금 자루 팔레트가 쌓였다. 여덟 줄. 줄 사이로 통로가 났다.<br><br>
    밀수꾼들이 아무렇게나 쌓은 줄 알았다. 진법가는 그렇게 안 본다. 간격이 같다. 높이가 셋씩 다르다. 팔문진이다. 쌓은 사람이 알았든 몰랐든.<br>
    가운데 통로가 제일 넓다. 바닥이 깨끗하다. 대걸레가 지나간 자리다.<br><br>
    넓고 깨끗한 길은 사문 자리다.`,
  o:[
    { l:'① 생문 줄을 셈해 좁은 통로로 지난다.', k:'fix', dc:21,
      ok:`쪽문 방위를 북으로 잡고 셈했다. 생문은 동북. 셋째 줄과 넷째 줄 사이, 어깨 하나 너비다.<br><br>옆걸음으로 하나씩 지났다. 소금 자루가 어깨를 긁는다. 짠 가루가 떨어진다.<br>다 지났다. 손에 소금 덩이 하나가 남았다. 터진 자루에서 굴러 나온 것이다.<br><br>생문은 늘 좁다. 좁은 대신 뭔가를 쥐여 준다.`,
      ng:`셈하는데 팔레트 하나가 반 칸 밀려 있었다. 누가 옮겼다. 생문이 반 칸 틀렸다.<br><br>상문으로 들어섰다. 자루 더미가 기울며 정강이를 덮쳤다.<br>빼내느라 살갗이 소금에 쓸려 쓰렸다.`,
      win:{ exp:18, dream:2, item:'소금 덩이' }, lose:{ hp:-26, mind:-12 } },
    { l:'② 내공을 실어 진의 눈 팔레트를 밀어낸다.', k:'break', dc:21, cost:{ qi:24 },
      ok:`진의 눈 자리 팔레트에 두 손바닥을 대고 내공을 밀었다. 한 줄이 통째로 미끄러졌다.<br><br>진이 깨지자 통로들이 다 똑같아졌다. 생문도 사문도 없다. 그냥 길이다.<br>그 길로 쪽문까지 갔다. 깨진 진은 지키지도 않고 가두지도 않는다.`,
      ng:`밀었는데 팔레트가 꿈쩍 안 했다. 내공이 소금 자루에 먹혔다. 소금은 기를 빨아들인다.<br><br>손목이 시큰하다.<br>그사이 대걸레 소리가 가까워졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'③ 넓고 깨끗한 가운데 통로로 빠진다.', k:'evade', dc:21,
      doom:{ title:'닦인 사문', what:'쏟아진 소금 자루에 깔렸습니다', dc:18, sec:45,
        text:`가운데 통로로 뛰었다. 넓다. 미끄럽다. 젖은 바닥이다.<br><br>반쯤 왔을 때 양쪽 팔레트가 한꺼번에 기울었다. 위에서부터. 사문은 들어온 것을 덮는다.<br><br>소금 자루가 쏟아진다. 어깨, 등, 머리. 짠 가루가 입에 찬다. 숨이 안 쉬어진다.`,
        dieText:`새벽에 3번 창고 가운데 통로에 소금 자루가 쌓여 있었다.<br><br>청소부가 와서 자루를 하나씩 치웠다. 서두르지 않고.<br>맨 밑 자루를 들고 고개를 끄덕였다. 수첩에 줄을 하나 그었다.` },
      ok:`가운데로 뛰었다. 넓다. 미끄럽다. 반쯤 왔을 때 양쪽 팔레트가 기우는 소리. 위에서부터.<br><br>멈추지 않고 비스듬히 꺾어 생문 쪽 틈으로 몸을 던졌다. 등 뒤로 소금 자루가 쏟아졌다.<br><br>사문을 지나는 법은 사문에서 서지 않는 것이다. 발이 그 법을 먼저 따랐다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'B2', t:'7층 — 침대 열둘의 배치',
  x:`병실에 침대가 열둘. 벽마다 셋씩. 머리가 다 가운데를 본다.<br><br>
    진법가 눈에는 배치가 보인다. 가두는 진이다. 머리를 가운데로 둔 사람은 기가 가운데로 모인다. 모인 기는 못 나간다. 그래서 다들 깊게 잔다.<br>
    진의 눈은 가운데다. 가운데 벽에 간호사실 창이 있다.<br><br>
    정각까지 십 분.`,
  o:[
    { l:'① 침대 하나를 돌려 진의 귀퉁이를 푼다.', k:'fix', dc:21, wake:1,
      ok:`이쪽 침대 바퀴 잠금쇠를 풀었다. 소리 없이 침대를 반 바퀴 돌렸다. 머리가 문 쪽을 보게.<br><br>한 귀퉁이가 풀렸다. 기가 그 귀퉁이로 샌다. 옆 침대 사람이 뒤척였다. 깨어난다. 일행 넷도 침대를 하나씩 돌렸다.<br>진이 뒤집혔다. 가두던 진이 내보내는 진이 됐다. 다섯이 가벼운 몸으로 일어나 문으로 갔다.<br><br>진은 돌을 놓아 만드는 줄 알았다. 놓인 것을 한 칸 돌려도 진이 바뀐다. 남의 진을 제 진으로 바꾸는 데 손 하나면 됐다. 손이 그 한 칸을 안다.`,
      ng:`침대를 돌리는데 바퀴가 끽 울었다. 간호사실 창에 흰 모자가 떠올랐다.<br><br>반쯤 돌린 침대 위에서 숨을 죽였다. 진은 반만 풀렸다.<br>반만 풀린 진에서 머리가 지끈거렸다. 정각까지 그 자리를 못 벗어났다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-14 } },
    { l:'② 내공을 실어 진의 눈에 기를 밀어 막는다.', k:'break', dc:21, cost:{ qi:24 },
      ok:`가운데 바닥에 손바닥을 대고 내공을 밀어 넣었다. 모이는 기가 거기서 막혔다.<br><br>막힌 기는 돌아 나간다. 다들 눈을 떴다.<br>손바닥이 뜨겁다. 진의 눈에 손을 댄 값이다.`,
      ng:`밀어 넣는데 진의 눈이 이쪽 기를 먹었다. 손바닥이 바닥에 붙는다. 머리가 가운데로 쏠린다. 졸음이 온다.<br><br>일행이 이쪽 손목을 잡아 떼어 냈다.<br>손바닥 살갗이 바닥에 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B3', t:'9호차 — 한 줄로 편 진',
  x:`열차 객차는 아홉 칸이다. 9호차에서 기관실 쪽으로 한 줄로 이어진다.<br><br>
    진법가 눈에는 이 열차가 진으로 보인다. 구궁(九宮)을 한 줄로 펴 놓은 진. 칸마다 문이 하나씩.<br>
    9호차가 휴문이다. 그다음이 생, 상, 두, 경, 사, 경, 개.<br><br>
    셈대로라면 사문은 특실이 있는 칸이다.`,
  o:[
    { l:'① 칸마다 문을 셈해 지나는 법을 일러 둔다.', k:'fix', dc:21,
      ok:`칸마다 지나는 법을 일렀다. 생문 칸에선 쉬어도 된다. 상문 칸에선 아무것도 만지지 말 것. 두문 칸에선 문을 닫고 지날 것. 사문 칸에선 서지 말 것, 뒤를 보지 말 것.<br><br>다들 외웠다. 따라 말하게 했다.<br><br>진은 놓는 것만이 아니다. 지나는 것이기도 하다. 지나는 법을 알면 남의 진도 길이다.`,
      ng:`셈하다 칸 하나를 빠뜨렸다. 침대칸을 한 칸으로 셌는데 둘이었다. 사문이 한 칸 앞으로 왔다.<br><br>사문 칸에서 쉬었다.<br>쉬는 사이 의자 하나가 이쪽으로 돌았다. 누가 앉아 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 내공을 실어 칸마다 철판의 기를 짚는다.', k:'sense', dc:21, cost:{ qi:22 },
      ok:`칸을 넘을 때마다 연결 통로 철판에 손바닥을 댔다. 내공을 실어.<br><br>기가 도는 칸은 따뜻하고 막힌 칸은 시리다. 시린 칸은 빨리, 따뜻한 칸은 천천히 지났다.<br>셈 없이 손바닥으로 진을 탔다.`,
      ng:`철판에 손을 대는데 열차가 덜컹했다. 손이 철판 이음새에 끼었다.<br><br>빼는 사이 빗물이 통로로 들이쳤다.<br>손가락 둘이 퉁퉁 부었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-12 } },
    { l:'③ 사문 칸은 지붕으로 건너뛴다.', k:'evade', dc:22,
      ok:`사문 앞 칸 끝 지붕 사다리를 탔다. 비가 얼굴을 친다. 바람이 몸을 민다.<br><br>지붕 위를 기어 사문 칸을 건넜다.<br>사문을 안 지나면 사문 법도 필요 없다. 다음 칸 앞에서 내렸다. 온몸이 젖었다.`,
      ng:`지붕 위에서 바람에 밀렸다. 몸이 미끄러져 지붕 끝에 매달렸다.<br><br>발밑 어둠이 빠르게 흘러간다.<br>손톱이 들릴 때까지 매달렸다가 겨우 기어올랐다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, spirit:-14 } }
  ] },

{ at:'B', t:'쫓기는 골목 — 반만 놓은 미혼진',
  x:`뒤쫓는 무리가 셋. 손전등 셋이 골목을 훑는다. 길을 잘 안다. 냄새 맡는 개도 하나 데리고 있다.<br><br>
    골목에 쓰레기통, 빈 상자, 부서진 우산이 굴러다닌다.<br>
    진법가는 무엇으로든 진을 놓는다. 미혼진(迷魂陣)은 길을 돌려 놓는 진이다. 사람도 개도 같은 길을 맴돌게.<br><br>
    다 놓으려면 한 시진. 남은 시간은 숨 백 번.`,
  o:[
    { l:'① 내공을 실어 반만 놓고 빈자리는 손자국으로 채운다.', k:'fix', dc:21, cost:{ qi:25 },
      ok:`쓰레기통 둘, 상자 셋을 방위대로 옮겼다. 나머지 자리에 내공을 실은 손바닥을 젖은 벽에 찍었다. 손자국도 돌이다.<br><br>숨 백 번에 진이 섰다. 손전등 셋이 골목에 들어섰다. 왼쪽으로 꺾었다가 오른쪽으로 꺾었다가 다시 골목 어귀로 나왔다.<br>개가 같은 쓰레기통 냄새를 세 번 맡았다.<br><br>다섯은 진 한가운데 상자 그늘에 앉아 비만 맞았다.`,
      ng:`손자국을 찍다가 내공이 끊겼다. 손자국 둘이 비었다. 진에 구멍이 났다.<br><br>개가 그 구멍으로 코를 들이밀었다. 짖었다.<br>뛰었다. 상자를 넘다 발목을 접질렸다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 진은 버리고 생문 방위로 뛴다.', k:'evade', dc:20,
      ok:`진을 놓을 시간에 생문 방위로 뛰었다. 빗물이 흘러 나가는 쪽.<br><br>손전등 셋이 반대쪽 골목을 훑는다.<br>진은 못 놓았다. 방위는 놓았다. 반 몫이다.`,
      ng:`생문 방위로 뛰었는데 그 골목 끝에 개가 먼저 와 있었다. 개는 방위를 모른다. 냄새만 안다.<br><br>바짓단을 물렸다.<br>찢고 뛰었다. 종아리에 이빨 자국이 남았다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B', t:'막다른 마당 — 걷는 오각',
  x:`막다른 마당이다. 사방에서 손전등이 들어온다. 넷, 다섯. 다섯 방향.<br><br>
    돌도 가지도 놓을 시간이 없다. 있는 것은 사람 다섯.<br>
    진법가는 사람도 진의 돌로 본다. 다섯이면 오각. 오각진은 기가 한 바퀴 돌며 빈틈을 지운다.<br><br>
    빈틈이 없는 무리 앞에서는 덤비기 전에 잰다. 재는 동안이 시간이다.`,
  o:[
    { l:'① 내공을 실어 다섯을 오각으로 세우고 기를 돌린다.', k:'fix', dc:22, cost:{ qi:24 }, wake:1,
      ok:`다섯을 오각으로 세웠다. 등을 안쪽으로. 손을 옆 사람 손목에. 이쪽이 먼저 숨을 쉬고 내공을 옆으로 넘겼다.<br><br>기가 손목을 타고 한 바퀴 돌았다. 두 바퀴째에 다섯이 같은 숨을 쉬었다. 손전등 다섯이 오각 둘레에서 섰다. 들어올 틈을 찾는다. 틈이 돈다. 찾을 때마다 다른 데로 간다.<br>한참 재다가 손전등 하나가 물러섰다. 그 자리가 생문이 됐다. 다섯이 오각 그대로 그 자리로 빠졌다.<br><br>사람으로 진을 놓은 적은 있다. 진을 세운 채로 걸은 건 처음이다. 진이 다리를 얻었다. 발이 그 걸음을 안다.`,
      ng:`기를 넘기는데 셋째가 손을 놓았다. 겁이 나서 손전등 쪽을 봤다. 기가 거기서 끊겼다.<br><br>끊긴 자리로 손전등이 들어왔다. 셋째 앞에 이쪽이 섰다.<br>곤봉이 어깨를 쳤다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-12 } },
    { l:'② 벽을 등지고 반원으로 선다.', k:'steady', dc:21,
      ok:`다섯이 벽을 등지고 반원으로 섰다. 뒤가 없다. 앞만 있다.<br><br>손전등 다섯이 반원 앞에서 머뭇거린다. 벽도 진의 한쪽이다. 벽이 반을 맡았다.<br>손전등 하나가 꺼진 틈에 벽을 따라 빠졌다.`,
      ng:`벽을 등지고 섰는데 벽 위에서 소리가 났다. 지붕이다. 누가 내려다본다.<br><br>뒤가 없는 게 아니라 위가 있었다.<br>흩어져 뛰었다. 다시 모이는 데 다섯 골목을 돌았다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-24, spirit:-16 } }
  ] },

{ at:'B1', t:'야적장 — 쌓은 순서',
  x:`컨테이너가 너덧 층으로 쌓여 골목을 만든다. 골목은 똑바르지 않다. 쌓은 순서대로 꺾인다.<br><br>
    진법가는 쌓은 것을 보면 쌓은 순서를 본다. 먼저 놓은 것이 아래고, 아래가 진의 뿌리다.<br>
    뿌리 줄을 따라가면 처음 쌓은 사람이 서 있던 자리가 나온다.<br><br>
    탐조등이 위를 훑는다.`,
  o:[
    { l:'① 맨 아래 칸 색을 따라 뿌리 줄을 탄다.', k:'fix', dc:21,
      ok:`맨 아래 칸 컨테이너는 다 녹슨 붉은색이다. 그 위로 파랑, 초록. 붉은 것만 따라 꺾었다.<br><br>붉은 줄은 크레인 레일과 엇갈리게 놓였다. 처음 쌓은 사람이 크레인을 피해서 쌓았다.<br>탐조등이 붉은 줄 위로는 안 온다. 크레인 기둥이 가린다.<br><br>다섯이 붉은 줄을 따라 야적장을 빠져나왔다. 진의 뿌리는 늘 제일 오래된 것이다.`,
      ng:`붉은 것을 따라가는데 붉은 칠을 새로 한 컨테이너가 끼어 있었다. 녹이 아니라 페인트다. 뿌리가 아니다.<br><br>그 줄은 크레인 밑으로 이어졌다. 탐조등이 내리꽂혔다.<br>컨테이너 틈으로 숨다 어깨가 찢겼다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 내공을 실어 컨테이너 걸쇠를 끊고 가로지른다.', k:'break', dc:22, cost:{ qi:26 },
      ok:`앞을 막은 컨테이너 문 손잡이에 손을 얹고 내공을 실어 비틀었다. 녹슨 걸쇠가 끊어졌다.<br><br>문을 열고 컨테이너 안을 지나 반대편 문을 밀었다. 골목 하나를 통째로 건너뛰었다.<br>안에는 빈 자루와 건어물 상자. 상자 하나에서 말린 고기를 집었다.`,
      ng:`걸쇠를 비틀었는데 반대편 문이 밖에서 잠겨 있었다. 컨테이너 안에 다섯이 갇혔다.<br><br>들어온 문을 다시 여는 데 내공이 다 빠졌다.<br>철판 안에서 숨이 막혔다. 빗소리가 철판 위에서 북처럼 울렸다.`,
      win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B2', t:'비상계단 — 고리진',
  x:`계단을 내려와도 4. 또 내려와도 4. 페인트 번진 모양까지 같다.<br><br>
    진법가 눈에는 계단이 고리로 보인다. 고리진. 들어온 것을 같은 자리로 돌려보내는 진이다.<br>
    고리진은 매듭 하나로 묶인다. 매듭을 풀면 고리가 끊어진다.<br><br>
    계단 한 칸만 미끄럼 방지 고무가 새것이다.`,
  o:[
    { l:'① 새 고무 칸을 매듭으로 보고 뜯는다.', k:'fix', dc:21,
      ok:`새 고무 귀퉁이에 손톱을 넣어 뜯었다. 밑에 숯으로 그은 선이 있다. 원 하나에 점 하나. 매듭이다.<br><br>손바닥으로 문질러 지웠다. 계단 아래쪽에서 바람이 올라왔다. 처음이다.<br>한 층 내려가니 3.`,
      ng:`뜯는데 고무 밑 선이 손가락에 묻어 왔다. 지운 게 아니라 옮겼다. 손가락에 원과 점.<br><br>내려갔다. 4. 손가락을 문지르며 세 번을 더 내려갔다. 4. 4.<br>겨우 지웠을 때 다리가 후들거렸다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 내공을 실어 고리를 거꾸로 거슬러 오른다.', k:'gaze', dc:22, cost:{ qi:24 },
      doom:{ title:'거꾸로 돈 고리', what:'계단 고리 속으로 빨려 듭니다', dc:17, sec:50,
        text:`고리는 한 방향으로 돈다. 거꾸로 돌면 매듭이 풀린다. 내공을 발끝에 싣고 계단을 거슬러 올랐다.<br><br>5. 6. 7. 맞다. 8. 9. 이 건물에 9층은 없다.<br>계단이 위로 끝없이 감겨 올라간다. 내려다보면 일행이 아주 작다. 불렀다. 목소리가 안 닿는다.<br><br>발밑 계단이 이쪽 발을 당긴다. 위로.`,
        dieText:`일행은 4층에서 기다렸다. 위에서 발소리가 났다. 한 층 위에서 계속.<br><br>그 발소리는 내려오지 않았다. 한 칸씩 올라갔다.<br>다음 날 밤에도 들렸다. 계단 수를 세는 소리가.` },
      ok:`내공을 발끝에 싣고 거슬러 올랐다. 5. 6. 7. 8.<br><br>거기서 멈췄다. 이 건물에 8층은 없다. 없는 층에서 매듭이 보였다. 계단참 벽의 숫자 8이 숯으로 그은 것이다.<br>지웠다. 내려왔다. 7, 6, 5, 4, 3. 고리가 풀렸다.<br><br>일행이 3층 문 앞에서 기다리고 있었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'B3', t:'식당칸 — 빈 의자가 진의 눈',
  x:`식당칸 식탁이 여섯. 식탁마다 의자 넷. 하나만 비었다. 나머지는 다 손님이다. 아무도 이쪽을 안 본다.<br><br>
    진법가 눈에는 식탁 배치가 보인다. 여섯이 한 점을 둘러싼 진이다. 빈 의자가 그 한 점. 진의 눈이다.<br>
    진의 눈이 비면 무언가 앉으러 온다. 진은 눈을 채우려 한다.<br><br>
    통로는 그 빈 의자 옆을 지난다.`,
  o:[
    { l:'① 빈 의자에 동전 하나를 놓아 눈을 채운다.', k:'fix', dc:21, wake:1,
      ok:`주머니에서 돌 대신 쥘 것을 찾았다. 동전 하나. 빈 의자 위에 놓았다.<br><br>손님들이 한꺼번에 숨을 내쉬었다. 진의 눈이 찼다. 앉으러 올 것이 없다.<br>다섯이 빈 의자 옆을 지났다. 아무도 고개를 안 돌렸다. 통로 끝에서 돌아보니 동전이 의자 위에서 혼자 돌고 있었다.<br><br>진의 눈에는 무엇이든 놓으면 된다. 눈은 채워졌는지만 안다. 그걸 알고 나니 주머니 속 모든 것이 돌로 보인다. 손이 벌써 다음 돌을 고른다.`,
      ng:`동전을 놓는데 손님 하나가 이쪽 손목을 잡았다. 빈자리에 손을 넣는 것은 앉겠다는 뜻이다.<br><br>손님이 의자를 빼 준다. 웃는다.<br>손목을 빼느라 식탁보가 끌려 접시가 쏟아졌다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, mind:-16 } },
    { l:'② 내공을 실어 일행 숨을 돌려 떨림을 멎게 한다.', k:'steady', dc:21, cost:{ qi:22 },
      ok:`다섯이 손을 잡았다. 이쪽 내공을 넘겨 숨을 한 바퀴 돌렸다. 떨림이 멎었다.<br><br>진의 눈은 떠는 것을 끌어당긴다. 떨지 않는 다섯은 안 끌려간다.<br>빈 의자 옆을 지났다. 의자가 조금 돌았다가 멈췄다.`,
      ng:`숨을 돌리는데 넷째가 떨었다. 떨림이 진의 눈 쪽으로 기울었다.<br><br>넷째 다리가 빈 의자 쪽으로 걸어간다. 제 뜻이 아니다.<br>끌어당겨 세웠다. 넷째가 한참 울었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B', t:'지하 보일러실 — 젖은 화진',
  x:`비를 피해 지하 보일러실에 들어왔다. 보일러는 꺼졌다. 다들 젖어 떤다.<br><br>
    태울 것은 기름 먹은 걸레 몇 장. 크게 피우면 연기가 문틈으로 나간다. 연기는 들킨다.<br>
    진법가는 불도 진에 넣는다. 작은 불 둘레에 벽돌을 방위대로 놓으면 열이 벽돌에 머문다.<br><br>
    벽돌은 바닥에 굴러다닌다. 젖었다.`,
  o:[
    { l:'① 내공을 실어 벽돌 여덟을 팔방에 잇는다.', k:'heal', dc:21, cost:{ qi:22 },
      ok:`젖은 벽돌을 불 가까이 두어 말리고 하나씩 팔방에 놓았다. 손바닥으로 하나씩 이었다. 내공이 벽돌에서 벽돌로 건너간다.<br><br>불이 작아도 방이 데워졌다. 연기는 개문 방위로만 빠진다. 배관 틈이다. 문틈으로는 안 나간다.<br>다섯이 젖은 옷을 벗어 벽돌에 널었다. 한 시진 만에 말랐다.`,
      ng:`여섯째 벽돌을 잇다가 벽돌이 갈라졌다. 젖은 벽돌은 열에 터진다. 파편이 뺨을 그었다.<br><br>진이 두 방위로 샌다. 연기가 문틈으로 기었다.<br>불을 밟아 껐다. 다시 젖은 어둠이다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 연기가 빠질 길부터 낸다.', k:'sense', dc:20,
      ok:`천장 배관을 따라 바람이 빠지는 틈을 찾았다. 그 밑에 불을 붙였다.<br><br>연기가 틈으로 곧장 빠진다. 불은 작게. 다들 둘러앉았다.<br>덜 따뜻했다. 들키지는 않았다.`,
      ng:`틈을 찾았는데 그 틈이 위층 복도와 이어져 있었다. 연기가 복도로 올라갔다.<br><br>위에서 발소리가 멈췄다.<br>불을 껐다. 젖은 채로 어둠 속에서 떨었다.`,
      win:{ exp:14, dream:1, hp:5 }, lose:{ mind:-14, spirit:-14 } }
  ] },

{ at:'B', t:'젖은 냅킨 — 남이 그린 길',
  x:`술집 뒷문에서 만난 남자가 길을 그려 줬다. 젖은 냅킨에 볼펜으로. 골목 다섯, 계단 하나, 철문 하나. 돈은 안 받았다. 나중에 받겠다고.<br><br>
    진법가는 그림을 보면 배치를 본다. 골목 다섯이 팔문 중 다섯 자리에 놓였다. 생, 경, 경, 두, 그리고 마지막 철문이 사문 자리다.<br>
    남자가 몰라서 그렇게 그렸을 수도 있다. 알아서 그렇게 그렸을 수도 있다.<br><br>
    남자는 카운터 전화로 누군가와 통화한다. 이쪽을 보며.`,
  o:[
    { l:'① 그림을 진으로 읽고 거꾸로 걷는다.', k:'fix', dc:22, wake:1,
      ok:`냅킨을 뒤집어 들었다. 사문이 처음에 오고 생문이 끝에 온다. 사문부터 지나면 사문은 아직 닫혀 있지 않다. 남자가 부른 사람들이 아직 거기 없다.<br><br>철문을 먼저 지났다. 비어 있다. 거꾸로 걸어 골목 다섯을 빠져나왔다. 생문 자리에 남자가 부른 사람들이 막 도착하고 있었다. 엇갈렸다.<br><br>진은 놓기만 했다. 남이 그린 진을 뒤집어 쓴 건 처음이다. 냅킨 한 장이 판 전체였다. 남의 손으로 그린 진에서 제 길을 뽑는 눈이 생겼다.`,
      ng:`거꾸로 걸어 철문에 닿았는데 철문 앞에 이미 사람이 있었다. 처음부터 거기 있었다.<br><br>뒤집어 걸을 것까지 남자가 셈했다.<br>뛰었다. 철문 모서리에 이마가 찢겼다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 그림대로 따라간다.', k:'luck', dc:21,
      ok:`그림대로 갔다. 골목 다섯, 계단 하나. 철문 앞에 섰다. 사문 자리다.<br><br>철문이 열려 있었다. 아무도 없다. 남자는 정말로 길만 그려 줬다.<br>다음에 돈을 받으러 올 것이다. 그때 줄 것이 있으면 좋겠다.`,
      ng:`그림대로 갔다. 철문 앞에 비옷 셋. 남자가 그린 사문은 정확했다.<br><br>돌아서 뛰었다.<br>등에 무언가 날아와 맞았다. 젖은 벽돌이다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-30, spirit:-12 } },
    { l:'③ 남자를 앞에 세워 함께 간다.', k:'gaze', dc:21,
      ok:`남자에게 같이 가자고 했다. 앞에 서라고. 남자가 웃다가 굳었다.<br><br>이쪽이 냅킨 위 사문 자리를 손가락으로 짚었다. 남자가 한참 이쪽을 보다가 볼펜을 꺼냈다. 철문 자리에 줄을 긋고 옆에 작은 문 하나를 그려 줬다.<br>그 문으로 갔다. 막히지 않았다.`,
      ng:`같이 가자는데 남자가 순순히 따라나섰다. 너무 순순했다.<br><br>철문 앞에서 남자가 먼저 뛰었다. 철문 안으로. 철문이 닫혔다.<br>바깥에 남은 다섯 등 뒤로 장화 소리가 골목을 메웠다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-16 } }
  ] },

{ at:'B1', t:'경매장 — 얼음 더미의 방위',
  x:`경매장 바닥에 얼음 더미가 군데군데 쌓였다. 생선을 덮던 얼음이다. 녹은 물이 바닥으로 흐른다.<br><br>
    반대편 문으로 노란 비옷들이 들어온다. 갈고리 장대를 들고. 한 줄로.<br>
    진법가는 쌓인 것을 보면 무너뜨릴 방위를 본다. 더미 여섯 중 세 곳만 무너지면 통로 하나가 막힌다.<br><br>
    막힌 통로는 돌아가야 한다. 돌아가는 동안이 시간이다.`,
  o:[
    { l:'① 방위대로 세 더미만 무너뜨려 통로를 막는다.', k:'fix', dc:21,
      ok:`동, 남서, 북. 세 더미를 발로 차 무너뜨렸다. 얼음이 미끄러지며 한 줄로 쌓였다.<br><br>노란 비옷들이 통로 앞에서 섰다. 얼음 담이다. 장대로 찔러 보다가 돌아간다. 한 바퀴.<br>그 한 바퀴에 다섯이 반대편 하역장 문을 나섰다.<br><br>나서기 전, 무너진 얼음 틈에서 퍼덕이는 민물고기 한 마리를 주웠다.`,
      ng:`둘째 더미를 차는데 발이 얼음물에 미끄러졌다. 넘어졌다. 얼음이 이쪽 위로 무너졌다.<br><br>얼음 밑에서 기어 나오는 사이 장대 끝이 바지를 꿰었다.<br>찢고 나왔다. 허벅지에 긁힌 줄이 길게 났다.`,
      win:{ exp:18, dream:2, item:'민물고기' }, lose:{ hp:-26, mind:-14 } },
    { l:'② 내공을 실어 찬 기운을 비옷들 발밑으로 민다.', k:'steady', dc:21, cost:{ qi:24 },
      ok:`두 손바닥을 얼음 더미에 대고 내공으로 찬 기운을 밀었다. 바닥 얼음물이 비옷들 발밑에서 얼었다.<br><br>장화가 미끄러진다. 줄이 무너졌다. 서로 붙잡느라 장대가 엉켰다.<br>그 틈에 지났다. 손바닥이 얼음에 데었다. 찬 데에도 덴다.`,
      ng:`밀었는데 찬 기운이 이쪽 발밑부터 얼렸다. 기를 민 쪽도 기에 밀린다.<br><br>신발이 바닥에 붙었다. 신을 벗고 맨발로 뛰었다.<br>발바닥이 얼음에 쩍쩍 붙었다 떨어졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B2', t:'세탁실 — 증기의 길',
  x:`세탁실에 증기가 찼다. 한 걸음 앞도 안 보인다. 드럼 여섯이 웅웅 운다.<br><br>
    증기 속 어딘가에 보호사가 서 있다. 아까 봤다. 움직이지 않는다. 증기 속에서 보이는 것은 움직이는 것뿐이다.<br>
    진법가는 증기도 기로 본다. 데워진 기다. 갈 데로 간다. 문으로, 틈으로.<br><br>
    증기가 흘러가는 쪽이 열린 쪽이다.`,
  o:[
    { l:'① 증기의 흐름을 따라 개문으로 간다.', k:'fix', dc:21,
      ok:`손바닥을 펴 증기 흐름을 쟀다. 손등을 스치는 쪽이 흐르는 쪽이다. 일행을 한 줄로 세워 흐름을 따라 걸었다.<br><br>증기가 얇아지는 데에 배수구 문이 있었다. 열려 있다. 증기가 거기로 빠진다. 사람도 빠진다.<br><br>보호사는 증기가 가장 짙은 데 서 있었다. 흐름이 없는 데다. 막힌 데 서 있는 것이 지키는 쪽이다.`,
      ng:`흐름을 따라가는데 흐름이 갑자기 거꾸로 돌았다. 누가 다른 문을 열었다.<br><br>증기가 이쪽으로 밀려왔다. 뜨겁다. 얼굴과 손등이 데었다.<br>증기 너머에서 흰 반팔이 걸어 나왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 내공을 실어 증기를 보호사 쪽으로 몰아 민다.', k:'break', dc:21, cost:{ qi:24 },
      ok:`두 손을 모아 내공을 실어 증기를 밀었다. 보호사가 서 있던 쪽으로.<br><br>증기가 그쪽에 몰려 벽처럼 짙어졌다. 이쪽은 얇아졌다. 앞이 보인다.<br>문까지 열 걸음. 다 걸었다. 보호사는 증기 벽 속에서 이쪽을 못 봤다.`,
      ng:`밀었는데 증기가 너무 뜨거웠다. 손바닥이 데었다.<br><br>밀린 증기가 드럼 쪽에서 되돌아왔다. 다섯이 증기 속에서 흩어졌다.<br>서로를 부르는 소리 쪽으로 보호사가 걸었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'B3', t:'특실 복도 — 번호 없는 문',
  x:`특실 복도에 문이 일곱. 1호부터 7호. 그리고 하나 더. 번호가 없는 문.<br><br>
    진법가 눈에는 여덟 문이 팔문으로 보인다. 번호 없는 문 자리가 사문이다.<br>
    복도 끝 문이 잠겼다. 앞 칸으로 가려면 여덟 방 중 하나를 지나 맞은편 통로로 나가야 한다.<br><br>
    번호 없는 문 밑으로 빛이 샌다. 안에서 누가 걷는다.`,
  o:[
    { l:'① 사문을 지나는 법대로 번호 없는 방을 지난다.', k:'fix', dc:22,
      doom:{ title:'번호 없는 방', what:'번호 없는 방이 안으로 끌어당깁니다', dc:17, sec:50,
        text:`사문을 지나는 법이 있다. 문턱을 밟지 않는다. 숨을 참는다. 뒤를 보지 않는다.<br><br>문턱을 넘었다. 숨을 참았다. 방 안에 침대, 트렁크, 비 긋는 창. 침대에 누가 앉아 있다. 이쪽 얼굴로.<br>그것이 이쪽 목소리로 이쪽 이름을 부른다. 참은 숨이 저절로 대답하려 한다.<br><br>대답하는 순간 문이 닫혔다. 이쪽은 안에 있다.`,
        dieText:`일행은 맞은편 통로로 나갔다. 진법가가 먼저 건너가 손짓했다. 법대로.<br><br>그 진법가는 건너편에서 문턱을 밟고 섰다. 아무도 못 봤다.<br>번호 없는 방에서 이제 둘이 걷는 소리가 난다.` },
      ok:`문턱을 밟지 않고, 숨을 참고, 뒤를 보지 않았다.<br><br>방 안 침대에 이쪽 얼굴이 앉아 이쪽 이름을 부른다. 대답하지 않았다. 숨은 참는 것이다.<br>맞은편 창 옆 통로 문을 열었다. 건너편에 닿자 부르는 소리가 그쳤다. 손짓해 다들 같은 법으로 건너게 했다.<br><br>사문도 문이다. 법을 알면 열린다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 번호 순서로 셈해 생문 방을 고른다.', k:'gaze', dc:21,
      ok:`번호 없는 문을 사문에 놓고 셈했다. 생문은 3호.<br><br>3호 문을 두드렸다. 대답이 없다. 열었다. 빈 방이다. 트렁크 하나. 맞은편 창이 통로 쪽으로 열린다.<br>트렁크는 안 열었다. 안에서 무언가 두드려도. 통로로 나갔다.`,
      ng:`셈해서 3호를 열었는데 안에서 트렁크가 두드리고 있었다. 생문은 산다는 뜻이지 비었다는 뜻이 아니다.<br><br>트렁크 뚜껑이 열리려 한다. 깔고 앉아 누르는 사이 일행이 통로 창을 열었다.<br>엉덩이 밑에서 손가락이 바지를 긁었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B', t:'빈 창고 — 눈이 빈 진',
  x:`쫓기다 들어온 빈 창고다. 문은 넷. 밤새 무언가 이 창고를 지나다닌다. 바닥 먼지에 발자국이 겹겹이다.<br><br>
    진을 놓을 것이 있다. 벽돌 넷. 사람 다섯.<br>
    진법가는 늘 진 밖에 섰다. 놓은 사람이 밖에 있어야 진을 고칠 수 있다.<br><br>
    이번 진은 눈이 빈다. 눈에 놓을 것이 없다. 동전도 다 썼다.`,
  o:[
    { l:'① 내공을 실어 제가 진의 눈에 앉는다.', k:'fix', dc:22, cost:{ qi:28 }, wake:1,
      ok:`가운데 앉았다. 숨을 고르고 내공을 사방으로 펼쳤다. 벽돌 넷과 사람 넷이 이쪽에 이어졌다.<br><br>밤에 무언가 지나갔다. 문 넷을 차례로 두드렸다. 진의 가장자리를 쓸고 갔다. 안으로는 못 들어왔다.<br>새벽에 눈을 뜨니 다들 이쪽을 둘러싸고 자고 있다. 이쪽이 제일 따뜻했다.<br><br>놓는 사람이었다. 오늘은 놓인 것이 됐다. 진 안에서 보니 진이 다르다. 고칠 데가 밖에서보다 더 잘 보인다.`,
      ng:`눈에 앉았는데 사방에서 기가 몰려 들어왔다. 받아 내지 못했다. 코에서 피가 났다.<br><br>진이 흔들렸다. 문 하나가 열렸다. 무언가 들어오려 했다.<br>다들 깨어 문을 등으로 막았다. 아침까지.`,
      win:{ exp:25, dream:3, mind:6 }, lose:{ hp:-24, mind:-16 } },
    { l:'② 벽돌로 눈을 대신하고 저는 밖에서 고친다.', k:'steady', dc:21,
      ok:`벽돌 하나를 가운데 놓고 셋으로 둘레를 놓았다. 이쪽은 밖에 섰다. 밤새 진을 고치며.<br><br>무언가 지나가며 벽돌 하나를 차고 갔다. 얼른 다시 놓았다.<br>새벽까지 버텼다. 늘 하던 대로 했다. 늘 그만큼 지친다.`,
      ng:`밖에 서 있다가 그것과 눈이 마주쳤다. 진 밖에 있는 것은 진이 안 지킨다.<br><br>그것이 이쪽으로 왔다.<br>할퀸 자국이 어깨에 셋 남았다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-28, spirit:-14 } }
  ] },

{ at:'B2', t:'원무과 — 의자 일곱 줄',
  x:`원무과 대기실. 플라스틱 의자가 줄지어 있다. 아무도 안 앉았다. 의자마다 번호표 한 장.<br><br>
    진법가 눈에는 의자 줄이 배치로 보인다. 일곱 줄. 줄마다 의자 수가 다르다. 하나, 셋, 다섯, 일곱, 다섯, 셋, 하나. 한가운데로 모으는 진이다. 앉은 사람을 창구로 보낸다.<br>
    창구로 가면 이름 칸을 채워야 한다.<br><br>
    대기실 둘레에 문이 셋. 정문 쪽 하나, 비상구 둘.`,
  o:[
    { l:'① 의자 줄 끝 빈틈을 이어 생문을 찾는다.', k:'fix', dc:21,
      ok:`의자 줄 끝마다 빈틈이 있다. 끝을 이으면 바깥을 도는 선이 하나 나온다. 가운데로 모으는 진은 바깥 선이 약하다.<br><br>바깥 선을 따라 벽에 붙어 걸었다. 의자 하나 안 건드리고.<br>선이 닿는 데가 동쪽 비상구다. 생문이다. 전광판이 띵동 할 때 문을 밀었다.`,
      ng:`바깥 선을 따라 걷다가 의자 하나를 발로 건드렸다. 의자가 한 칸 돌았다. 배치가 틀어졌다.<br><br>가운데로 모이던 기가 바깥으로 튀었다. 의자 줄 전체가 끽 소리를 내며 이쪽을 향해 돌았다.<br>뛰었다. 의자 다리에 정강이가 걸렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 내공을 실어 번호표 기계의 기를 끊는다.', k:'break', dc:21, cost:{ qi:24 },
      ok:`번호표 기계 옆구리에 손바닥을 대고 내공을 밀었다. 기계 속 톱니가 멎었다.<br><br>번호표가 안 나온다. 전광판 숫자가 멈췄다. 띵동이 끊겼다. 부를 번호가 없다.<br>의자 줄이 조용해졌다. 대기실을 가로질러 정문 쪽 문으로 나갔다.`,
      ng:`밀었는데 기계가 번호표를 한꺼번에 뱉었다. 수십 장이 바닥에 깔렸다.<br><br>전광판이 그 번호를 하나씩 부른다. 빠르게. 의자들이 다 대답한다.<br>손바닥이 기계 철판에 데었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-16 } }
  ] },

{ at:'B1', t:'방파제 — 꺼진 등대',
  x:`방파제 끝 등대가 꺼졌다. 등대는 항구의 눈이다. 배들이 등대를 보고 들어오고 나간다.<br><br>
    진법가 눈에는 항구가 진으로 보인다. 부두, 창고, 야적장, 수로. 등대가 그 진의 눈이다. 눈이 꺼진 진은 아무것도 안 지킨다. 대신 아무것도 못 나간다.<br>
    방파제 위로 바람이 옆으로 친다. 비가 바늘 같다.<br><br>
    우산 하나가 꺼진 등대 밑에서 기다린다.`,
  o:[
    { l:'① 내공을 실어 등대 자리에 서서 바람을 돌린다.', k:'fix', dc:22, cost:{ qi:26 }, wake:1,
      ok:`우산을 지나쳐 등대 밑 돌 위에 섰다. 진의 눈 자리다. 숨을 고르고 내공을 사방으로 펼쳤다.<br><br>사람으로 놓는 진은 다섯이 끝인 줄 알았다. 항구 하나가 손바닥 밑에 놓였다. 옆으로 치던 바람이 한 바퀴 돌았다.<br>우산이 뒤집혔다. 처음으로. 우산 밑 얼굴이 빗속에 드러났다. 그가 우산을 바로 세우는 사이 다섯이 테트라포드 사잇길로 빠졌다.<br><br>놓은 진만 진인 줄 알았다. 이미 있는 큰 진의 눈에 서면 그 진도 잠깐 이쪽 것이 된다. 손바닥이 그 무게를 기억한다.`,
      ng:`등대 밑에 섰는데 펼친 내공을 바닷바람이 다 먹었다. 바다는 너무 크다.<br><br>휘청였다. 우산이 다가와 이쪽 팔을 잡았다. 반갑다는 듯이.<br>뿌리치느라 방파제 돌에 무릎을 찧었다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 테트라포드 사이로 내려가 파도 박을 탄다.', k:'evade', dc:21,
      ok:`방파제 아래 테트라포드로 내려갔다. 파도가 들어왔다 나간다. 나갈 때 당긴다.<br><br>파도 박을 셌다. 나가는 박에 붙고 들어오는 박에 건넜다.<br>우산의 손전등이 위를 훑는다. 아래는 안 닿는다.`,
      ng:`테트라포드 틈으로 다리가 빠졌다. 파도가 나가며 당긴다.<br><br>일행이 겨드랑이를 잡아 끌어냈다.<br>정강이가 다 갈렸다. 소금물이 상처에 스며 쓰렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, spirit:-12 } }
  ] },

{ at:'B3', t:'보일러 옆 — 붉은 압력계',
  x:`기관차 보일러 옆 압력계 바늘이 붉은 칸에 들어갔다. 화실 문틈으로 불이 하얗다. 화부가 쉬지 않고 석탄을 던진다.<br><br>
    진법가 눈에는 화실 둘레가 보인다. 석탄 더미, 물 탱크, 화실, 연통. 화진(火陣)이다. 불이 불을 부르게 놓였다. 누가 일부러.<br>
    이대로면 종착을 지나쳐 달린다. 아니면 그 전에 터진다.<br><br>
    석탄 더미가 화실 입구 옆에 산처럼 쌓였다.`,
  o:[
    { l:'① 내공을 실어 물 탱크의 찬 기운을 화실로 돌린다.', k:'fix', dc:22, cost:{ qi:28 },
      ok:`물 탱크 철판에 손바닥을 댔다. 찬 기운이 있다. 내공을 실어 그 기운을 화실 쪽으로 흘렸다.<br><br>화진에 물 한 점을 넣었다. 불이 불을 부르던 고리가 한 군데 끊겼다.<br>압력계 바늘이 붉은 칸에서 한 칸 내려왔다. 화부 삽질이 느려졌다.<br><br>화부가 이쪽을 돌아봤다. 처음으로 땀을 닦았다.`,
      ng:`찬 기운을 흘리는데 화진이 그걸 먹었다. 물 탱크가 끓기 시작했다.<br><br>증기가 터져 나왔다. 얼굴을 돌렸지만 목덜미가 데었다.<br>바늘이 한 칸 더 올라갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 석탄 더미를 방위대로 무너뜨려 화실 입구를 막는다.', k:'break', dc:21,
      doom:{ title:'무너진 석탄 산', what:'무너진 석탄 더미에 깔렸습니다', dc:18, sec:45,
        text:`석탄 더미 밑을 걷어찼다. 방위대로라면 화실 쪽으로 쏟아져 입구를 막는다.<br><br>석탄이 쏟아졌다. 화실 쪽이 아니라 이쪽으로. 열차가 덜컹 기울었다. 방위가 흔들렸다.<br><br>무릎, 허리, 가슴. 석탄이 차오른다. 젖은 석탄이 무겁다. 숨 쉴 자리가 없다.`,
        dieText:`화부는 쏟아진 석탄을 퍼서 화실에 던졌다. 쉬지 않고.<br><br>삽 끝에 무언가 걸렸다. 화부가 잠깐 멈췄다가 그것도 던졌다.<br>압력계 바늘이 한 칸 더 올라갔다.` },
      ok:`열차가 덜컹 기울 때를 기다려 석탄 더미 밑을 걷어찼다. 기울어짐까지 방위에 넣었다.<br><br>석탄이 화실 입구 쪽으로 쏟아져 문을 반쯤 덮었다.<br>화부가 삽을 들고 멍하니 섰다. 던질 석탄이 문 앞에 막혀 있다.<br><br>압력계 바늘이 붉은 칸 끝에서 멈췄다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'B', t:'지하 출구 — 철문 여덟',
  x:`마지막 갈림이다. 출구가 여덟. 다 같은 철문. 다 같은 비상등. 하나만 바깥으로 열린다.<br><br>
    진법가는 문이 여덟이면 셈부터 한다. 휴, 생, 상, 두, 경, 사, 경, 개. 바깥으로 열리는 문은 개문이다.<br>
    셈하려면 방위가 필요하다. 지하라서 빗물도 안 흐른다.<br><br>
    뒤에서 발소리가 다가온다. 숨 스무 번.`,
  o:[
    { l:'① 오늘 밤 지나온 문들을 거꾸로 셈한다.', k:'fix', dc:22,
      ok:`오늘 밤 지나온 생문, 사문, 경문을 머릿속에 다 늘어놓았다. 들어온 쪽이 휴문이었다. 첫 문이 휴문이면 이 판 전체의 방위가 나온다.<br><br>거꾸로 셈했다. 숨 열두 번. 왼쪽에서 셋째 문.<br>밀었다. 빗소리가 쏟아져 들어왔다. 바깥이다.<br><br>밤새 지나온 문이 마지막 문의 셈이었다.`,
      ng:`거꾸로 셈하는데 한 군데서 셈이 엇갈렸다. 숨 스무 번이 다 갔다.<br><br>아무 문이나 밀었다. 두문이다. 막혔다. 발소리가 등 뒤에 닿았다.<br>두 번째 문을 밀다 어깨를 붙잡혔다. 겨우 뿌리쳤다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-14 } },
    { l:'② 내공을 실어 가장 가까운 문을 밀어 연다.', k:'break', dc:22, cost:{ qi:28 },
      ok:`가장 가까운 문에 두 손바닥을 대고 내공을 밀었다. 셈 없이. 어느 문이든 기를 밀면 일단 열린다.<br><br>철문이 비틀리며 열렸다. 경문이다. 놀라는 문.<br>문 너머는 바깥으로 이어진 배수로였다. 놀라고 살았다.`,
      ng:`밀었는데 사문이었다. 문이 열리자 안에서 찬바람이 이쪽을 빨아들였다.<br><br>문틀을 잡고 버텼다. 일행이 허리를 잡아 당겼다.<br>손톱이 문틀에 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'B', t:'빗속 공터 — 걷는 진',
  x:`바깥이다. 그런데 끝이 아니다. 큰길까지 빗속 공터를 가로질러야 한다. 공터에 무언가 서성인다. 여럿이다.<br><br>
    진을 놓을 시간이 없다. 놓고 기다릴 자리도 없다. 놓은 진은 서 있다. 이쪽은 걸어야 한다.<br>
    진법가는 늘 진을 놓고 그 밖에 섰다. 진은 땅에 붙은 것이라고 배웠다.<br><br>
    다섯이 이쪽을 본다.`,
  o:[
    { l:'① 다섯을 진으로 세우고 걸음마다 방위를 새로 셈한다.', k:'fix', dc:22, wake:1,
      ok:`다섯을 세웠다. 앞에 둘, 가운데 하나, 뒤에 둘. 이쪽은 가운데. 진의 눈이자 진을 놓는 손.<br><br>걸음마다 방위를 다시 셈했다. 한 걸음에 한 번. 진이 한 걸음 옮겨 가면 생문도 한 걸음 옮겨 간다. 그 생문으로 다음 걸음을 디뎠다.<br>공터의 것들이 다가오다 비켜섰다. 진의 가장자리가 그것들을 밀었다. 큰길에 닿았다.<br><br>진은 땅에 놓는 것인 줄 알았다. 사람에게 놓는 것이다. 사람이 걸으면 진도 걷는다. 그 셈을 이제 걸으면서 한다.`,
      ng:`셋째 걸음에서 셈이 걸음을 못 따라갔다. 진이 한 걸음 늦게 섰다.<br><br>늦게 선 진의 가장자리로 무언가 손을 들이밀었다. 뒤에 선 일행 소매가 찢겼다.<br>진을 버리고 뛰었다. 큰길 앞에서 넘어져 손바닥이 찢겼다.`,
      win:{ exp:25, dream:4, spirit:6 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 늘 하던 대로 진을 놓고 밖에서 지킨다.', k:'steady', dc:21,
      ok:`공터 어귀에 돌을 놓아 작은 진을 세웠다. 넷을 그 안에 앉히고 이쪽은 밖에 섰다.<br><br>서성이던 것들이 진을 돌아 이쪽으로 왔다. 진 밖에 있는 것은 진이 안 지킨다.<br>그것들이 이쪽에 정신이 팔린 사이 넷이 진을 나서 큰길로 갔다. 이쪽은 맨 끝에 뛰었다.`,
      ng:`진을 놓는 사이 공터의 것들이 이미 둘레에 와 있었다. 놓을 시간이 모자랐다.<br><br>진은 반만 섰다.<br>반만 선 진 안에서 다섯이 떨었다. 비가 그칠 때까지.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] }

]);
